D.ClientTexts.BattlePet[162]={Description={["05f0a9fec782f039:96"]="这个淘气的南瓜想要破土而出，把你吓得屁滚尿流。向南瓜歌致敬！"},Source={["c67d612179a0f5bc:22"]="世界事件：万圣节"}}
D.ClientTexts.BattlePet[163]={Description={["fa120cc91b439562:91"]="鳄鱼的皮和肉是猎人眼中的珍宝，但这种猛兽凶残无比，且很少能被成功偷袭。"},Source={["43d8a4d880a82b6d:32"]=S[680]}}
D.ClientTexts.BattlePet[164]={Description={["828d1e8dda6e6704:71"]="毒皮和其它鳄鱼一样，除了具有超常的幽默感。"},Source={["43d8a4d880a82b6d:32"]=S[680]}}
D.ClientTexts.BattlePet[165]={Description={["61fd58136b2e69d8:65"]="阿曼尼巫医将许多牺牲者变成了青蛙。其中的某些人再也没能恢复过来。"},Source={["ebb0aacaf32861f1:28"]="掉落：森林蛙\n地区：祖阿曼"}}
D.ClientTexts.BattlePet[166]={Description={["d3f618e8a835641f:114"]="粉色雷象是一种害羞的生物，它只会出现在曾经帮助过它的，或是已醉得不省人事的人身边。"}}
D.ClientTexts.BattlePet[167]={Description={["49c5423b10310848:80"]=S[20869]}}
D.ClientTexts.BattlePet[168]={Description={["84bd9f8cbab68515:127"]="当燃烧军团入侵外域时，兰德鲁·郎绍特捐献出了这个设计用于对抗强敌。联盟和部落都接连开始了生产。"},Source={["c06c39db47f350a8:32"]="集换式卡牌：燃烧军团的进攻"}}
D.ClientTexts.BattlePet[169]={Description={["b831eaaa49a6aeb1:27"]="比真龙要安静得多。"},Source={["c06c39db47f350a8:32"]="集换式卡牌：燃烧军团的进攻"}}
D.ClientTexts.BattlePet[170]={Description={["e4a368f4e3083c5b:60"]="这只金猪以赠与同伴好运的方式，为其祖先增光添彩。"},Source={["79a4707712881b10:26"]="特殊：战友招募/猪年春节庆祝\n"}}
D.ClientTexts.BattlePet[171]={Description={["cd14987e02cc99f3:95"]="德鲁伊认为，银猪与金猪有着特殊的联结，因为这两种生物在艾泽拉斯出现的时间不谋而合。"},Source={["79a4707712881b10:26"]="特殊：战友招募/春节"}}
D.ClientTexts.BattlePet[172]={Description={["975d34e07bad2bbb:113"]="年长的萨满曾警告说，拉格纳罗斯的爪牙，火焰领主的忠实奴仆，已经赶往熔火前线了。我们得提高警惕。"}}
D.ClientTexts.BattlePet[173]={Description={["45713bd1de37e4b0:136"]="鳄鱼是在沿海水域活动的六脚两栖掠食者。考古学家认为，它们也许是从安戈洛环形山的双帆龙演变而来。"},Source={["43d8a4d880a82b6d:32"]=S[680]}}
D.ClientTexts.BattlePet[174]={Description={["40729f09dc363cea:116"]="在对鳄鱼这个物种研究了数年之后，著名钓鱼专家纳特·帕格得出了结论，鳄鱼宝宝大多无害。"},Source={["43d8a4d880a82b6d:32"]=S[680]}}
D.ClientTexts.BattlePet[175]={Description={["74bd55dddd1a3e86:69"]="凤凰之神奥的子嗣之一，这头雏鸟一出生即能飞行。"},Source={["838339ed74fe4dbe:46"]="掉落：凯尔萨斯·逐日者\n地区：魔导师平台"}}
D.ClientTexts.BattlePet[179]={Description={["b07410880f788f05:85"]="这些奇妙的小家伙，是奖励给得胜归来的英雄的，代表着勇猛与力量。"},Source={["793a29d3da5accc4:27"]="特殊：战场活动"}}
D.ClientTexts.BattlePet[180]={Description={["a338fcf2c3f78003:96"]="只有那些通过伟绩证明自己勇猛过人的英雄们，才能拥有这种神秘的蛇形生物。"},Source={["a3521f81f3ce0a70:23"]="特殊：中国竞技场活动"}}
D.ClientTexts.BattlePet[183]={Description={["5cb4afeda5632c84:84"]="神秘的灵魂商人会选择跟那些能从难驯宿主体内释放精魄的人同行。"},Source={["46d9e8c0e5ca1cd5:33"]="集换式卡牌：追捕伊利丹"}}
D.ClientTexts.BattlePet[186]={Description={["24ead9084c4c5aaf:140"]="原产自泰罗卡森林，虚空鳐只在雨季产卵。虽然一次可孵化出数百个幼崽，但只有少数能活到成年。"}}
D.ClientTexts.BattlePet[187]={Description={["028328d4710d182d:98"]="吸血蝙蝠已经被幽暗城的被遗忘者和祖阿曼的阿曼尼巨魔训练成了斥候和坐骑。"},Source={["0d530113aa84ec3c:39"]="掉落：特里斯·黯血王子\n地区：卡拉赞"}}
D.ClientTexts.BattlePet[188]={Description={["ce06803767c7bbcc:75"]="巫妖王用死亡之力将霜牙从亡者之界召回时的偶然产物。"},Source={["bdd53858010300d5:46"]="特殊：巫妖王之怒典藏版"}}
D.ClientTexts.BattlePet[189]={Description={["3d3b4fe911849bce:19"]="‘我就是正义！’"},Source={["a2535d5353c2d6b8:35"]="特殊：2008年暴雪全球邀请赛"}}
D.ClientTexts.BattlePet[190]={Description={["f404e40e6439e3e9:84"]="当它感应到附近有生物濒临死亡时，它的颅骨会发出一种刺耳的咯咯声。"}}
D.ClientTexts.BattlePet[191]={Description={["78f4cd03a219ea48:98"]="这个机器人战士是冬幕节上最受欢迎的礼物。虽然没附带电池，但火箭弹肯定是有的！"},Source={["d00fbada955d933f:28"]=S[811]}}
D.ClientTexts.BattlePet[192]={Description={["6f8a139970331bbc:74"]="小叽的外表能让人联想到更为文明的时代，那时决斗者都身穿燕尾服战斗。"},Source={["01b6ed83eeb8922c:35"]="特殊：魔兽世界/暴雪游戏通行证绑定"}}
D.ClientTexts.BattlePet[193]={Description={["552b84083910f6b7:70"]="你不会愿意在黑暗的巷路里与这只老鼠狭路相逢。或者说，在哪里都一样。"},Source={["9e3bf2780252cc6b:30"]="专业技能：钓鱼\n地区：达拉然"}}
D.ClientTexts.BattlePet[194]={Description={["422c1d6953703d6e:81"]="和鳄鱼人吉恩大部分‘神秘的卵’不同，这个卵里真的有一只活物。"},Source={["5f98136b1cc9145c:18"]=S[12325]}}
D.ClientTexts.BattlePet[195]={Description={["f73e00411c556cba:119"]="稀有的白色食虱鸟在神谕者中备受尊重。它们被视为暴雨来临，幼虫丰收以及狼獾人冬眠的预兆。"},Source={["5f98136b1cc9145c:18"]=S[12325]}}
D.ClientTexts.BattlePet[196]={Description={["ed2f602c92bd907f:92"]="这些贪吃的幼兽生长速度十分惊人，而且每天都能吞下相当于其体重两倍的生肉。"},Source={["5f98136b1cc9145c:18"]=S[12325]}}
D.ClientTexts.BattlePet[197]={Description={["28544bd8cf33bc0d:69"]="艾泽拉斯的眼镜蛇以其快速发作的毒液和迅猛的攻击而著称。"},Source={["5f98136b1cc9145c:18"]=S[12325]}}
D.ClientTexts.BattlePet[198]={Description={["27a15245ea3dae32:35"]="它大大的眼睛和时髦的滑步特别引人注目。"}}
D.ClientTexts.BattlePet[199]={Description={["8a836a5b32c79fbc:180"]="为了防止学徒们依靠魔仆来完成功课，大法师举行仪式，将能够召唤这种生物的法术书页藏在了达拉然的几处角落。"},Source={["5004ab85808c0fc4:42"]="成就：进修\n分类：综合"}}
D.ClientTexts.BattlePet[200]={Description={["b44beab79951c578:60"]="春兔象征着多产，而且它们很乐意展现这一点。"}}
D.ClientTexts.BattlePet[201]={Description={["b3b3eae427982f3b:54"]="他很谦卑，富有洞察力，要是再来上一点小红莓果酱，那味道就更美了。"},Source={["c2cfd978ad541187:26"]="世界事件：感恩节"}}
D.ClientTexts.BattlePet[202]={Description={["3543df4d54198db0:66"]="这头稀有的小熊不但天生体格娇小，而且外貌常葆青春。"},Source={["3acc95f029d9a665:55"]="成就：魔兽世界四周年\n分类：光辉事迹"}}
D.ClientTexts.BattlePet[203]={Description={["25f9cc3ae894cbd5:59"]="她喜欢朋友们的陪伴。准确地说，是七十五个朋友的陪伴。"},Source={["d36757507d192683:45"]="成就：王牌小猎人\n分类：宠物对战"}}
D.ClientTexts.BattlePet[204]={Description={["43902ceb797ee17c:44"]="只要醒着，它就不停地跳舞。多么快乐的小树啊！"}}
D.ClientTexts.BattlePet[205]={Description={["4bdf7bc607521a3f:125"]="丹莫罗的熊以它们的强壮、忠诚和英勇顽强而闻名于世。自从和矮人生活在一起后，它们凶狠的天性有所收敛。"}}
D.ClientTexts.BattlePet[206]={Description={["62efd42825a0ded7:49"]="通过回声定位的能力可感应到对手的心跳。"}}
D.ClientTexts.BattlePet[207]={Description={["5e246c8f21dea72c:95"]="性格暴躁的杜隆塔尔蝎子是一种凶猛的沙漠掠食者。它偶尔还会攻击自己的主人。"}}
D.ClientTexts.BattlePet[209]={Description={["967c89885e21061f:57"]="不同于其他的异变种类，真正的小绵羊胆子非常小。"}}
D.ClientTexts.BattlePet[210]={Description={["65ecdc97c3748c32:97"]="陆行鸟在空旷地带的移动速度无可匹敌，所以捕食者只能依靠偷袭和包围战术来捕食它们。"}}
D.ClientTexts.BattlePet[211]={Description={["33dc7520a345bf91:78"]="沙滩蟹因在海岛沙滩下过冬，而适应了北方的寒冷气候。"},Source={["56e464684b8156d1:52"]="专业技能：钓鱼\n地区：诺森德、暴风城、奥格瑞玛"}}
D.ClientTexts.BattlePet[212]={Description={["72ca08d153c0219c:79"]="受埃索达长期严重污染的影响，还需要仔细观察一段时间。"}}
D.ClientTexts.BattlePet[213]={Description={["0d607a3d17f3330a:98"]="由一名血精灵学徒制作而成，如果有人能琢磨出如何让它停下来，这把魔法扫帚就能派上很大的用场。"}}
D.ClientTexts.BattlePet[214]={Description={["d94c7f7a5d78276f:94"]="许多暴风城中的年轻人都以侍从身份加入了银色北伐军，希望有朝一日能在战斗中为圣光效命。"},Source={["34c41537a21c8242:33"]="任务：冠军诞生\n地区：冰冠冰川"}}
D.ClientTexts.BattlePet[215]={Description={["d486aa52236dd581:102"]="作为年轻侏儒的训练坐骑使用，机械鸟速度不怎么样，但它所有的魅力都来自于它的老大哥。"},Source={["289ddba4bfa05963:36"]="商人出售：莉蕾·转轴\n地区：冰冠冰川"}}
D.ClientTexts.BattlePet[216]={Description={["a22fdcc1424515f0:82"]="这些年轻的兽人力图彰显银色北伐军的种种美德——英勇、强力、正直。"},Source={["34c41537a21c8242:33"]="任务：冠军诞生\n地区：冰冠冰川"}}
D.ClientTexts.BattlePet[217]={Description={["6ef9048b6e3b35ea:73"]="莫叽姆斯是所有鱼人竞技场战士中最厉害的一个。在某段时期，也是唯一的一个。"},Source={["e09e499ace7eae59:25"]="特殊：竞技场锦标赛"}}
D.ClientTexts.BattlePet[218]={Description={["e6948254d4639b75:71"]="这宠物其实有三个。除非召唤出来，否则你不会知道出来的是什么！"}}
D.ClientTexts.BattlePet[220]={Description={["eb3fe6318c97a7ea:71"]="一个庄严的警示，记载着灭世者在改变艾泽拉斯的过程中所造成的灾难与毁灭。"},Source={["c2f15fcff4c68780:42"]="任务：铭记奥伯丁\n地区：黑海岸"}}
D.ClientTexts.BattlePet[224]={Description={["7fcf6272cb366685:78"]="许多宠物在战斗前曾嘲笑这只猫。通常它们的最后一句话就是：‘过来啊，小猫咪。’"}}
D.ClientTexts.BattlePet[225]={Description={["e465649d62915ee0:43"]="鳄鱼人是鱼人的远房表亲。"},Source={["eb109ad84f45d1f1:25"]=S[810]}}
D.ClientTexts.BattlePet[226]={Description={["c82fad9473472df5:128"]="尽管它们身材矮小，但狼獾人还是诺森德大陆上最具攻击性的物种。这通常使它们让人望而生畏。"},Source={["eb109ad84f45d1f1:25"]=S[810]}}
D.ClientTexts.BattlePet[227]={Description={["ec8bb95e66f6675d:53"]="以红蓝电解质为动力源泉的战斗机器人。"},Source={["db45ce18a3199df1:30"]="特殊：激浪促销活动"}}
D.ClientTexts.BattlePet[228]={Description={["5be9b9f3f57f098c:138"]="只有极少数鱼人能成功跨越时空障碍。还能带着玛润的先进盔甲和武器返回的则更是罕见。"},Source={["fc4bf3bcc0943a21:22"]="特殊：2009年暴雪嘉年华"}}
D.ClientTexts.BattlePet[229]={Description={["4e423f16177651a9:83"]="这条极其稀有的法力浮龙以它独特的色泽和超凡的气质饱受赞誉。"}}
D.ClientTexts.BattlePet[231]={Description={["a37b19be5be4ef49:94"]="作为幸运的象征，碧玉雕成的老虎是十分珍贵的，但驯养碧玉虎本身则更为难得。"},Source={["79a4707712881b10:26"]="特殊：战友招募/光辉事迹"}}
D.ClientTexts.BattlePet[232]={Description={["53ea37963c2029af:76"]="它们很少在成年之前离开巢穴，最喜欢对附近的刺喉龙巢穴恶作剧。"},Source={["97dde15a88d7d8cf:35"]="掉落：达尔特的卵\n地区：尘泥沼泽"}}
D.ClientTexts.BattlePet[233]={Description={["45d9c46b0b61efdc:97"]="人们对这种紫皮变种的旺盛需求，已经极大地削减了哀嚎洞穴附近的迅猛龙数量。"},Source={["8c2730ca1c441e9f:54"]="掉落：变异守护者、变异破坏者\n地区：哀嚎洞穴"}}
D.ClientTexts.BattlePet[234]={Description={["d65674ca1e873e49:108"]="这头狡诈的迅猛龙出生于诺森德的冰原。严酷的生长环境造就了它无以伦比的生存能力。"},Source={["67d77432060dd059:31"]="掉落：古达克迅猛龙\n地区：祖达克"}}
D.ClientTexts.BattlePet[235]={Description={["a6ca6cfb4a77ab5a:96"]="这个“跳跃者”塔克的后裔敏捷得令人难以置信，并可以轻松适应各种艰苦环境。"},Source={["ad2715774054772c:30"]="掉落：塔克的卵\n地区：贫瘠之地"}}
D.ClientTexts.BattlePet[236]={Description={["d79167fd47725a26:113"]="这只幼崽因拥有独特的颜色而令人艳羡不已。尽管布琳妮悉心调教，但迅猛龙凶狠的天性难改。"}}
D.ClientTexts.BattlePet[237]={Description={["01e72bdbfb641278:103"]="这些雏龙的体型比其他迅猛龙幼崽更大，能够长成极具破坏性的巨型爬行动物。"},Source={["b235bc806d653835:46"]="掉落：暴掠龙女王的卵\n地区：安戈洛环形山"}}
D.ClientTexts.BattlePet[238]={Description={["0667951f4533518a:89"]="刺喉龙的卵由刺喉雌龙严密看守。它们娇小的体格掩饰了其凶猛的天性。"},Source={["8ecfab0e05d46edf:41"]="掉落：刺喉雌龙的卵\n地区：湿地"}}
D.ClientTexts.BattlePet[239]={Description={["089aa6d12dbcff1a:94"]="拉扎什迅猛龙是丛林中最聪明的掠食者之一，并因此受到了古拉巴什巨魔的喜爱。"},Source={["972c826877360a85:63"]=S[12323]}}
D.ClientTexts.BattlePet[240]={Description={["5d3fc5ab101077dc:78"]="墨玉猎豹在夜间隐形，犹如潜行的暗影，随着黎明的到来而消失得无影无踪。"},Source={["41639cc2863cf2bb:25"]="特殊：韩国活动"}}
D.ClientTexts.BattlePet[241]={Description={["af3b64f4eaa2a741:78"]="看到这些风筝高飞在诺森德岸边的天空中，就知道附近有海象人。"},Source={["b3a4125ecf9fe905:26"]="集换式卡牌：天灾战争"}}
D.ClientTexts.BattlePet[242]={Description={["e66cd9b2a41df1b1:73"]="与人亲近又好奇心十足，这些小虎崽似乎找到了最特别的藏身之所。"},Source={["b3a4125ecf9fe905:26"]="集换式卡牌：天灾战争"}}
D.ClientTexts.BattlePet[243]={Description={["6006ac2532164c34:103"]="奥妮克希亚的雏龙，这条年轻的小龙已经决心不再重蹈父辈们的毁灭覆辙。"},Source={["dbd40291793d0fa4:55"]="成就：魔兽世界五周年\n分类：光辉事迹"}}
D.ClientTexts.BattlePet[244]={Description={["724b0a036faa427c:94"]="熔火恶犬生活在火焰之地和熔火之心，血统可追溯到首领玛格曼达。"},Source={["07054a7ca7dc0ecb:34"]="特殊：绑定电子安全令\n"}}
D.ClientTexts.BattlePet[245]={Description={["6e0aa182db22b8fb:144"]="作为蛮锤矮人赠与联盟英雄的礼物，这些幼崽是弗斯塔德和随从进入格瑞姆巴托时骑乘的狮鹫所生。"},Source={["13ced4bd7d391b10:11"]=S[16053]}}
D.ClientTexts.BattlePet[246]={Description={["0aabf4b594cba1dc:68"]="索基佐格从没把那句古老的兽人格言当回事——‘不要拉扯双足飞龙的尾巴’。"},Source={["13ced4bd7d391b10:11"]=S[16053]}}
D.ClientTexts.BattlePet[247]={Description={["2dfdd9a6d8838241:121"]="罕见的虎族成员，很多人认为（也许是谬误），其独特的颜色也许是由残存魔法或其它经历造成的。"},Source={["79a4707712881b10:26"]="特殊：战友招募/中国充值促销活动"}}
D.ClientTexts.BattlePet[248]={Description={["263dcfd63ca11181:124"]="熊猫人僧侣是大无畏的旅行同伴，不断磨练着自己的战技……除非你请他喝酒。他认为拒绝是粗鲁的行为。"},Source={["13ced4bd7d391b10:11"]=S[16053]}}
D.ClientTexts.BattlePet[249]={Description={["8b0530103acc35d7:120"]="生时，克尔苏加德背叛了肯瑞托，成立了诅咒教派。死后，他以纳克萨玛斯巫妖领主的身份效命于天灾军团。"},Source={["13ced4bd7d391b10:11"]=S[16053]}}
D.ClientTexts.BattlePet[250]={Description={["3c7e439557f200b4:47"]="虽然个头很小，但小狗们被激怒时也是很危险的。"},Source={["7e7729469afb1c6f:55"]="成就：1Q24，来的密\n分类：地下城和团队"}}
D.ClientTexts.BattlePet[251]={Description={["95ee4db8b340fdc7:79"]="这个看似‘可爱’的小家伙想和小动物玩耍。千万别让它们靠太近。"},Source={["ef4382ef188d400c:25"]="世界事件：情人节"}}
D.ClientTexts.BattlePet[253]={Description={["ec25ffe50223f484:133"]="不同于它们极具毁灭性的主人——冰霜之王埃霍恩，霜娃娃喜欢和毫无防备冒险者嬉闹，向他们丢雪球。"},Source={["dc26cc20b3a70eb3:32"]="世界事件：仲夏火焰节"}}
D.ClientTexts.BattlePet[254]={Description={["7dab4062b65c8a7d:113"]="耶比托当季最畅销的热门玩具，这个打架机器人的全新蓝色底盘让整个艾泽拉斯的孩子们为之疯狂。"}}
D.ClientTexts.BattlePet[255]={Description={["d8f047da2f6e0b33:147"]="作为世界上首屈一指的珍奇宠物收藏家，达拉然的布琳妮只会将神秘的星界灵龙奖励给那些和她一样热爱宠物的收藏家。"},Source={["5bfa92f08d00e6e5:46"]="成就：小小宠物店\n分类：宠物对战"}}
D.ClientTexts.BattlePet[256]={Description={["c55245bdf673746a:90"]="根据奥杜尔的巨大泰坦原型仿制而成，这个狂躁的小东西可决不会对它的玩具们手软。"},Source={["13ced4bd7d391b10:11"]=S[16053]}}
D.ClientTexts.BattlePet[257]={Description={["c334d6c807833619:64"]="莫叽姆斯是所有鱼人竞技场战士中最厉害的一个。也是唯一的一个。"}}
D.ClientTexts.BattlePet[258]={Description={["c0d40eca2b6e9797:78"]="人类军队中的强大火炮。雷神总是冲锋在先，撤退殿后！"},Source={["57bc2e814605d760:54"]="特殊：星际争霸2：自由之翼典藏版"}}
D.ClientTexts.BattlePet[259]={Description={["c624ce935cc9224c:95"]="与它的金色伙伴不同，蓝色小矛骑兵在戳对手眼球时，身手更加悠闲从容。"},Source={["77e6cd1812dc61d3:28"]="任务：砸蛋\n地区：海加尔山\n\n"}}
D.ClientTexts.BattlePet[260]={Description={["e73580184d426017:73"]="这小家伙由于能以迅雷不及掩耳之势猛戳眼球而臭名昭著。"},Source={["77e6cd1812dc61d3:28"]="任务：砸蛋\n地区：海加尔山\n\n"}}
D.ClientTexts.BattlePet[261]={Description={["41c6f4df438ec928:85"]="地精工程学的上佳杰作。蓝图取材于地狱火半岛的巨型魔能机甲。"},Source={["f18900d2ac976b15:22"]=S[678]}}
D.ClientTexts.BattlePet[262]={Description={["45cd84f8c4e0f7c1:108"]="严格遵守侏儒设计的优质标准，这个机械小动物对于四处奔走的寂寞工程师来说，简直堪称完美旅伴。"},Source={["f18900d2ac976b15:22"]=S[678]}}
D.ClientTexts.BattlePet[264]={Description={["5a9d5ba8829066c5:136"]="这看起来不过是某种小型灵长类动物的爪子。仔细观察后发现，这只爪子已经在奥丹姆的沙漠中被暴晒了好几个世纪。"},Source={["460985159ae8a4ac:22"]=S[679]}}
D.ClientTexts.BattlePet[265]={Description={["59bac8c883b8b88d:161"]="作为一只爱冒险的土元素，佩波逃过了碎岩之渊中饥饿的旋岩虫之口，闯过了空寂的扭曲虚空，最终被人从一个邮箱里救了出来。"},Source={["ae2098fcebc296fd:36"]="成就：石头爱好者\n分类：任务"}}
D.ClientTexts.BattlePet[266]={Description={["973cf31f5ba69ed8:100"]="你凝视她，她也凝视着你。真是太聪明了，有时她像是在琢磨如何开门。"},Source={["460985159ae8a4ac:22"]=S[679]}}
D.ClientTexts.BattlePet[267]={Description={["6a538607dd3bab40:72"]="能降低当你进入漆黑处所时，被怪物吃掉的可能性。"},Source={["8dec7b21ed634bb4:50"]="专业技能：附魔（525）\n公式：魔化灯笼"}}
D.ClientTexts.BattlePet[268]={Description={["ffb49a082700572b:145"]="万民在灭世者的阴影下战栗，他是曾经的大地守护者，也是导致艾泽拉斯分崩离析的祸首。现推出便携旅行装！"},Source={["2432b7343f38600d:37"]="特殊：大地的裂变典藏版"}}
D.ClientTexts.BattlePet[270]={Description={["d44c3c74c5ed0183:81"]="凤凰宝宝是从凤凰的灰烬中诞生的，而暗色凤凰宝宝则是从它们的阴影里生成的。"}}
D.ClientTexts.BattlePet[271]={Description={["68605bb8dadbf033:129"]="历经无数次围绕托尔巴拉德的海战，这只鸟俨然已经成一个老兵了——它之所以体态臃肿，是因为每次战后都大快朵颐尸体残骸，就是这么回事。"}}
D.ClientTexts.BattlePet[272]={Description={["b6fdd58b07e57150:67"]="当它感受到威胁时会蜷缩成一个球，它妈叫它时它也会这么做。"}}
D.ClientTexts.BattlePet[277]={Description={["780991f4c87cb3d1:95"]="发条侏儒被认为是泰坦的原创作品，有些零件小得连肉眼都看不见。"},Source={["460985159ae8a4ac:22"]=S[679]}}
D.ClientTexts.BattlePet[278]={Description={["5a1bafe93c801de6:124"]="托尔巴拉德的战斗使这种小兽变得极为罕见。结果，大量想要拥有这种宠物的爱好者令当地的狐狸数量急剧减少。"},Source={["529196e0398e8181:37"]="掉落：巴拉丁狐狸\n地区：托尔巴拉德半岛"}}
D.ClientTexts.BattlePet[279]={Description={["1faec0f96ea7ecd0:100"]="元素页岩蛛并不是真正的蜘蛛，但它们的耐受性和凶猛天性使其成为深岩之洲中的一霸。"},Source={["aa53a5a811d6aa4b:26"]="掉落：玉牙页岩蛛\n地区：深岩之洲"}}
D.ClientTexts.BattlePet[280]={Description={["c490d1e779bf19ea:98"]="公会侍从必须是大胆无畏的，因为他们要在战场上宣告他们的公会在和部落的战斗中取得了胜利。"}}
D.ClientTexts.BattlePet[281]={Description={["41bac94a3a115e5f:104"]="当一个公会通过击败联盟勇士取得足够的荣耀后，一些兽人也会通过作为公会侍从来分享这份荣耀。"}}
D.ClientTexts.BattlePet[282]={Description={["8ec29b9b4bb88592:86"]="当公会积累到足够多的财富时，英勇的士兵们也常被要求背负公会的旗帜。"}}
D.ClientTexts.BattlePet[283]={Description={["64fd77685b47a845:78"]="富有的公会对士兵有很强的吸引力，他们心甘情愿背负公会的旗帜进行战斗。"}}
D.ClientTexts.BattlePet[285]={Description={["5a432f2c32dfe965:104"]="时刻‘准备玩耍’，兰德鲁的小拆与原版几乎毫无差别。易怒且嗜睡。"},Source={["d5684380972cca31:28"]="集换式卡牌：灭世者\n"}}
D.ClientTexts.BattlePet[286]={Description={["a1ded83d282b9b10:138"]="瘟疫之地的蛆虫是巫术腐蚀和大量堆积的尸体所衍生的产物，胖虫先生更是一个特别复杂的品种。"},Source={["d7a556f9a5e5999a:55"]="世界掉落：东瘟疫之地（需要完成菲奥拉的好运符任务）"}}
D.ClientTexts.BattlePet[287]={Description={["8615d17dc102a198:85"]="这些诡异的虫子日间围绕开阔的熔岩坑飞舞，夜间则会发出烈焰般的光华。"},Source={["9064bd7b7541663e:59"]="任务：七个！对！、不是萤火虫，是火焰蜂\n地区：燃烧平原\n"}}
D.ClientTexts.BattlePet[289]={Description={["829c7cf32a49d20a:50"]="它总是缩在自己的壳里，蜗牛不都是这样的嘛！"},Source={["eb109ad84f45d1f1:25"]=S[810]}}
D.ClientTexts.BattlePet[291]={Description={["d6df7a94b5529e1b:90"]="这朵甜美的小花会用它那温暖的微笑和欢乐的歌声点亮你的生活！在对抗亡灵时还是个强大的帮手。"},Source={["bbdff3668d06df33:42"]="任务：亡者的草坪\n地区：希尔斯布莱德丘陵\n"}}
D.ClientTexts.BattlePet[292]={Description={["3ba9eb9cd2ebac59:61"]="幽冥火，火幽冥，急急如律令，浮光照人行——噢，轻弱纤羽！"},Source={["393b6f2612966c07:21"]="专业技能：附魔"}}
D.ClientTexts.BattlePet[293]={Description={["ecae1c6e3102c8f7:102"]="晶簇常被矿工们误认为稀有的宝石。最初，人们是靠它们散发出的优美振鸣声才认识到这一物种的存在的。"},Source={["2df13755406019e8:75"]="掉落：源质矿、富源质矿\n地区：深岩之洲、暮光高地、奥丹姆"}}
D.ClientTexts.BattlePet[294]={Description={["df2938e0cc695919:112"]="死亡之翼的出现把整个艾泽拉斯搅得天翻地覆，就连深居海洋的鱼人也无法免疫他的腐化影响。"},Source={["fc4bf3d4c0953a57:22"]="特殊：2010年暴雪嘉年华"}}
D.ClientTexts.BattlePet[296]={Description={["ecd4c3ec10a802e5:108"]="月夜枭兽受到了艾露恩的祝福，无论走到哪里都不忘散播自然的恩赐。这种欢乐的禽鸟总是乐于翩翩起舞。"},Source={["5dcfa0f044e4a581:20"]="游戏商城：联盟"}}
D.ClientTexts.BattlePet[297]={Description={["56021d06d414f457:57"]="召唤恐怖火焰之王的小小化身，永远都不算为时过早。"},Source={["13ced4bd7d391b10:11"]=S[16053]}}
D.ClientTexts.BattlePet[298]={Description={["7f3733d7528a3b36:66"]="月夜枭兽与众不同的咆哮声是大自然中最可怖的声音之一。"},Source={["d440a7a9049fa702:17"]="游戏商城：部落"}}
D.ClientTexts.BattlePet[301]={Description={["374f97dd191026c8:68"]="它抬头用那双乌溜溜的大眼睛望着你，仿佛在问：‘你是我妈妈么？’"},Source={["336494db63abda8a:48"]="任务：善心之举\n地区：北荆棘谷\n\n"}}
D.ClientTexts.BattlePet[302]={Description={["15780a956fb386aa:125"]="兰德鲁·郎绍特最初是怎么拥有这个小巫妖的，至今仍是个谜，可他却迫不及待地把它当成了卡牌游戏的赌注。"},Source={["d5684380972cca31:28"]="集换式卡牌：灭世者"}}
D.ClientTexts.BattlePet[303]={Description={["173d6605d573f474:79"]="艾露恩为夜刃豹赋予了银黑相间的条纹，以使它们能在月光照耀的夜晚与黑暗融为一体。"},Source={["2f448a2c34e835ad:36"]="集换式卡牌：巨龙暮光"}}
D.ClientTexts.BattlePet[306]={Description={["1a52214972a2b73a:61"]="当冬泉豹幼崽在初落的雪地里嬉戏时，是最最开心的。"}}
D.ClientTexts.BattlePet[307]={Description={["27dc656681cd527b:119"]="生于荆棘谷的茂密丛林间，不走运的小迅猛龙通常会被古拉巴什巨魔掳走，带到巨魔之城祖尔格拉布。"},Source={["3b0bc394a8f72f0d:31"]="任务：老朋友\n地区：祖尔格拉布"}}
D.ClientTexts.BattlePet[308]={Description={["afcd2085e7c27dc2:93"]="野生的泥沼游荡者极具攻击性，非常危险。可一旦被驯服，它们就会表现出极大的忠诚和依赖。"},Source={["eb109ad84f45d1f1:25"]=S[810]}}
D.ClientTexts.BattlePet[309]={Description={["2cba7d72797ba705:131"]="翼手龙的龙蛋被置于祖先的化石下孵化，使龙宝宝得以吸收祖先的凶猛和才智。"},Source={["460985159ae8a4ac:22"]=S[679]}}
D.ClientTexts.BattlePet[310]={Description={["dbfe013d8894bf6c:86"]="巫毒雕像通常会从魔精、巨魔的汗水和部族敌人的血肉中汲取能量。"},Source={["460985159ae8a4ac:22"]=S[679]}}
D.ClientTexts.BattlePet[311]={Description={["e0ecde8e0d048a09:74"]="尽管仍然略显笨拙，这只长翅膀的小狮子正在学习如何成为最棒的坐骑！"},Source={["13ced4bd7d391b10:11"]=S[16053]}}
D.ClientTexts.BattlePet[316]={Description={["f779d47b5a2a185e:154"]="还没发育成凶残的成年角鹰兽，塞纳里奥角鹰兽宝宝有着看似无害的外表，往往会让塞纳里奥议会的新成员疏于防范。"},Source={["13ced4bd7d391b10:11"]=S[16053]}}
D.ClientTexts.BattlePet[317]={Description={["0902ee4edfbe69c9:129"]="这些海加尔的幼崽在经历大地的裂变时饱受痛苦折磨。但从好的方面来看，正是这些苦难让他们学会了不畏艰险、勇敢拼搏的精神。"}}
D.ClientTexts.BattlePet[318]={Description={["2a5724b38a976656:102"]="鞭笞者原产于火焰之地的灰烬土壤中，后经由海加尔守护者的帮助，被移植到了艾泽拉斯。"}}
D.ClientTexts.BattlePet[319]={Description={["3954f53a38208275:61"]="与月亮（和这个蓬头垢面、胡子拉碴的女巫）同行，徜徉在死亡的夜晚！"}}
D.ClientTexts.BattlePet[320]={Description={["d072765edd371ceb:38"]="蓝龙军团中的传奇一员。"}}
D.ClientTexts.BattlePet[321]={Description={["477ac0bc55b8e191:83"]="箱子先前的主人曾报告说他们收集的其他宠物都消失了。"},Source={["c67d612179a0f5bc:22"]="世界事件：万圣节"}}
D.ClientTexts.BattlePet[323]={Description={["c57dfc80ec3ce925:99"]="大部分松鼠都会储藏橡实作为食物。而疯狂松鼠则是储藏橡实作为弹药。"},Source={["f63b8cab7b9bf080:41"]="成就：小宠物乐园\n分类：宠物对战"}}
D.ClientTexts.BattlePet[325]={Description={["9573dd4fa2750906:115"]="作为最珍稀的物种之一，这只卡利鸟以其灿烂的羽毛与捕捉的难度在同类中脱颖而出。"},Source={["0e8b7d258a8e905e:40"]="成就：宠物博览会\n分类：宠物对战"}}
D.ClientTexts.BattlePet[328]={Description={["4c1620b10b982894:111"]="你也许认为这条离开水的鱼是个无能的对手……等你见识到它那潜藏在防御水泡中的力量，也许就不这么想了。"},Source={["e5afc35bd220c262:32"]="集换式卡牌：潮汐王座"}}
D.ClientTexts.BattlePet[329]={Description={["cbd14ca7e6a6783c:92"]="当你与奔波尔菠萝或其它强力鱼人交战时，强烈推荐随身携带灵魂石。"},Source={["fc4bf3d5c0953a58:22"]="特殊：2011年暴雪嘉年华"}}
D.ClientTexts.BattlePet[330]={Description={["6dcf42da2ad0435b:127"]="艾泽拉斯的猴子是声名狼藉的无赖，这些暗月马戏团最最青睐的小伙伴将它们与生俱来的狡诈提升到了一个全新的境界。"}}
D.ClientTexts.BattlePet[331]={Description={["09e510ade98d3ffe:90"]="制造这些魔法气球是为了在暗月马戏团开张时哄小孩开心，这些气球永远不会失去浮性。"},Source={["df59b0027d49f335:29"]="任务：吹跑了\n地区：暴风城"}}
D.ClientTexts.BattlePet[332]={Description={["708dfaf4d1101951:93"]="真是个魔法奇迹——这些气球永远不会漏气，并且依照惯例，每批都制造九十九个。"},Source={["ccc48dcb5a5dbb10:29"]="任务：吹跑了\n地区：奥格瑞玛\n"}}
D.ClientTexts.BattlePet[333]={Description={["f4b5789a219f8c59:64"]="劣魔体现着大自然狂野的一面。温驯的十分罕见。"},Source={["4012064587dc257e:33"]="集换式卡牌：苍穹之冠"}}
D.ClientTexts.BattlePet[335]={Description={["2d80a05fd8266d3e:84"]="这个带壳的爬行动物以毫不动摇的乐天性情，捍卫着它背上的家。"}}
D.ClientTexts.BattlePet[336]={Description={["bb475ecca33e7bdf:20"]="它只是在飘来飘去……"}}
D.ClientTexts.BattlePet[337]={Description={["48c390a3c904c704:123"]="从冬天爷爷那里溜出来的小家伙，这个小元素发现自己困在了被讨厌的格林奇偷走的礼物中。"},Source={["d00fbada955d933f:28"]=S[811]}}
D.ClientTexts.BattlePet[338]={Description={["2491cb295166633a:96"]="艾泽拉斯的小朋友最喜欢的宠物之一，这个坚韧的小家伙甚至能对抗最最残暴的敌人。"}}
D.ClientTexts.BattlePet[339]={Description={["1c6fe7cb8ac24fa4:105"]="跟前辈相比，它没有地雷，没有火箭弹，但这种深受孩子们喜欢的小东西在艾泽拉斯广为流传。"}}
D.ClientTexts.BattlePet[340]={Description={["49139f687c9fe267:76"]="尽管体型微小，人们的视线却一定能捕捉到这只翻涛破浪的小海马。"},Source={["8af3989b2a84588e:37"]="专业技能：钓鱼\n地区：暗月岛"}}
D.ClientTexts.BattlePet[341]={Description={["d8fbb207cdbff0ee:116"]="这些魔法灯笼通常可以在春节上获得，它们是用来纪念艾泽拉斯的各族人民击败燃烧军团的英勇事迹。"}}
D.ClientTexts.BattlePet[342]={Description={["1425abd01d8ca315:139"]="灯笼里透出的光都代表着对先祖之魂的敬意。每逢春节期间，这些幽灵般的长老们便会将他们的智慧传承给下一代。"}}
D.ClientTexts.BattlePet[343]={Description={["62f4957cadeb5d55:89"]="这只可爱的猫咪喜欢嬉闹，但有时候它追逐的东西并不真实存在。"}}
D.ClientTexts.BattlePet[346]={Description={["1f2e18b09ce2188b:154"]="魔卒萨满因亡故祖先魂灵的庇佑而变得强大。这些邪恶的灵魂就在萨满的部族长矛里。控制了长矛，就等于控制了萨满。"},Source={["34ef327160d5d0f8:35"]="特殊：暗黑破坏神3典藏版"}}
D.ClientTexts.BattlePet[347]={Description={["3167400ba9102ec4:134"]="守护巨龙之魂据说有着多变的情绪，时而隐忍沉着，时而怪异莫测，时而多情忧郁。"},Source={["13ced4bd7d391b10:11"]=S[16053]}}
D.ClientTexts.BattlePet[348]={Description={["7593ce0035491675:29"]="时刻监视。时刻裁断。"},Source={["a59044336c3aa522:44"]="集换式卡牌：时空行者：上古之战\n"}}
D.ClientTexts.BattlePet[374]={Description={["8cee347949d56862:69"]="作为黑绵羊的后代，黑羔羊只生活在艾尔文森林里。"},Source={["41d31754e6732d89:22"]="宠物对战：艾尔文森林"}}
D.ClientTexts.BattlePet[378]={Description={["c5b0fd8627bfad7f:47"]="当你拥有两只兔子时，你恐怕很快就会得到第三只了。"},Source={["cbcbc70e877040c7:338"]="宠物对战：艾萨拉、刀锋山、晶歌森林、黑海岸、丹莫罗、暮色森林、艾尔文森林、永歌森林、菲拉斯、至高岭、希尔斯布莱德丘陵、嚎风峡湾、月光林地、海加尔山、莫高雷、纳格兰、赤脊山、银月城、银松森林、石爪山脉、暴风城、提瑞斯法林地、西瘟疫之地、西部荒野、湿地"}}
D.ClientTexts.BattlePet[379]={Description={["ed0407c7a2c0d9e4:75"]="大部分人都分不清松鼠和花栗鼠。他们也不在乎。"},Source={["f23878ee98afd3b9:459"]="宠物对战：埃门谷、灰谷、艾萨拉、刀锋山、晶歌森林、黑海岸、丹莫罗、暮色森林、尘泥沼泽、艾尔文森林、菲拉斯、吉尔尼斯、至高岭、希尔斯布莱德丘陵、嚎风峡湾、洛克莫丹、魔导师平台、月光林地、海加尔山、纳格兰、吉尔尼斯废墟、索拉查盆地、银松森林、阿兰卡峰林、暴风城、泰达希尔、泰罗卡森林、托尔巴拉德半岛、暮光高地、瓦尔莎拉、永恒之井、西瘟疫之地、西部荒野、湿地、祖阿曼"}}
D.ClientTexts.BattlePet[380]={Description={["b3b4a755348075a4:52"]="很难说清楚这家伙究竟是牙齿还是尾巴更危险。"},Source={["3acabf4ce60c7aa3:23"]=S[8957]}}
D.ClientTexts.BattlePet[381]={Description={["35dfd6d77c548098:49"]="别被这名字骗了，你绝对、永远也不该去抚摸它。"},Source={["89d39f69e54afc74:22"]="掉落：宠物补给袋\n"}}
D.ClientTexts.BattlePet[382]={Description={["5a0d487c0f7fb051:58"]="这种特殊的精灵龙在艾泽拉斯非常少见。"},Source={["87cd0eb8cd793c5f:21"]="掉落：色彩怪异的蛋\n"}}
D.ClientTexts.BattlePet[383]={Description={["b4ca905ff6a3f166:102"]="看起来像是视觉特效，但水黾确实能够在水上行走，它纤细的腿脚几乎不会踩破水面。"},Source={["0c72e4de52bf4c0f:31"]="宠物对战：锦绣谷"}}
D.ClientTexts.BattlePet[384]={Description={["732ea844fe2b019f:111"]="厚实的皮毛可以让水獭在任何环境下生存，但它特别喜欢寒冷的水域，因为那里有大量美味的鲍鱼。"}}
D.ClientTexts.BattlePet[385]={Description={["b59502ba428ef1a1:97"]="看来，即使是面临囚禁、受伤甚至死亡威胁时，老鼠依然抵抗不了奶酪的诱惑。"},Source={["36fffadee88a3707:85"]="宠物对战：暮色森林、尘泥沼泽、灰熊丘陵、莫高雷、虚空风暴、西部荒野、湿地"}}
D.ClientTexts.BattlePet[441]={Description={["a3430051c960523c:72"]="高山野兔能够在永冻层中打洞，并冬眠数周、甚至数月之久。"},Source={["9b7b2b0f19f44444:32"]="宠物对战：丹莫罗、冬泉谷"}}
D.ClientTexts.BattlePet[386]={Description={["77969a4ec95670d5:101"]="与那些住在树上的近亲不同，这些旱地松鼠喜欢在艾泽拉斯及其他大陆的平原上做窝。"},Source={["ebf6507ac2695b4f:95"]="宠物对战：阿拉希高地、莫高雷、纳格兰、北贫瘠之地、南贫瘠之地、雷霆崖、西部荒野"}}
D.ClientTexts.BattlePet[387]={Description={["c4323e5fc0dbf318:87"]="由于近期发生的事故，地精财团已禁止任何人将蛇带上飞艇了。"},Source={["e0e2e51244eb638b:187"]="宠物对战：尘泥沼泽、永歌森林、菲拉斯、幽魂之地、嚎风峡湾、洛克莫丹、纳格兰、北荆棘谷、索拉查盆地、银松森林、泰罗卡森林、西部荒野、赞加沼泽、祖达克"}}
D.ClientTexts.BattlePet[388]={Description={["63fc230dd042ddaa:82"]="这种节肢动物遍布艾泽拉斯的海滩，并努力满足着它们唯一的愿望：夹人。"},Source={["cf51ebdcc4053549:102"]="宠物对战：艾萨拉、北风苔原、嚎风峡湾、卡桑琅丛林、纳格兰（德拉诺）、暮光高地、西部荒野"}}
D.ClientTexts.BattlePet[389]={Description={["a7f9773efa4fcb69:77"]="这些小收割者会收集那些大收割者漏掉的杂草和细小谷物。"},Source={["9fe14426dced3ead:18"]="宠物对战：西部荒野"}}
D.ClientTexts.BattlePet[390]={Description={["2744ad4461eb9d19:101"]="当对着这些棕色的大眼睛时，有些猎人会感到难以扣下扳机。所以他们会从远处射击。"}}
D.ClientTexts.BattlePet[391]={Description={["57e5b63178b83072:69"]="高山短尾兔可以用令人难以置信的速度跳上陡峭的山壁。"},Source={["16bdea5f72154612:40"]="宠物对战：至高岭、赤脊山"}}
D.ClientTexts.BattlePet[392]={Description={["d7eb00f09429594d:67"]="赤脊山的老鼠个个都在村里的食品库里吃得脑满肠肥。"},Source={["99f272a8f46bd309:27"]="宠物对战：赤脊山"}}
D.ClientTexts.BattlePet[393]={Description={["9d93556492b7245f:56"]="早在我们出现之前，它们已经在此繁衍。即使我们灭亡，它们的传承仍将继续。"},Source={["6a5c64c66b6a21e3:127"]="宠物对战：燃烧平原、东瘟疫之地、戈尔隆德、冰冠冰川、钢铁码头、辛特兰、暮光高地、安戈洛环形山、湿地"}}
D.ClientTexts.BattlePet[394]={Description={["58ccc088eca992dd:118"]="“小牧羊女的羊群走丢了，也不知该去哪找它们。别管它们，它们会回……我的天呐，它们就在屋子里！”"}}
D.ClientTexts.BattlePet[395]={Description={["f060b76c29c6cd0d:89"]="人们在赤脊山活动时一定得带上头盔，因为秃鹫总把人形生物的头发看做极佳的筑巢材料。"},Source={["99f272a8f46bd309:27"]="宠物对战：赤脊山"}}
D.ClientTexts.BattlePet[396]={Description={["a02348e35763ca2a:84"]="作为暮色森林的原住民，这些八条腿的小家伙常被当成炼金药水的原料。"},Source={["e608f554dfd854f9:18"]="宠物对战：暮色森林"}}
D.ClientTexts.BattlePet[397]={Description={["f937a27ce05dbf4b:68"]="由于显然易见的原因，臭鼬是一种独居生物。"},Source={["c05e304f94636d3c:103"]="宠物对战：埃门谷、艾萨拉、秘血岛、暮色森林、吉尔尼斯、嚎风峡湾、纳格兰（德拉诺）、泰罗卡森林\n"}}
D.ClientTexts.BattlePet[398]={Description={["2709ba73497cfc3c:74"]="尽管大部分人都认为黑猫是不吉利的，可黑老鼠的风评却好得多。"},Source={["1d80df32c48aad81:124"]="宠物对战：荒芜之地、暮色森林、尘泥沼泽、东瘟疫之地、千针石林、暮光高地、西瘟疫之地、湿地\n"}}
D.ClientTexts.BattlePet[399]={Description={["c7426773b87eb540:78"]="许多年以前，人类将这些爬行动物带到了暮色森林，来削减当地的老鼠数量。"},Source={["e608f554dfd854f9:18"]="宠物对战：暮色森林"}}
D.ClientTexts.BattlePet[400]={Description={["ad559b65d5453e38:95"]="一旦寡妇幼蛛开始承担讨厌的家庭责任后，就会有大把的时间来探索暮色森林了。"},Source={["adcd7a570e48c0a4:28"]="宠物对战：暮色森林\n时间：夜晚"}}
D.ClientTexts.BattlePet[401]={Description={["5d22902916ac38c8:116"]="退去的潮水暴露了海湾蟹的栖息地以及他们躲在沙滩吞吃小生物时咔嚓起舞的响声。"},Source={["9101c4d51834e098:142"]="宠物对战：黑海岸、龙骨荒野、丹莫罗、吉尔尼斯、科赞、北荆棘谷、阿兰卡峰林、悲伤沼泽、荆棘谷海角、失落群岛"}}
D.ClientTexts.BattlePet[402]={Description={["236f4756d4ca848f:56"]="更喜欢居住在潮湿、泥泞的地区，以哀伤苔的花蜜为食。"},Source={["deb1ff60f4de925b:24"]="宠物对战：悲伤沼泽"}}
D.ClientTexts.BattlePet[403]={Description={["116f36223e2eb6f3:66"]="鹦鹉能够学舌，但很难进行有意义的对话。"},Source={["81cee93b9d1f44ae:83"]="宠物对战：北荆棘谷、悲伤沼泽、荆棘谷海角、安戈洛环形山"}}
D.ClientTexts.BattlePet[404]={Description={["d6c3381b300ac2f6:101"]="尽管大部分人都将其当做童谣的胡言乱语，但长尾地道鼠是切实存在的。"},Source={["5e713392416b5f95:78"]="宠物对战：丹莫罗、北荆棘谷、荆棘谷海角、安戈洛环形山"}}
D.ClientTexts.BattlePet[405]={Description={["646619592103d814:92"]="荆棘谷的古拉巴什巨魔经常捕捉这种强大的野兽作为宠物……或者充作肉食。"},Source={["896341b7561b639c:81"]="宠物对战：北荆棘谷、塔纳安丛林、荆棘谷海角、安戈洛环形山"}}
D.ClientTexts.BattlePet[406]={Description={["27666697001da450:109"]="一种生命力旺盛的昆虫，能够适应各种气候。这种甲虫以能够在大战方酣的战场上繁衍生息而著称。"},Source={["6c43170371537f1e:113"]="宠物对战：荒芜之地、东瘟疫之地、费伍德森林、北荆棘谷、希利苏斯、荆棘谷海角、安戈洛环形山"}}
D.ClientTexts.BattlePet[407]={Description={["b6611f6d0a73549c:82"]="这种邪恶的生物在荆棘谷的密林里编织着精巧的网。"},Source={["9f31e1f43ba55e19:84"]="宠物对战：至高岭、北荆棘谷、影月谷、荆棘谷海角"}}
D.ClientTexts.BattlePet[408]={Description={["f83c3b64eb9a699d:102"]="如果一条雌蜥蜴不在隐蔽的地方产卵，那她的卵就很有可能会被鞭尾迅猛龙吃掉。"},Source={["dc7ec7a5b5b23890:54"]="宠物对战：北荆棘谷、荆棘谷海角"}}
D.ClientTexts.BattlePet[409]={Description={["fa44347945028e96:95"]="鹦鹉最喜欢血顶巨魔们吃的新鲜小鱼。它们对干面包片并不那么感兴趣。"},Source={["db157e9f0a16b456:31"]="宠物对战：北荆棘谷"}}
D.ClientTexts.BattlePet[410]={Description={["e9b1857d0d005d90:86"]="就像码头上乱七八糟的水手一样，码头老鼠也是一种凶猛暴力的生物。"},Source={["f4765bba1584e895:60"]="宠物对战：钢铁码头、荆棘谷海角、托尔巴拉德半岛"}}
D.ClientTexts.BattlePet[411]={Description={["ba0d073186bc208a:101"]="小猩猩很快就会学会用脚在树枝上荡来荡去，并用解放出来的双手向入侵者砸东西。"},Source={["4e62b4b2760890f7:44"]="宠物对战：荆棘谷海角\n天气：雨天"}}
D.ClientTexts.BattlePet[442]={Description={["ef487d0b5c22d61c:80"]="大部分生物对环境的适应能力都及不上蟑螂的千分之一。"},Source={["2a5fa337d4ec7e9a:19"]="宠物对战：丹莫罗"}}
D.ClientTexts.BattlePet[711]={Description={["15cf61c89523e751:61"]="四方水獭近水而居，通常十分活泼友善。"},Source={["fe35bc281447888d:30"]=S[8944]}}
D.ClientTexts.BattlePet[412]={Description={["eae053b67cce0b1d:88"]="蜘蛛家族中最常见的品种，艾泽拉斯的各个角落里几乎都有这些小家伙结出的网。"},Source={["35c7d9f7dd5cdb22:532"]="宠物对战：安卡赫特：古代王国、艾卓-尼鲁布、艾萨拉、黑暗神殿、诅咒之地、达克萨隆要塞、丹莫罗、尘泥沼泽、东瘟疫之地、艾尔文森林、幽魂之地、吉尔尼斯、吉尔尼斯城、映像大厅、希尔斯布莱德丘陵、嚎风峡湾、冰冠堡垒、卡拉赞、纳克萨玛斯、奥格瑞玛、萨隆矿坑、吉尔尼斯废墟、影月谷（德拉诺）、石爪山脉、悲伤沼泽、泰达希尔、净化斯坦索姆、灵魂洪炉、辛特兰、风暴峭壁、紫罗兰监狱、提瑞斯法林地、乌特加德城堡、乌特加德之巅、冬泉谷、祖阿曼、祖达克"}}
D.ClientTexts.BattlePet[414]={Description={["630854e249ca28d5:59"]="其毒液足以杀死重量相当于其本身体重100倍的生物。"},Source={["e48ad5309d8e8907:165"]="宠物对战：刀锋山、诅咒之地、燃烧平原、东瘟疫之地、地狱火半岛、奥格瑞玛、影月谷、希利苏斯、千针石林、暮光高地"}}
D.ClientTexts.BattlePet[415]={Description={["fef13d442888318b:63"]="火甲虫以灰烬为食，喜欢高温和浓烟的味道。"},Source={["19b90e0878ab30ab:75"]="宠物对战：诅咒之地、燃烧平原、海加尔山、灼热峡谷、安戈洛环形山"}}
D.ClientTexts.BattlePet[416]={Description={["1b345c9b9469fcc2:104"]="尽管有着强有力的钳子和滴着毒液的尾巴，可这种小蝎子的噬咬才是最危险的。"},Source={["6afaf1f5cf46e374:22"]="宠物对战：诅咒之地"}}
D.ClientTexts.BattlePet[417]={Description={["5b5cd263c2dece36:66"]="根据可靠记载称，勇敢的考古学家哈里森·琼斯十分害怕这种老鼠。"},Source={["b1f5beb567f681d4:583"]="宠物对战：埃门谷、阿拉希盆地、阿拉希高地、灰谷、艾萨拉、秘血岛、晶歌森林、黑海岸、凄凉之地、达克萨隆要塞、丹莫罗、霜火岭、幽魂之地、吉尔尼斯、吉尔尼斯城、至高岭、希尔斯布莱德丘陵、嚎风峡湾、卡拉赞、洛克莫丹、纳格兰、纳克萨玛斯、吉尔尼斯废墟、血色修道院、沙塔斯城、银松森林、阿兰卡峰林、石爪山脉、暴风城、沉没的神庙、悲伤沼泽、泰罗卡森林、荆棘谷海角、净化斯坦索姆、死亡矿井、辛特兰、失落群岛、破碎大厅、紫罗兰监狱、永恒岛、提瑞斯法林地、塔纳安丛林"}}
D.ClientTexts.BattlePet[418]={Description={["e50ce7e8bab8b489:101"]="这些短命的爬虫搭乘商船来到奥格瑞玛，被这座城市的住民看成是害虫。"},Source={["d78090c8db1c1d41:91"]="宠物对战：杜隆塔尔、北荆棘谷、奥格瑞玛、悲伤沼泽、暮光高地、湿地"}}
D.ClientTexts.BattlePet[419]={Description={["0cc3832fb245445c:17"]="这是一只小青蛙。"},Source={["db17638b64b57676:162"]="宠物对战：阿拉希高地、达纳苏斯、凄凉之地、艾尔文森林、永歌森林、幽魂之地、洛克莫丹、北贫瘠之地、南贫瘠之地、悲伤沼泽、泰达希尔、赞加沼泽"}}
D.ClientTexts.BattlePet[420]={Description={["ee8b3f90d4ba753f:42"]="晚夏的夜歌是属于蛤蟆们的歌。"},Source={["624a04990cad6702:196"]="宠物对战：灰谷、杜隆塔尔、尘泥沼泽、永歌森林、费伍德森林、幽魂之地、希尔斯布莱德丘陵、嚎风峡湾、纳格兰、奥格瑞玛、银松森林、悲伤沼泽、泰达希尔、暮光高地、湿地"}}
D.ClientTexts.BattlePet[421]={Description={["f6fc913690a738bb:61"]="更喜欢居住在潮湿的热带地区，以皇血草的花蜜为食。"},Source={["dc7ec7a5b5b23890:54"]="宠物对战：北荆棘谷、荆棘谷海角"}}
D.ClientTexts.BattlePet[422]={Description={["afcfe87fde0e409a:85"]="在捕食或躲避天敌时，这种蛇可以在水面上短距离的滑行。"},Source={["deb1ff60f4de925b:24"]="宠物对战：悲伤沼泽"}}
D.ClientTexts.BattlePet[423]={Description={["f963fe2f20d0a248:79"]="这种适应力极强的节肢动物有着厚厚的甲壳，使其能够在严酷的环境下生存。"},Source={["0186222660bbf313:37"]="宠物对战：燃烧平原、灼热峡谷"}}
D.ClientTexts.BattlePet[424]={Description={["ce2a61bd10afca66:77"]="被绝大多数人所厌恶的蟑螂具有非凡的生命力，这是它们与其它物种之间的最大区别。"},Source={["2c27c055bcaa132c:271"]="宠物对战：灰谷、艾萨拉、凄凉之地、丹莫罗、暮色森林、吉尔尼斯、吉尔尼斯城、嚎风峡湾、冰冠堡垒、科赞、洛克莫丹、北荆棘谷、剃刀高地、赤脊山、石爪山脉、荆棘谷海角、净化斯坦索姆、千针石林、提瑞斯法林地\n"}}
D.ClientTexts.BattlePet[425]={Description={["4ad827be65e1b5e5:84"]="这种坏脾气的蛇生活在燃烧平原的熔火池附近。"},Source={["d23d25f556e4c80a:41"]="宠物对战：燃烧平原、影月谷"}}
D.ClientTexts.BattlePet[427]={Description={["5f120a62d8b650cd:87"]="这些蜘蛛像石头一样坚硬的甲壳使它们能够在灼热峡谷的高温中存活下来。"},Source={["bf406e340db72de5:30"]="宠物对战：灼热峡谷、塔拉多"}}
D.ClientTexts.BattlePet[428]={Description={["ce8918e7e3666a92:75"]="这些酷热的蜘蛛会把自己伪装成岩浆，混入周围的环境中。"},Source={["25c37ac10ed5f6cc:22"]="宠物对战：灼热峡谷"}}
D.ClientTexts.BattlePet[429]={Description={["4edacff2d82692db:74"]="燃烧平原的甲虫会将熔岩滚成小球，并在其冷却之后吞下它们。"},Source={["7c6ee31d9c8dae22:24"]="宠物对战：燃烧平原"}}
D.ClientTexts.BattlePet[430]={Description={["6dff12c00a904723:79"]="泰坦制造的小型自动机械同伴，用于清洁和维护他们庞大的建筑。"},Source={["5906bf69c6d27be6:35"]="宠物对战：荒芜之地、戈尔隆德、塔纳利斯"}}
D.ClientTexts.BattlePet[431]={Description={["8d2d7df525d85fbe:92"]="蛮锤矮人们在训练小狮鹫时，会让它们去捕猎暮光高地的响尾蛇。"},Source={["bdfdc8e531d2f720:44"]="宠物对战：荒芜之地、塔纳利斯、暮光高地"}}
D.ClientTexts.BattlePet[432]={Description={["417be0384970f9af:55"]="毒性不如其他蝎子那么强，但更具攻击性。"},Source={["f71fa17d8f72be92:41"]="宠物对战：荒芜之地、塔纳利斯、泰罗卡森林"}}
D.ClientTexts.BattlePet[433]={Description={["b9d2dc5148282ef2:85"]="刺蜥的颜色让它能够不着痕迹地融入希利苏斯的沙漠中去。"},Source={["6b525d5efdec6e6b:27"]="宠物对战：荒芜之地、希利苏斯"}}
D.ClientTexts.BattlePet[434]={Description={["ace358c94f00649e:72"]="当公羊低下脑袋时，就说明它要冲锋了。当然也有可能是它累了。"},Source={["00a0b508fd115759:78"]="宠物对战：阿拉希高地、希尔斯布莱德丘陵、洛克莫丹、吉尔尼斯废墟、湿地"}}
D.ClientTexts.BattlePet[437]={Description={["3d5fadbb172117c0:76"]="这些山羊靠用头撞击洛克莫丹附近的小树苗来磨练自己的战斗技巧。"},Source={["ea27c0d9dfbc4224:19"]="宠物对战：洛克莫丹"}}
D.ClientTexts.BattlePet[438]={Description={["7201cf8b984fe4d6:62"]="人们经常看到这条蛇在荒芜之地的裸露岩石上晒太阳。"},Source={["e7012d9dd58df926:18"]="宠物对战：荒芜之地"}}
D.ClientTexts.BattlePet[439]={Description={["abd908b76718118a:70"]="这些生物十分安静，只是偶尔会发出死气沉沉的绝望叹息。"},Source={["f5b69fdb31b2ab8e:39"]="宠物对战：逆风小径\n时间：清晨"}}
D.ClientTexts.BattlePet[440]={Description={["b5e08687ec23fe10:67"]="丹莫罗附近厚厚的积雪为学习捕猎的雪豹幼崽提供了保护色。"},Source={["2a5fa337d4ec7e9a:19"]="宠物对战：丹莫罗"}}
D.ClientTexts.BattlePet[443]={Description={["37bd70c4a60f0949:98"]="尽管有着田园牧歌式的生活环境，草地短尾兔在躲避追逐者时的跳跃速度十分惊人。"},Source={["53fa3d4f7a90539e:25"]="宠物对战：阿拉希高地"}}
D.ClientTexts.BattlePet[445]={Description={["cd43d2c04018bb61:92"]="小旋风最喜欢偷偷靠近毫无防备的生物，然后吹起它们的鼻孔，让它们吓一跳。"},Source={["53fa3d4f7a90539e:25"]="宠物对战：阿拉希高地"}}
D.ClientTexts.BattlePet[446]={Description={["163f2c6cb747c50b:83"]="翡翠软泥怪能在黑暗中发光，这令它们受到了在漆黑矿道中工作的工人们的欢迎。"},Source={["c80c0c41ba72e286:24"]="宠物对战：辛特兰"}}
D.ClientTexts.BattlePet[447]={Description={["6953d251abf8354c:59"]="小心有鹿出没的地方。哪怕一头小鹿都能彻底撞坏一辆地精三轮车。"},Source={["0990cbf7d93eb3be:33"]="宠物对战：艾尔文森林、泰达希尔"}}
D.ClientTexts.BattlePet[448]={Description={["393ff3d56c8b36da:66"]="一根胡萝卜、一个盒子、一根棍子和一些棉线。等上几个小时，你就能得到一只野兔了。"},Source={["2dbe81c59f22b306:48"]="宠物对战：阿拉希高地、杜隆塔尔、辛特兰"}}
D.ClientTexts.BattlePet[449]={Description={["dcde1c29f892dffe:95"]="与它们在艾泽拉斯的近亲不同，这些外域生物在刀锋山安了家。"},Source={["d995746032cd69bb:54"]="宠物对战：刀锋山、戈尔隆德、辛特兰"}}
D.ClientTexts.BattlePet[450]={Description={["57f2b21a069aa9db:89"]="这种生物更偏爱栖息在林地中。它们可以在那里安全地完成蜕变。"},Source={["6e798bf319975f7c:105"]="宠物对战：灰谷、幽魂之地、希尔斯布莱德丘陵、嚎风峡湾、辛特兰、提瑞斯法林地、塔纳安丛林"}}
D.ClientTexts.BattlePet[452]={Description={["5605bac7a587c162:115"]="根据暗夜精灵的传说，第一只红尾花栗鼠是在偷吃了一颗神圣苹果之后才变成这样的。"},Source={["c3463e8ff89660e0:66"]="宠物对战：达纳苏斯、凄凉之地、希尔斯布莱德丘陵、塔拉多、泰达希尔"}}
D.ClientTexts.BattlePet[453]={Description={["36ed6916bfefe07d:86"]="这些被感染的幼熊仍然对蜜蜂的嗡嗡声十分敏感，尽管已经尝不到蜂蜜了。"},Source={["a2bcc12d004d40e2:28"]="宠物对战：希尔斯布莱德丘陵"}}
D.ClientTexts.BattlePet[454]={Description={["74dfb9eeabe15911:87"]="就连洛丹伦的老鼠都染上了药剂师的瘟疫，开始以死者的腐肉为食。"},Source={["15f59f72b4987303:24"]="宠物对战：提瑞斯法林地"}}
D.ClientTexts.BattlePet[455]={Description={["13a6d3b93c88e91a:95"]="亡灵松鼠开始喜欢上了银松森林里生长的奇怪浆果和蘑菇。"},Source={["db97c7b8fe7945fd:26"]="宠物对战：银松森林"}}
D.ClientTexts.BattlePet[456]={Description={["07d698a51a6f7076:118"]="奇怪的是，这种鹰会用刀锋般锐利的爪子撕扯树皮来寻找下面的虫子，尽管它并不需要食物。"},Source={["a25b095cd4900667:28"]="宠物对战：西瘟疫之地"}}
D.ClientTexts.BattlePet[457]={Description={["36af564660fdce79:46"]="它能够活吞重量相当于其体重三倍的东西。"},Source={["99651b06f7d8c9f5:28"]="宠物对战：东瘟疫之地"}}
D.ClientTexts.BattlePet[458]={Description={["efbd0b64596815c9:98"]="这些小鬼魂发现它们的亡灵邻居都是糟糕的伙伴，所以它们喜欢在提瑞斯法林地里独自游荡。"},Source={["15f59f72b4987303:24"]="宠物对战：提瑞斯法林地"}}
D.ClientTexts.BattlePet[459]={Description={["22b6afc94655c7c6:98"]="经过几个世纪的驯化，这些毛茸茸的动物几乎遍及东部王国的所有人类国度。"},Source={["8e5f2e8696c17ba5:79"]="宠物对战：阿拉希高地、艾尔文森林、永歌森林、虚空风暴、银月城"}}
D.ClientTexts.BattlePet[460]={Description={["3cbe25cc2f13cb9f:72"]="小的元素树苗会长成树人，成为凶猛的森林守护者。"},Source={["71217fb93c37c030:23"]="宠物对战：永歌森林"}}
D.ClientTexts.BattlePet[461]={Description={["e9de51bce91c146b:99"]="不久前才出现在艾泽拉斯的新物种，在等待着下一阶段的进化的同时积极繁衍开来。"},Source={["5d76ea5b37f8bf1c:20"]="宠物对战：幽魂之地"}}
D.ClientTexts.BattlePet[462]={Source={["998cdb0167f2eb44:80"]="商人出售：军需官布雷泽\n地区：托尔巴拉德半岛\n声望：巴拉丁典狱官-尊敬"}}
D.ClientTexts.BattlePet[463]={Description={["28175e586b1e4a49:61"]="死去螃蟹的灵魂，渴望向那些吃了它们的鱼人复仇。"},Source={["5d76ea5b37f8bf1c:20"]="宠物对战：幽魂之地"}}
D.ClientTexts.BattlePet[464]={Description={["cf38410a3f2d1359:109"]="如果你在埃门谷附近穿上昂贵的服装，那就能轻松找到大量飞蛾了。它们完全抵挡不了高级时装的美丽诱惑。"},Source={["80714d853385b49c:23"]="宠物对战：秘蓝岛"}}
D.ClientTexts.BattlePet[465]={Description={["f89d75e9b24a144e:93"]="这些贪吃的食肉生物随着德莱尼人的空间堡垒埃索达一起来到了艾泽拉斯。"},Source={["81b8d7cef9d8f567:23"]="宠物对战：秘血岛"}}
D.ClientTexts.BattlePet[466]={Description={["9bc2d81e9405b1f9:99"]="奥格瑞玛的孩子们经常捕捉这些蜥蜴作为宠物。奥格瑞玛的大人们则常常一脚踩死它们。"},Source={["bd01d92192b16174:27"]="宠物对战：杜隆塔尔、奥格瑞玛"}}
D.ClientTexts.BattlePet[467]={Description={["c91ddfb28daf88a1:51"]="一种沙漠劫掠者，喜欢粪便集中的区域。"},Source={["32a78e54763f51ed:33"]="宠物对战：杜隆塔尔、奥格瑞玛、奥丹姆"}}
D.ClientTexts.BattlePet[468]={Description={["e90d09e60791fbf9:80"]="这些甲虫经常在杜隆塔尔那些被部落的战争机器遗弃的采石场中安家。"},Source={["3d3621656306e834:17"]="宠物对战：杜隆塔尔"}}
D.ClientTexts.BattlePet[469]={Description={["80ca0d8e505d68e3:63"]="一个神秘的物种，据说是以上古之神的混乱能量为食的。"},Source={["54f8a0bf120347d6:37"]="宠物对战：艾萨拉、深岩之洲、海加尔山"}}
D.ClientTexts.BattlePet[470]={Description={["2789f8b7011f1d4c:89"]="这些邪恶的生物被暮光之锤的黑暗魔法所扭曲，以专门吞食自己的幼崽而著称。"},Source={["d0e208927510d6cb:44"]="宠物对战：艾萨拉、深岩之洲、暮光高地"}}
D.ClientTexts.BattlePet[471]={Description={["5e8651683ee3948d:76"]="最早由一名生气的地精制造而成，专门用清晨的打鸣声来骚扰邻居。"},Source={["e6956322ca93131f:40"]="宠物对战：艾萨拉、奥格瑞玛、冬泉谷\n"}}
D.ClientTexts.BattlePet[472]={Description={["2d663cef29367f4c:127"]="尽管这一代产品被大部分人看做是4000系列的重大改进，但它们产生的热量依然是一个大问题。"},Source={["705b8657687d985e:50"]="宠物对战：艾萨拉、石爪山脉、冬泉谷\n"}}
D.ClientTexts.BattlePet[473]={Description={["69818909565d9f3c:90"]="纳迦都很害怕海龟，认为它们是不吉利的象征，并在艾萨拉的海滩上对它们敬而远之。"},Source={["61ff296e44568a3f:17"]="宠物对战：艾萨拉"}}
D.ClientTexts.BattlePet[474]={Description={["f92ec4b988d74a76:85"]="这些淘气的幼年猫科动物在贫瘠之地互相追踪，以练习捕猎技巧。"},Source={["bb6387015b48b1ac:25"]="宠物对战：北贫瘠之地"}}
D.ClientTexts.BattlePet[475]={Description={["43df5551d06cf862:99"]="长颈鹿经历了野蛮的半人马数十年来的过度捕杀，最后还是牛头人挽救了这个濒临灭绝的物种。"},Source={["d9e5c84954c76734:25"]="宠物对战：南贫瘠之地"}}
D.ClientTexts.BattlePet[476]={Description={["fa025a900bf4402b:37"]="对瞪羚，大部分人只能瞠乎其后。"},Source={["792c8ec52f0a1b78:58"]="宠物对战：凄凉之地、莫高雷、北贫瘠之地、南贫瘠之地"}}
D.ClientTexts.BattlePet[477]={Description={["46850e1eb143a0ef:121"]="莫高雷的小瞪羚很快就学会了在听到牛头人猎手的战号时逃跑。不幸的是，它们听不到好猎手的接近。"},Source={["f1913affdc63415c:17"]="宠物对战：莫高雷"}}
D.ClientTexts.BattlePet[478]={Description={["48a04b1f0f1ebdd4:59"]="更喜欢居住在凉爽的林区，以魔皇草的花蜜为食。"},Source={["478baae315df0c06:70"]="宠物对战：灰谷、达纳苏斯、凄凉之地、月光林地、海加尔山、泰达希尔"}}
D.ClientTexts.BattlePet[479]={Description={["8d8dc8eee60bd187:110"]="长时间亲近精灵魔法造成了它们违反自然规律的超长寿命。在某些小野兔身上……还出现了更奇怪的事。"},Source={["981345de5d2f816d:50"]="宠物对战：达纳苏斯、凄凉之地、海加尔山、泰达希尔"}}
D.ClientTexts.BattlePet[480]={Description={["d3082e6111c3511e:109"]="黄宝石钻孔幼蛛向来受珠宝匠人的追捧，其完好无损的甲壳可以制作成精美的戒指和手镯镶饰。"},Source={["c64db05e739872c9:27"]="宠物对战：深岩之洲、凄凉之地"}}
D.ClientTexts.BattlePet[482]={Description={["4184179dd47cb082:93"]="很久以前，海加尔山的德鲁伊们就驯服了这种生物，使它们与当地的其他生物和平共处。"},Source={["d3e7a90d72817bb2:59"]="宠物对战：刀锋山、凄凉之地、海加尔山、希利苏斯"}}
D.ClientTexts.BattlePet[483]={Description={["d05b89a8193800bb:53"]="许多学者都在质疑这到底是不是蛤蟆。"},Source={["bd7599c87d6d7a5f:31"]="宠物对战：凄凉之地、塔纳安丛林"}}
D.ClientTexts.BattlePet[484]={Description={["444b7429a2fb0bea:76"]="这种狡猾的生物在奥丹姆的地下钻洞，并靠从地下暴起来捕捉猎物。"},Source={["9405db966f46d943:41"]="宠物对战：凄凉之地、希利苏斯、塔纳利斯、奥丹姆"}}
D.ClientTexts.BattlePet[485]={Description={["b2c4e89518fbface:88"]="当这些嗜睡的小家伙不打瞌睡时，就会用它们巨大的爪子挖虫子来吃。"},Source={["644c67070c4a8562:28"]="宠物对战：凄凉之地\n时间：夜晚\n"}}
D.ClientTexts.BattlePet[486]={Description={["723935f8fe62683d:109"]="由于长着一对大耳朵，所以这种生物被称为骡子。它们还以将黑市血蓟偷运去奎尔萨拉斯而闻名。"},Source={["ff75bce98a57faea:29"]="宠物对战：石爪山脉"}}
D.ClientTexts.BattlePet[487]={Description={["f2dfe8c85f5da4f9:117"]="许多探险家都会被高山花栗鼠的可爱天性迷住，以致忽略了咬在自己冻伤的手指上的细小牙齿。"},Source={["bcd81ecfe4eda738:66"]="宠物对战：至高岭、海加尔山、石爪山脉、冬泉谷\n"}}
D.ClientTexts.BattlePet[488]={Description={["273993e3af92d4ca:85"]="勇敢的刺客有时会捕捉这些小家伙，并用它们的剧毒汁液给武器浸毒。"},Source={["ff75bce98a57faea:29"]="宠物对战：石爪山脉"}}
D.ClientTexts.BattlePet[489]={Description={["02e1fb27265e146a:108"]="这些邪恶的喷火雏龙逃出奥妮克希亚的巢穴，躲入了周边地区。与其接触时一定要保持高度警惕。"},Source={["55f2a9d517b89a2c:25"]="宠物对战：尘泥沼泽"}}
D.ClientTexts.BattlePet[491]={Description={["232898f7c9c9030e:91"]="这些凶猛野蛮的猫科动物最初是沙怒巨魔豢养的宠物，居住在塔纳利斯的沙漠中。"},Source={["dde2aa166e3933d9:17"]="宠物对战：塔纳利斯"}}
D.ClientTexts.BattlePet[492]={Description={["ecc16220b3520253:71"]="一种沙漠昆虫，靠散发一种肮脏的、类似食人魔的气味来保护自己的卵。"},Source={["dde2aa166e3933d9:17"]="宠物对战：塔纳利斯"}}
D.ClientTexts.BattlePet[493]={Description={["343bfa0a455aef6f:60"]="总在黑海岸沿海的水面下捕食。"},Source={["e4bc8b078255ea74:19"]="宠物对战：黑海岸"}}
D.ClientTexts.BattlePet[494]={Description={["ded05d05fd1328d0:95"]="这些幼虫可以通过咬合颚骨奏出渐趋复杂的节奏来自娱自乐。"},Source={["4c6fc3fbffe9c366:34"]="宠物对战：塔纳利斯\n天气：沙尘暴"}}
D.ClientTexts.BattlePet[495]={Description={["3c962405de8b7132:41"]="每一只青蛙都在等待它的王子或公主。"},Source={["13cfd2fbce664c40:19"]="宠物对战：灰谷"}}
D.ClientTexts.BattlePet[496]={Description={["9fa2576089421ad5:83"]="别让这些没有脸的家伙骗了，这些黏滑的家伙十分愤怒并且渴望战斗。"},Source={["13cfd2fbce664c40:19"]="宠物对战：灰谷"}}
D.ClientTexts.BattlePet[497]={Description={["91515340fe9a875b:79"]="就连蟑螂也抵抗不了渗漏出来的恶魔腐蚀。"},Source={["0930a50c392f5455:34"]="宠物对战：费伍德森林、影月谷"}}
D.ClientTexts.BattlePet[498]={Description={["c482042f7849dace:61"]="它们更喜欢住在腐化的林子里，以紫莲花的花蜜为食。"},Source={["b16fcd5486dab317:17"]=S[8963]}}
D.ClientTexts.BattlePet[499]={Description={["5177c0f1ad820258:38"]="有些东西脏得连老鼠都不愿碰。"},Source={["b16fcd5486dab317:17"]=S[8963]}}
D.ClientTexts.BattlePet[500]={Description={["ee2cf1957bfbbbe2:101"]="在战斗中倒下的大型地狱火残骸上偶尔会生成这些由烈焰和怒火组成的暴躁构造体。"},Source={["b16fcd5486dab317:17"]=S[8963]}}
D.ClientTexts.BattlePet[502]={Description={["aa65a1e7d8019e30:155"]="第一个发现斑点铃蛙的矮人探险家无法决定到底是以这种青蛙独特的斑纹还是奇特的求偶叫声来命名。于是她选择了两者兼备。"},Source={["9ca64d0661e26b5f:23"]="宠物对战：安戈洛环形山"}}
D.ClientTexts.BattlePet[503]={Description={["9f9bce01b3a1a582:62"]="更喜欢居住在诺达希尔的树荫之下，以风暴藤的花蜜为食。"},Source={["8576dd3f6efd81f4:44"]="宠物对战：月光林地、海加尔山、安戈洛环形山"}}
D.ClientTexts.BattlePet[504]={Description={["e6f37854cc5210f5:93"]="双帆龙会将自己的幼崽遗弃在安戈洛环形山上，让它们自生自灭。只有最强壮的小双帆龙才能存活下来。"},Source={["9ca64d0661e26b5f:23"]="宠物对战：安戈洛环形山"}}
D.ClientTexts.BattlePet[505]={Description={["19759b64feb4ef9f:100"]="虽然大部分爬行动物都喜欢晒太阳，可这些长着鳞片的野兽却喜欢沐浴艾泽拉斯的双月光辉。"},Source={["758ee3ca25d4c3a3:25"]="宠物对战：千针石林"}}
D.ClientTexts.BattlePet[506]={Description={["e8580a9673945215:90"]="这些八条腿的家伙已经在石爪山脉的阴郁悬崖下徘徊了数千年。"},Source={["ff75bce98a57faea:29"]="宠物对战：石爪山脉"}}
D.ClientTexts.BattlePet[507]={Description={["c3788c9eb67835c3:91"]="许多猫头鹰都在达纳苏斯高耸的岩石建筑上筑巢，捕杀一切进入暗夜精灵主城的害虫。"},Source={["e7b47dfb7acf781e:20"]="宠物对战：泰达希尔"}}
D.ClientTexts.BattlePet[508]={Description={["21300c48d96fc779:102"]="由于生活在长年不见阳光的环境中，黑海岸的熊有着黑色的毛皮和令人难以置信的夜视能力。"},Source={["e4bc8b078255ea74:19"]="宠物对战：黑海岸"}}
D.ClientTexts.BattlePet[509]={Description={["9bf9c30c36730e5f:82"]="这些小型元素生物会依附在大型泥泞兽的背上，搜寻美味的虫子。"},Source={["a1a32126f1735bc5:18"]="宠物对战：湿地"}}
D.ClientTexts.BattlePet[510]={Description={["7156195bb4eaa970:96"]="许多年轻的侏儒发明家都曾按照死去的心爱宠物的形象制作过机械伙伴以作为弥补。"},Source={["339c13355603d7d4:28"]="宠物对战：科赞、冬泉谷"}}
D.ClientTexts.BattlePet[511]={Description={["f8e58a1181f0a4a4:84"]="原产于艾泽拉斯的沙漠地区。这些有着超强适应能力的爬行动物可以在没有水的情况下存活数周。"},Source={["a9097d2c2a7b6fa1:24"]="宠物对战：希利苏斯、奥丹姆"}}
D.ClientTexts.BattlePet[512]={Description={["3b31d70eeffc069b:103"]="邪恶的安其拉食脑甲虫的幼体。这些小家伙比它们的父母要温顺（且安静）得多。"},Source={["11af85f9b1ce4d28:18"]="宠物对战：希利苏斯"}}
D.ClientTexts.BattlePet[513]={Description={["55381833d81ab7b8:88"]="这些小虫子发出的吱吱声可能听起来很可爱，但它们其实是在为你的死亡而尖叫。"},Source={["f1c0ffd51723fcde:31"]="宠物对战：希利苏斯\n季节：夏季"}}
D.ClientTexts.BattlePet[514]={Description={["aa5bc272d8fcf897:107"]="一个傲慢的邪兽人曾试图奴役这些生物作为私兵。现在，他的残骸依然散落在外域的各个角落。"},Source={["51c83f5e7c68f07f:27"]="宠物对战：地狱火半岛"}}
D.ClientTexts.BattlePet[515]={Description={["9d86ee423b675567:95"]="这些矮墩墩的小家伙经常会在寻找它们最爱的食物荧光菌帽时陷入麻烦。"},Source={["a697f8a24a582d7f:21"]="宠物对战：赞加沼泽"}}
D.ClientTexts.BattlePet[517]={Description={["0a069a4657131bf7:90"]="在孵化出来之后，这些扭曲的爬行动物就会吞噬较弱的同胞兄弟姐妹，以确立自己的统治地位。"},Source={["ea874ada50f1b67f:24"]="宠物对战：泰罗卡森林"}}
D.ClientTexts.BattlePet[518]={Description={["ec5186f1c1231c42:80"]="对食人魔来说，将女性的头发比喻成裂蹄牛蓬松的毛发是一种表达爱意的方法。"},Source={["0f8f9cbf9c5ada16:17"]="宠物对战：纳格兰"}}
D.ClientTexts.BattlePet[519]={Description={["ed77b1725e2c37f1:91"]="这些暴躁的小家伙是由恶魔法术缔造而成，会用邪恶能量腐化自己碰触到的一切。"},Source={["25d31b54e2d34353:39"]="宠物对战：影月谷、塔纳安丛林"}}
D.ClientTexts.BattlePet[521]={Description={["a7cda198f32f928f:95"]="成年的虚空鳐比较温顺，但它们的幼崽都是些脾气暴躁又精力充沛的小家伙。"},Source={["51f61d5f38f1fdae:21"]="宠物对战：虚空风暴"}}
D.ClientTexts.BattlePet[523]={Description={["281bba569f63924d:157"]="嚎风峡湾存在着永不停止的生命轮回。当一只生物死去时，它的尸体会很快被蛆虫消化，然后将养分依次传递给其他生物。"},Source={["ded67d319d7b4e7a:22"]=S[8943]}}
D.ClientTexts.BattlePet[525]={Description={["e032bed1e3302276:41"]="冬幕节主菜的食材。"},Source={["ded67d319d7b4e7a:22"]=S[8943]}}
D.ClientTexts.BattlePet[528]={Description={["8b69c626df8c64f5:105"]="这种暴躁的蜥蜴栖息在刀锋山上，尽可能不与其他生物接触。"},Source={["b4cbd7c9ac864da8:30"]="宠物对战：刀锋山"}}
D.ClientTexts.BattlePet[529]={Description={["ab6b89beccf93ef5:89"]="曾有一个老维库人说过：‘不要吵醒沉睡的座狼，除非你不想要自己的脸了。’"},Source={["ded67d319d7b4e7a:22"]=S[8943]}}
D.ClientTexts.BattlePet[530]={Description={["59d32608a8da5c25:107"]="这些有生命的软泥怪连最基本的智慧都欠奉，但这并不意味着你们不能交朋友。"},Source={["32dc3ba9c9ad6c76:22"]="宠物对战：北风苔原"}}
D.ClientTexts.BattlePet[532]={Description={["e3378c655d8ccf54:104"]="凶狠的狼獾人猎杀这些暴躁的凶兽以获取它们的角。随后，这些角会被雕刻成护符和其他饰品。"},Source={["5de8d5b5affe2b5a:23"]="宠物对战：索拉查盆地"}}
D.ClientTexts.BattlePet[534]={Description={["cae03c4e0a928833:87"]="牦牛人会收集这些高贵的猛禽羽毛，用于原始的预言仪式。"},Source={["a4be99bbab9b6d4a:22"]="宠物对战：灰熊丘陵"}}
D.ClientTexts.BattlePet[535]={Description={["150552bed60cf0d7:103"]="祖达克的巨魔在召唤水元素来对抗天灾军团时不小心创造出了这些小家伙。"},Source={["1e8441c8cac86351:18"]="宠物对战：祖达克"}}
D.ClientTexts.BattlePet[536]={Description={["988e99f8769314f1:171"]="苔原企鹅经常聚集在冰层上，以对抗来自水中的威胁。不幸的是，这反而使那些寻找肉食、毛皮或怀有其他目的人形猎手更容易捕杀它们。"},Source={["e054128a5e32829d:35"]="宠物对战：北风苔原、龙骨荒野"}}
D.ClientTexts.BattlePet[537]={Description={["e08ce98c3e906a69:91"]="这些鬼祟的小家伙都蛰伏在诺森德中心的古代龙骨附近的巢穴中。"},Source={["8a158f19087733aa:22"]="宠物对战：龙骨荒野"}}
D.ClientTexts.BattlePet[538]={Description={["f34899bf9938b51a:92"]="克尔苏加德曾养大过一条被瘟疫感染的雏龙，只给它喂食彻底溶解的尸体。"},Source={["f87e1e7ec1c1ad6f:18"]="宠物对战：冰冠冰川"}}
D.ClientTexts.BattlePet[539]={Description={["33168c0a76bdbb31:47"]="人们常把洞穴鼠和老鼠搞混。但这种错误绝不会再犯第二次。"},Source={["ad89eb4f143fd7ae:20"]="宠物对战：海加尔山"}}
D.ClientTexts.BattlePet[540]={Description={["09a82fbe3b434541:42"]="哪里有腐肉，哪里就有老鼠。"},Source={["ad89eb4f143fd7ae:20"]="宠物对战：海加尔山"}}
D.ClientTexts.BattlePet[541]={Description={["ed4db4367b0d6b4d:148"]="蟑螂卵的外壳保护了幼虫不被烧成灰烬。在孵化过程中，它们就获得了抵抗火山地带的火焰与高温的能力。"},Source={["2afde2da56db9083:35"]="宠物对战：霜火岭、海加尔山"}}
D.ClientTexts.BattlePet[542]={Description={["ff0949700dce38d9:49"]="色彩艳丽，而且比大部分青蛙更有活力。"},Source={["dc90c64b47147222:15"]=S[8946]}}
D.ClientTexts.BattlePet[543]={Description={["75856afdc775053e:61"]="当蝗虫过境时，一切声响都会被它们挥动翅膀的声音淹没。"},Source={["dc90c64b47147222:15"]=S[8946]}}
D.ClientTexts.BattlePet[544]={Description={["4b7cd02fee0c8050:77"]="更喜欢居住在沙漠中的溪流、水井或水坑附近，以鞭尾草的花蜜为食。"},Source={["dc90c64b47147222:15"]=S[8946]}}
D.ClientTexts.BattlePet[545]={Description={["bc8fda19e699916e:63"]="最喜欢在晚上躲进没有防备的旅行者的鞋子里。"},Source={["dc90c64b47147222:15"]=S[8946]}}
D.ClientTexts.BattlePet[546]={Description={["a353ac1a5e47d60b:112"]="这种食腐甲虫经常成群结队地出现在古代地下墓穴中，它们可以在不进食的情况下存活很久。"},Source={["dc90c64b47147222:15"]=S[8946]}}
D.ClientTexts.BattlePet[547]={Description={["d7d86e33a74bca88:82"]="在第三次大战期间，数以千计的这种神秘生物战胜了恶魔领主阿克蒙德。"},Source={["ad89eb4f143fd7ae:20"]="宠物对战：海加尔山"}}
D.ClientTexts.BattlePet[548]={Description={["f1e3ee8681172029:52"]="这家伙因为胆小所以一直不敢飞，直到被人从很高的地方扔下来之后才学会。"},Source={["a8e3d122150c80f3:27"]=S[8952]}}
D.ClientTexts.BattlePet[549]={Description={["4710b2a4da25d451:102"]="与它们那些住在平原上的近亲不同，这些小家伙栖息在兵连祸结的暮光高地。"},Source={["a8e3d122150c80f3:27"]=S[8952]}}
D.ClientTexts.BattlePet[550]={Description={["943c0504f959f9b7:108"]="高地的老鼠可能也被暮光之锤所扭曲了，它们极具攻击性而且会为了首领的地位而自相残杀。"},Source={["a8e3d122150c80f3:27"]=S[8952]}}
D.ClientTexts.BattlePet[552]={Description={["630bcd451d6f028c:115"]="仿佛是为了证明做点小坏事有益身心一般，这种小恶魔用它们剃刀般锋利的牙齿和张大的嘴吞吃着一切阻挡它们的东西。"},Source={["a8e3d122150c80f3:27"]=S[8952]}}
D.ClientTexts.BattlePet[553]={Description={["7987d38ae00e1c65:59"]="在漂泊于海上的困窘日子里，看到一只老鼠都能令人欣喜万分。"},Source={["f60f30f2e070ba97:18"]=S[8953]}}
D.ClientTexts.BattlePet[554]={Description={["403a29263bcbd42f:149"]="经过试验，达拉然的法师们发现赤红页岩蜘蛛体内残留的能量能够极大地催发火焰法术的燃烧程度。"},Source={["f60f30f2e070ba97:18"]=S[8953]}}
D.ClientTexts.BattlePet[555]={Description={["d5224203ee96d9f6:65"]="深岩之洲的蟑螂会自己在岩石上打洞筑巢。"},Source={["f60f30f2e070ba97:18"]=S[8953]}}
D.ClientTexts.BattlePet[556]={Description={["c4b015d4ffed0bf7:96"]="作为暮光甲虫的近亲，这种昆虫学会了以能够与古代能量共鸣的水晶为食。"},Source={["f60f30f2e070ba97:18"]=S[8953]}}
D.ClientTexts.BattlePet[557]={Description={["8dfd5f10ea31f8f3:95"]="和其他精灵龙一样，这些淘气又神秘的飞行生物诞生于自然与魔法的对抗之中。"},Source={["b1d041821d46cacd:17"]="宠物对战：菲拉斯"}}
D.ClientTexts.BattlePet[558]={Description={["80b6b257d50b78b4:87"]="在风暴峭壁的寒冷夜间，这些小家伙会将自己毛茸茸的尾巴当成保暖的毯子。"},Source={["d5fdf65f2a96f682:35"]="宠物对战：风暴峭壁\n天气：雪天"}}
D.ClientTexts.BattlePet[559]={Description={["be0d85a2b887f6e5:90"]="在蔚蓝狂潮横扫深岩之洲前，塞拉赞恩曾将这些生气勃勃的红色元素生物当做首饰佩戴。"},Source={["f60f30f2e070ba97:18"]=S[8953]}}
D.ClientTexts.BattlePet[560]={Description={["186d3d56b3617fcb:52"]="作为海滩清道夫，海鸥常出没于码头附近。"},Source={["931b905c0583dec3:50"]="宠物对战：霜寒晶壁、卡桑琅丛林、塔拉多、塔纳利斯"}}
D.ClientTexts.BattlePet[562]={Description={["176a7e1be195ee5c:79"]="珊瑚毒蛇的毒液具有致命的杀伤力，咬上一口就足以让一只成年科多兽毙命。"},Source={["3acabf4ce60c7aa3:23"]=S[8958]}}
D.ClientTexts.BattlePet[564]={Description={["002b7979e897b07a:106"]="很难相信，承载着整个迷踪岛的神真子就是由一只小小的翡翠乌龟长成的。"},Source={["3acabf4ce60c7aa3:23"]=S[8957]}}
D.ClientTexts.BattlePet[565]={Description={["c20711963eafe9f3:71"]="在丛林中，每一片叶子下都藏着一只青蛙。可当你停下来寻找时，它们可能早就已经逃走了。"},Source={["3acabf4ce60c7aa3:23"]=S[8957]}}
D.ClientTexts.BattlePet[566]={Description={["e3f5fafb4294448a:126"]="在准备出远门之前，熊猫人都会按照传统捕捉一只明镜水黾然后将其安全放入其他水域。"},Source={["3acabf4ce60c7aa3:23"]=S[8957]}}
D.ClientTexts.BattlePet[567]={Description={["4d35c3be0e5f168b:91"]="翡翠林的熊猫人认为这些爬行动物是高贵的青龙玉珑的远亲。"},Source={["3acabf4ce60c7aa3:23"]=S[8957]}}
D.ClientTexts.BattlePet[568]={Description={["84fc8a7e3050a07f:39"]="躲在壳里以躲避附近螃蟹的钳子。"},Source={["98c1ec23064c13b2:53"]="宠物对战：戈尔隆德、阿兰卡峰林、塔拉多、翡翠林"}}
D.ClientTexts.BattlePet[569]={Description={["decc19cf545826d4:86"]="作为园艺师眼中的几大古怪害虫之一，花园蛙会对花园造成难以言喻的损害。"},Source={["e06c7541ce451a84:43"]="宠物对战：阿苏纳、至高岭、翡翠林"}}
D.ClientTexts.BattlePet[570]={Description={["5035844b305c1958:115"]="人们关于狸猫到底是浣熊还是狗曾有过激烈争论，但当它们啃咬你的腿骨时，这些差别似乎都变得无关紧要了。"},Source={["3acabf4ce60c7aa3:23"]=S[8957]}}
D.ClientTexts.BattlePet[571]={Description={["dfcca249619fe3c2:84"]="翡翠林的山地猢狲很怕这些剧毒的爬行动物，常常出于纯粹的厌恶而去捕杀它们。"},Source={["3acabf4ce60c7aa3:23"]=S[8957]}}
D.ClientTexts.BattlePet[572]={Description={["548e8460ac151ca5:79"]="这些微型节肢动物是潘达利亚的原住民，以临风岛为家。"},Source={["3acabf4ce60c7aa3:23"]=S[8957]}}
D.ClientTexts.BattlePet[573]={Description={["f4a85fe00dc62aef:71"]="沙地海燕翱翔于临风岛上空，躲过了地面上的掠食者。"},Source={["3acabf4ce60c7aa3:23"]=S[8957]}}
D.ClientTexts.BattlePet[626]={Description={["93e24f32ccfef987:82"]="这些不祥的生物在东瘟疫之地的夜空下活动，以腐尸为食。"},Source={["e6e706b7738a9a0a:54"]="宠物对战：东瘟疫之地、海加尔山、提瑞斯法林地"}}
D.ClientTexts.BattlePet[627]={Description={["94d83b245564557d:129"]="比其外表更可怕的是，瘟疫之地的被感染的松鼠不再收集坚果，而是收集腐烂、败坏的肉。"},Source={["0c7bd79cd037e66f:59"]=S[8956]}}
D.ClientTexts.BattlePet[628]={Description={["9999b92aba0bc703:120"]="只有傻瓜和疯子才会骑上这些被感染的鹿，因为它们总是用头去撞墙。好消息是，它们与那些亡灵新朋友很相配。"},Source={["0c7bd79cd037e66f:59"]=S[8956]}}
D.ClientTexts.BattlePet[629]={Description={["64db2035ceafc68e:65"]="只在科赞海岸发现过，这个可爱的海洋生物脾气会有点暴躁。"},Source={["da54a542d9d69fd1:26"]="商人出售：马提\n地区：奥格瑞玛"}}
D.ClientTexts.BattlePet[630]={Description={["3e13bc079ae67b2a:43"]="乌鸦说：等你话说完，我都老了。"},Source={["cb506ac04d7b3f63:32"]="商人出售：威尔·拉森斯\n地区：黑海岸"}}
D.ClientTexts.BattlePet[631]={Description={["bdafc49dc0ff15c2:92"]="这种美丽的生物生活在艾泽拉斯富饶的河流两岸，其美丽的毛皮极受大众的追捧。"},Source={["46fc27536e448966:61"]="宠物对战：北贫瘠之地、南贫瘠之地、奥丹姆、安戈洛环形山"}}
D.ClientTexts.BattlePet[632]={Description={["f27c1a706e9c520d:83"]="这种燃灰蜥蜴得名于其蜕皮的样子，它们蜕下的旧皮看上去就像一堆燃烧的余烬。"},Source={["947a58bd96478064:34"]="宠物对战：海加尔山、安戈洛环形山"}}
D.ClientTexts.BattlePet[633]={Description={["e7027e67dc412c58:85"]="山地臭鼬最出名的就是其爱冒险的天性。不对，那只是它比较出名的一个天性而已。"},Source={["53f9a86894459f4b:78"]="宠物对战：灰熊丘陵、石爪山脉、风暴峭壁、湿地、冬泉谷"}}
D.ClientTexts.BattlePet[634]={Description={["cd8f60a69d74d1c5:86"]="这些奇怪的小家伙像冰块一样闪闪发光，使它们能够藏身于冬泉谷的雪域之中。"},Source={["bc09e95046389275:22"]="宠物对战：冬泉谷"}}
D.ClientTexts.BattlePet[710]={Description={["88d51c76347307f9:51"]="众所周知，它以四风谷的美味植物为食。"},Source={["fe35bc281447888d:30"]=S[8944]}}
D.ClientTexts.BattlePet[635]={Description={["36b29ad30e4707ae:90"]="与其他那些主动捕食的蛇类不同，这些狡猾的爬虫总是躲在浓密的植被下伏击猎物。"},Source={["5fe36f84bf1ef75d:147"]="宠物对战：诅咒之地、丹莫罗、杜隆塔尔、恐轨车站、地狱火半岛、纳格兰、北贫瘠之地、北荆棘谷、南贫瘠之地、阿兰卡峰林"}}
D.ClientTexts.BattlePet[637]={Description={["bf87786082456197:91"]="这些蜘蛛用它们剃刀般锋利的腿在刀锋山坚硬的岩石上挖出了大量隧道。"},Source={["b4cbd7c9ac864da8:30"]="宠物对战：刀锋山"}}
D.ClientTexts.BattlePet[638]={Description={["a48334dd5bbfb37a:119"]="虚空蟑螂已经适应了寒冷的真空环境，不需要空气也能存活。它们的体内构造和普通蟑螂几乎完全不同。"},Source={["51f61d5f38f1fdae:21"]="宠物对战：虚空风暴"}}
D.ClientTexts.BattlePet[639]={Description={["02b9d5279bc4854a:102"]="与它们那些生活在温暖地带的近亲不同，这些耐寒的小家伙们在诺森德的冰寒荒原上安了家。"},Source={["32dc3ba9c9ad6c76:22"]="宠物对战：北风苔原"}}
D.ClientTexts.BattlePet[640]={Description={["322bea0517c777a6:132"]="当追逐者陷入雪坑时，雪靴野兔依然可以依靠格外宽大的腿在雪地上轻松跳跃。"},Source={["a2bcc12d004d40e2:28"]="宠物对战：希尔斯布莱德丘陵"}}
D.ClientTexts.BattlePet[641]={Description={["445d20ad9193b0c2:52"]="极地野兔的心跳速度是普通野兔的两倍。"},Source={["c514a710e4e3eb4d:58"]="宠物对战：北风苔原、龙骨荒野、风暴峭壁、祖达克"}}
D.ClientTexts.BattlePet[644]={Description={["091e1169f42deb10:69"]="要不是意外死亡率太高，峡湾鼠可能已经统治世界了。"},Source={["ded67d319d7b4e7a:22"]=S[8943]}}
D.ClientTexts.BattlePet[645]={Description={["933694f8917e380f:40"]="与家养品种不同，这些小家伙可以飞。"},Source={["a8e3d122150c80f3:27"]=S[8952]}}
D.ClientTexts.BattlePet[646]={Description={["3fd71e3271363a69:50"]="不管动机如何，但它总想躲开十字路口。"},Source={["9443de8387729fca:145"]="宠物对战：暮色森林、尘泥沼泽、艾尔文森林、希尔斯布莱德丘陵、嚎风峡湾、赤脊山、泰罗卡森林、提瑞斯法林地、西部荒野、湿地\n"}}
D.ClientTexts.BattlePet[647]={Description={["68c4d3f87f0e9e49:76"]="在森林深处，就连小动物也得具备自我保护的凶猛性情。"},Source={["c88c31c581c08894:40"]="宠物对战：灰熊丘陵、暮光高地"}}
D.ClientTexts.BattlePet[648]={Description={["4dc32c79d83466cc:16"]="这是一只大蛤蟆。"},Source={["f4f1486fe56d638e:70"]="宠物对战：希尔斯布莱德丘陵、悲伤沼泽、暮光高地、祖达克"}}
D.ClientTexts.BattlePet[649]={Description={["647f83d4e945432d:106"]="人们相信，有关黄蟾蜍的药用价值的谣言是一个喜欢恶作剧的药剂师传出来的。"},Source={["5de8d5b5affe2b5a:23"]="宠物对战：索拉查盆地\n"}}
D.ClientTexts.BattlePet[650]={Description={["031e8193af14f346:44"]="而你认为餐桌上出现芜菁是十分糟糕的。"},Source={["77893debb180d882:39"]="掉落：世界掉落\n地区：四风谷"}}
D.ClientTexts.BattlePet[652]={Description={["6b1d70eee22bed55:30"]="这个泡泡要比水缸糟糕多了。"}}
D.ClientTexts.BattlePet[665]={Description={["930502907d5cc7a7:125"]="人们容易将沙地甲虫和普通甲虫搞混，可要是你不幸被某只沙地甲虫的尖刺蜇伤，你就马上能纠正自己的错误概念了。"},Source={["8e3de07c35bab667:34"]="集换式卡牌：遗忘之墓\n"}}
D.ClientTexts.BattlePet[666]={Description={["4268375b25e02ca8:146"]="当基尔加丹的军队在艾泽拉斯遭遇失利时，他总会掏出微型纳克斯号，恐吓阿古斯当地的小型猫科生物，来抚慰自己受伤的心灵。"},Source={["92cdbff4132d525b:32"]="成就：古墓探险者的荣耀\n"}}
D.ClientTexts.BattlePet[671]={Description={["53cbb438b040a445:29"]="皇家魁麟的后代。"},Source={["dc545f81f89ff5d4:46"]="特殊：熊猫人之谜典藏版"}}
D.ClientTexts.BattlePet[675]={Description={["30afc70ec1e0e19b:134"]="除了猫和捕鼠人之外，没有人发现暴风城的老鼠们在死亡之翼降临前突然逃离了城市。之后，它们才陆续返回。"},Source={["20622b20752b9f39:36"]="宠物对战：艾尔文森林、暴风城\n"}}
D.ClientTexts.BattlePet[677]={Description={["ca98db8219bfd3d9:101"]="曾有一个地精炼金师声称被这种浣熊咬了之后获得了预言能力。事后证明，那只是狂犬病。"},Source={["fe35bc281447888d:30"]=S[8944]}}
D.ClientTexts.BattlePet[678]={Description={["8f255e7fcfae40ae:103"]="这些绿色的小虫子是潘达利亚荒野的原住民。它们靠翠绿的颜色来躲避天敌。"},Source={["8857f3217ec2b69c:24"]=S[8941]}}
D.ClientTexts.BattlePet[679]={Description={["e4965457372d8502:108"]="它们通常都栖息在令人难以置信的高度，或偏远的裸石上，很少能在山脚看到他们。"},Source={["35c647940dfe38b5:23"]=S[8951]}}
D.ClientTexts.BattlePet[680]={Description={["95f02db198b3ccf4:85"]="猫鼬因具有驱赶毒蛇的能力而广受嘉许。Rikk-tikk-tikki-tikki-tchk！"},Source={["3458e600c9561781:25"]=S[8962]}}
D.ClientTexts.BattlePet[699]={Description={["0df061025ec2bb1b:85"]="这种恐怖又极具毒性的生物会从翡翠林茂密的林木顶端跃到猎物身上。"},Source={["3acabf4ce60c7aa3:23"]=S[8958]}}
D.ClientTexts.BattlePet[702]={Description={["5925df6f6590f1e4:63"]="金钱豹蛙得名于它们在树枝间纵跃的英姿。"},Source={["078ee2ba57cb186d:32"]="宠物对战：戈尔隆德、翡翠林"}}
D.ClientTexts.BattlePet[703]={Description={["297edab0040d731d:89"]="许多小浣熊都曾抱怨过严格的宵禁制度，觉得凌晨睡觉未免太早了。"},Source={["3acabf4ce60c7aa3:23"]=S[8957]}}
D.ClientTexts.BattlePet[705]={Description={["0c229b5124700678:81"]="对农夫而言，几乎没什么能比在脚下发现一只求爱的公鸡更让人难以忍受了。"},Source={["3ad281876e99898c:27"]=S[8944]}}
D.ClientTexts.BattlePet[706]={Description={["fb96cca342a5c8f6:49"]="这种沉默内敛的浣熊主要以吃苹果为生。"},Source={["fe35bc281447888d:30"]=S[8944]}}
D.ClientTexts.BattlePet[707]={Description={["2ec8d719d0124f58:83"]="有些德鲁伊说熊猫人和浣熊是远亲，但谁也不敢当着熊猫人的面这么说。"},Source={["fe35bc281447888d:30"]=S[8944]}}
D.ClientTexts.BattlePet[708]={Description={["3686dd7b5b818752:61"]="许多人都相信箭鼠能够对侵略者射出身上的刺。"},Source={["9fcc617114b50638:45"]="宠物对战：四风谷、卡桑琅丛林"}}
D.ClientTexts.BattlePet[709]={Description={["f2d16ec979e97e88:84"]="虽然箭鼠幼崽造成的伤口鲜有致命，大部分掠食者还是会去寻找更加安全的猎物。"},Source={["fe35bc281447888d:30"]=S[8944]}}
D.ClientTexts.BattlePet[712]={Description={["eae0d45378e20314:99"]="水獭在游泳时，会蜷起长长的身体，靠它们强有力的尾巴推进。它们的游泳速度非常快。"},Source={["fe35bc281447888d:30"]=S[8944]}}
D.ClientTexts.BattlePet[713]={Description={["56043156bece0c21:84"]="软壳乌龟的肉被人们视为佳肴，而且是海龟汤的关键原料。"},Source={["fe35bc281447888d:30"]=S[8944]}}
D.ClientTexts.BattlePet[714]={Description={["4c24f0b04c840763:108"]="有偏方称，一旦被热毒牙幼蛛咬伤，可以狂舞飙汗，在毒素沁入身体之前将其排出。"},Source={["8857f3217ec2b69c:24"]="宠物对战：卡桑琅丛林\n\n"}}
D.ClientTexts.BattlePet[715]={Description={["f063f3a05ba58ae1:97"]="因擅于结茧吐丝而倍受重视，对未经训练的人来说，很难在野外辨识出这种生物。"},Source={["fe35bc281447888d:30"]="宠物对战：四风谷\n"}}
D.ClientTexts.BattlePet[716]={Description={["1a4c5aef2399e508:74"]="这些不具毒性的小动物只吃植物和水果，这在蛛型纲动物中十分罕见。"},Source={["8857f3217ec2b69c:24"]=S[8942]}}
D.ClientTexts.BattlePet[717]={Description={["9005cb61c8fcb5da:34"]="甲虫家族中最美味的成员。"},Source={["8857f3217ec2b69c:24"]="宠物对战：卡桑琅丛林\n\n"}}
D.ClientTexts.BattlePet[718]={Description={["c260fa0ed68fdb17:74"]="这种勇敢又颇为自恋的昆虫，为使自己成为焦点，无惧任何威胁。"},Source={["8857f3217ec2b69c:24"]=S[8942]}}
D.ClientTexts.BattlePet[722]={Description={["8d80f0f5c74afcaa:40"]="长大后以吃小树叶和青草为生。"},Source={["8857f3217ec2b69c:24"]=S[8942]}}
D.ClientTexts.BattlePet[723]={Description={["d6179678fffe886f:93"]="棘刺水龟被激怒时，会缩进壳里，然后疯狂地旋转着撞向攻击者。"},Source={["8857f3217ec2b69c:24"]=S[8941]}}
D.ClientTexts.BattlePet[724]={Description={["bcb0e5faea6d64e9:44"]="钻入雪丘深处以躲避掠食者。"},Source={["35c647940dfe38b5:23"]=S[8951]}}
D.ClientTexts.BattlePet[725]={Description={["b6b16d216924b560:62"]="偶尔从被体型较大动物杀死的尸体上偷些食物。"},Source={["35c647940dfe38b5:23"]=S[8951]}}
D.ClientTexts.BattlePet[726]={Description={["d5931d47d7adfd18:169"]="静止不动时，平原监视者会不断地前后摇动尾巴。远远看去，很像随风摆荡的高高杂草，使这种爬行动物能骗过空中掠食者的眼睛。"},Source={["35c647940dfe38b5:23"]=S[8951]}}
D.ClientTexts.BattlePet[727]={Description={["fdfb091eab0ac113:88"]="在大草原上有数不胜数的噬齿生物和其它小动物，但没什么能比老鼠更常见了。"},Source={["35c647940dfe38b5:23"]=S[8951]}}
D.ClientTexts.BattlePet[728]={Description={["514515283564986b:29"]="只在强光下才肯产卵。"},Source={["35c647940dfe38b5:23"]="宠物对战：昆莱山"}}
D.ClientTexts.BattlePet[729]={Description={["d2b941b831c401a3:131"]="在古代传说中提到，多莱野兔本在星辰间跳跃，后来突因烦乱而坠下天穹，落入凡间。"},Source={["35c647940dfe38b5:23"]=S[8951]}}
D.ClientTexts.BattlePet[730]={Description={["cd76d67ad50e5f9d:62"]="多莱兔仔在年幼时就会被赶出窝巢，独立成长。"},Source={["35c647940dfe38b5:23"]=S[8951]}}
D.ClientTexts.BattlePet[731]={Description={["c81bc586ae3872b5:97"]="这些爬行动物身上长满了钩形鳞片，能在昆莱山的多岩山坡和险峻峭壁上攀爬自如。"},Source={["35c647940dfe38b5:23"]=S[8951]}}
D.ClientTexts.BattlePet[732]={Description={["4dc58e24a0bce775:67"]="众所周知，这种昆虫最喜爱雷雨天气，因此会在雨季繁衍。"},Source={["417b8096634a92b1:46"]="宠物对战：恐惧废土\n宠物对战：螳螂高原"}}
D.ClientTexts.BattlePet[733]={Description={["405bc96271e056ff:139"]="每到夜晚，草地欢跳者的疯狂歌声就会在夜空中回荡。那些无法习惯的人们在它们交配的歌声伴奏下度过了许多个不眠之夜。"},Source={["3458e600c9561781:25"]="宠物对战：螳螂高原"}}
D.ClientTexts.BattlePet[737]={Description={["7388bb1707ac842e:138"]="别看外表温和无害，猫鼬可是种危险的食肉动物，以擅长捕猎足以杀死更大猎物的毒蛇而著称。"},Source={["3458e600c9561781:25"]=S[8962]}}
D.ClientTexts.BattlePet[739]={Description={["5ecb3572fe30715d:60"]="猫鼬幼崽喜欢待在高高的草丛间，只有妈妈才能找到它们。"},Source={["3458e600c9561781:25"]=S[8962]}}
D.ClientTexts.BattlePet[740]={Description={["62d9d84deda2c85a:95"]="牦牛和老鼠之间的联结很是诡异，而至于老鼠能从这种共生关系中获得什么，则也是一个谜。"},Source={["d21d9103067e4728:37"]="宠物对战：螳螂高原、恐惧废土\n"}}
D.ClientTexts.BattlePet[741]={Description={["14af89b32f177876:90"]="这些刺猬或许很安静，可却总能让那些踩中它们尖刺的蠢货们哭天喊地。"},Source={["c53252db0a5a98d0:21"]=S[8948]}}
D.ClientTexts.BattlePet[742]={Description={["85c6b8c68ad38885:46"]="槌球戏和火烈鸟什么的，刺猬最讨厌了。"},Source={["c53252db0a5a98d0:21"]=S[8948]}}
D.ClientTexts.BattlePet[743]={Description={["2d71d59ca75b17fd:53"]="有人见过它们为争夺主要食物来源而与其他海螺厮打。"},Source={["c53252db0a5a98d0:21"]="宠物对战：恐惧废土\n\n"}}
D.ClientTexts.BattlePet[744]={Description={["5b9482aa2164c8d5:84"]="恐惧废土的蟑螂都潜伏在阴影中。有人发誓阴影会跟着它们移动。"},Source={["c53252db0a5a98d0:21"]=S[8948]}}
D.ClientTexts.BattlePet[745]={Description={["34c2560dfd605390:62"]="它的甲壳以其独特的纹理和强度倍受首饰匠的喜爱。"},Source={["c53252db0a5a98d0:21"]=S[8948]}}
D.ClientTexts.BattlePet[746]={Description={["f6c163dd33a1bda6:150"]="君王蟹得名于其庄严的外表：它们背上的纹路和举起的钳子很像一顶皇冠。可你要是想戴上它，它非把你的眼珠子夹出来不可。"},Source={["c53252db0a5a98d0:21"]=S[8948]}}
D.ClientTexts.BattlePet[747]={Description={["241802a94de96fe8:34"]="周身散发冷光，用于吸引配偶。"},Source={["0c72e4de52bf4c0f:31"]=S[8964]}}
D.ClientTexts.BattlePet[748]={Description={["741ed5454e3e60fa:58"]="这种精致昆虫的翅膀经常被用来点缀服饰和盔甲。"},Source={["0c72e4de52bf4c0f:31"]=S[8964]}}
D.ClientTexts.BattlePet[749]={Description={["15732952657b37c1:66"]="麝猫是水獭的陆生近亲，以浓郁的麝香而广受重视。"},Source={["0c72e4de52bf4c0f:31"]="宠物对战：锦绣谷"}}
D.ClientTexts.BattlePet[750]={Description={["b9a2a29fed3b388a:46"]="众所周知，麝猫会疯狂地保护自己的幼崽。"},Source={["0c72e4de52bf4c0f:31"]="宠物对战：锦绣谷"}}
D.ClientTexts.BattlePet[848]={Description={["b7c105ac8d116e19:36"]="这只兔子要比它看上去强大得多。"},Source={["7a00d0cfe62fcc1e:38"]="掉落：暗月兔子\n地区：暗月岛"}}
D.ClientTexts.BattlePet[751]={Description={["b3a8f604782e3c75:150"]="因其在水面飞掠时舞蹈般的姿势而得名，这种动物会通过飘忽不定地移动来使自己免于被鱼类和其它水下掠食者吞噬。"},Source={["0c72e4de52bf4c0f:31"]=S[8964]}}
D.ClientTexts.BattlePet[752]={Description={["97993ce1c158d4c0:68"]="尽管看似凶恶，这种黄腹牛蛙却有着恰如其分的名字。"},Source={["0c72e4de52bf4c0f:31"]=S[8964]}}
D.ClientTexts.BattlePet[753]={Description={["4dc58e24a0bce775:67"]="这种昆虫在雨季最为活跃，为雷雨所吸引。"},Source={["bd434d4b761945f8:20"]=S[8958]}}
D.ClientTexts.BattlePet[754]={Description={["e81e926e03d66a3d:117"]="这种昆虫被神殿的潜能所吸引，它们冷光熠熠的外表，为这蕴满力量之地更增添了几分神秘感。"},Source={["3acabf4ce60c7aa3:23"]=S[8958]}}
D.ClientTexts.BattlePet[755]={Description={["e0b5503bc57436c6:75"]="这只蟑螂甲壳上的印记，和亡首十分相像。"},Source={["ad89eb4f143fd7ae:20"]="宠物对战：海加尔山\n"}}
D.ClientTexts.BattlePet[756]={Description={["4ff6f284b7367a5b:53"]="更喜欢居住在黑暗的洞穴里，以心灵之花的花蜜为食。"},Source={["f60f30f2e070ba97:18"]="宠物对战：深岩之洲\n"}}
D.ClientTexts.BattlePet[757]={Description={["9a8a238283e93621:83"]="相传，这些充满活力的翡翠同伴能给主人带来好运，保他们旅途平安。"},Source={["fd85b0342e9f9ebf:20"]="特殊：iCoke中国活动"}}
D.ClientTexts.BattlePet[758]={Description={["ac25ffbdb5516b90:77"]="据说如果能在秋天见到，就能交上好运。一向对不熟悉的生物退避三舍。"},Source={["fd85b0342e9f9ebf:20"]="特殊：iCoke中国活动"}}
D.ClientTexts.BattlePet[792]={Description={["969e0a8f699150c2:39"]="一个体态优雅的生物，来自潘达利亚。"}}
D.ClientTexts.BattlePet[802]={Description={["fbf2dc27b1b26880:80"]="雷霆云端翔龙的缩小版，这是一种翱翔在遥远潘达利亚的强大翔龙。"},Source={["a860d34ea9dc6b89:18"]="商人出售：黑市"}}
D.ClientTexts.BattlePet[817]={Description={["b0c8d5273addf452:17"]="如此可爱，如此神奇。"},Source={["6d1c99ec3f3c2c89:62"]=S[8959]}}
D.ClientTexts.BattlePet[818]={Description={["0af77ceddd4fba58:104"]="烛龙的后裔，在永春台被煞魔彻底腐蚀前躲了起来。"},Source={["6d1c99ec3f3c2c89:62"]="宠物对战：翡翠林\n声望：云端翔龙骑士团（崇拜）"}}
D.ClientTexts.BattlePet[819]={Description={["d2bdaca9828ebfd4:26"]="因为它是红色的，所以肯定飞得更快。"},Source={["6d1c99ec3f3c2c89:62"]=S[8959]}}
D.ClientTexts.BattlePet[820]={Description={["21c05a8f56b581aa:45"]="众所周知，它以卡桑琅丛林的美味植物为食。"},Source={["479277fd9e9b3fde:39"]="成就：专业宠物团\n分类：宠物对战"}}
D.ClientTexts.BattlePet[821]={Description={["3075975af00a3fb7:41"]="它一直在盯着我看。我想它是想要咬我一口。"},Source={["8f363d31cb38c244:50"]="成就：需要更多绳套\n分类：收集"}}
D.ClientTexts.BattlePet[823]={Description={["620bba47cd44bbb8:98"]="这只凶猛的臭鼬能在三十码外朝攻击者喷臭气，使其暂时失明。一定要小心应对！"},Source={["a8e3d122150c80f3:27"]=S[8952]}}
D.ClientTexts.BattlePet[834]={Description={["8cfad0634108f0c4:106"]="与更具野性的仆从相比，那些能为石头赋予生命的魔古巫师们更钟爱这些感官迟钝的小伙伴。"},Source={["3c5a0a3e16cb6561:36"]="掉落：黑化者卡尔\n地区：恐惧废土\n\n"}}
D.ClientTexts.BattlePet[835]={Description={["7c1268082907aead:66"]="对这么渺小可爱的小生物来说，广阔的世界里到处都是危险。"},Source={["ebad630610ad0105:61"]="成就：林庭的草药之旅\n分类：地下城与团队"}}
D.ClientTexts.BattlePet[836]={Description={["31275d9d30295222:110"]="水黾在锦鱼人的文化中占有重要地位，既是坐骑，也是传递信息的工具，甚至可以充当家养宠物。"},Source={["940600284ee0544d:36"]="掉落：纳拉什·沃登提斯\n地区：恐惧废土\n\n"}}
D.ClientTexts.BattlePet[837]={Description={["4beb7141dc432442:124"]="有冒险者声称看到过这种罕见的巨型翠绿页岩蛛，深岩之洲的住民们管它叫玉牙页岩蛛。"},Source={["f60f30f2e070ba97:18"]=S[8953]}}
D.ClientTexts.BattlePet[838]={Description={["a4b9a8e44679fb0d:80"]="成年的紫晶页岩蛛喜欢在深岩之洲的外墙上筑巢。"},Source={["c64db05e739872c9:27"]="宠物对战：深岩之洲、凄凉之地"}}
D.ClientTexts.BattlePet[844]={Description={["1ea9051a33a6c6cf:162"]="由一大堆看似毫不相干的齿轮、弹簧、电线和某个特殊的小配件拼凑而成，这只幼龙透过工程师的视角，体现着潘达利亚的精神。"},Source={["f18900d2ac976b15:22"]=S[678]}}
D.ClientTexts.BattlePet[845]={Description={["24c5c0f85f1237e3:147"]="天然玉石色彩斑斓，充满生命力，是制造这只温驯宠物的完美原料。据说它挥动翅膀时扇出的风能抚平不安的心绪。"},Source={["9118632c807e31c7:24"]="专业技能：珠宝加工\n"}}
D.ClientTexts.BattlePet[846]={Description={["117363a7ed36119a:153"]="尽管每个宠物都是以同样的方式缔造的，但每颗宝石上的微瑕却能使其成为一个个具有独特性格的生命体。不过，它们通常总是活泼友好的。"},Source={["9118632c807e31c7:24"]="专业技能：珠宝加工\n"}}
D.ClientTexts.BattlePet[847]={Description={["6ed400d26c2df635:134"]="许多人（错误地）相信金鱼是没有记忆的。但它们的训练师很清楚不是这么回事，身上的瘀伤便是最好的证明。"},Source={["ac53fe7911894106:35"]="任务：烧死他们\n地区：翡翠林"}}
D.ClientTexts.BattlePet[849]={Description={["5aa30f1ccee73c23:50"]="一只美丽的风筝，潘达利亚的铭文师为其赋予了生命力。"},Source={["314be0995359547a:22"]="专业技能：铭文"}}
D.ClientTexts.BattlePet[850]={Description={["aa0fadc7deb45b54:29"]="谁能想到铭文师会制作风筝？"},Source={["314be0995359547a:22"]="专业技能：铭文"}}
D.ClientTexts.BattlePet[851]={Description={["03afa37822d24389:29"]="它不仅迅如闪电，而且声如洪钟！"},Source={["dc90c64b47147222:15"]=S[8946]}}
D.ClientTexts.BattlePet[855]={Description={["a744afaa09cc1f5f:39"]="奇怪的是，他竟然不喜欢苍蝇……对吧？"},Source={["6be932a7042e3ce6:47"]="成就：需要大量宠物食品\n分类：收集"}}
D.ClientTexts.BattlePet[856]={Description={["4ed5b4484fab5413:40"]="多加小心，她有时候会活泼过头！"},Source={["a0ab70f3f76baad2:50"]="成就：该去开家宠物店了\n分类：宠物对战"}}
D.ClientTexts.BattlePet[868]={Description={["bc9c58a417806641:90"]="水灵特别淘气，经常在风暴烈酒酿造厂外的运河里恶作剧。"},Source={["1716bc7ebda339a7:51"]="任务：熊猫人驭灵师\n地区：锦绣谷"}}
D.ClientTexts.BattlePet[903]={Description={["5f586599a294c314:108"]="爆虫是异虫大军中的自爆型单位，可造成惊人的伤害。近距离接触异常危险。"},Source={["dd5f23dda196a9e6:55"]="特殊：星际争霸2：虫群之心典藏版"}}
D.ClientTexts.BattlePet[1013]={Description={["73b87dd0e572cfe9:140"]="相传，神真子从前就是一只这样的海龙龟，后来越长越大，变成了迷踪岛。也许你的小海龟也能长成了不起的大家伙？"},Source={["dd92c42d27382c9a:48"]="宠物对战：卡桑琅丛林\n事件：云游节"}}
D.ClientTexts.BattlePet[1039]={Description={["bcf4fa278bf8bf48:73"]="这种飞蛾的幼虫以出产全艾泽拉斯最优质的丝绸而著称。"},Source={["56fde2a7c26a9bc2:34"]="专业技能：裁缝（帝王丝绸）"}}
D.ClientTexts.BattlePet[1040]={Description={["2d10507fbc6ca13e:73"]="这种胖嘟嘟的红色毛虫以出产全艾泽拉斯最优质的丝绸而著称。"},Source={["56fde2a7c26a9bc2:34"]="专业技能：裁缝（帝王丝绸）\n"}}
D.ClientTexts.BattlePet[1042]={Description={["bd8bb0ea62f23d51:33"]="小心，它可能会吃光你所有的粮食！"},Source={["7837d9e8f1f7d233:67"]="任务：与阿烁的朋友关系达到崇拜\n地区：四风谷"}}
D.ClientTexts.BattlePet[1155]={Description={["1e54e3a84e32e833:70"]="来自安其拉神殿的阿努比萨斯人偶，体内灌注着远古其拉魔法。"},Source={["9eef4b13a8be68ac:33"]="掉落：维克洛尔大帝\n地区：安其拉"}}
D.ClientTexts.BattlePet[1061]={Description={["1f2d7e02b3bfdcf9:164"]="大部分紫色的小森林陆行鸟都被斯塔姆·雷角做成了马戏团的口粮，但也有一小部分被驯养成了坐骑，或被喜欢紫色小宠物的冒险者买走。"}}
D.ClientTexts.BattlePet[1062]={Description={["f7fce79c9ff3904b:109"]="人们偶尔能在暗月岛扭曲的林木间瞥见它们一掠而过，它们诡异的绿光会令人联想到邪能烈焰。"},Source={["7c90cd3ad6dccf6f:24"]="宠物对战：暗月岛\n"}}
D.ClientTexts.BattlePet[1063]={Description={["6dc7d86d2e54366c:31"]="现在就连欺骗的念头都不要有了。"},Source={["5010482d48ad85aa:24"]="掉落： 暗月宠物补给袋\n"}}
D.ClientTexts.BattlePet[1068]={Description={["67537feb734855fa:73"]="虽然比臭名昭著的吉尔尼斯渡鸦要小一些，但在智力和狡诈程度上毫不逊色。"},Source={["94d57290ecbe9f45:82"]="宠物对战：偶尔在暗月岛上的战斗中与其它生物一起出现。"}}
D.ClientTexts.BattlePet[1073]={Description={["8236871963539992:74"]="塔吉是一只可爱又隐居避世的鱼人，相对于新朋友，她更喜欢和密友们在一起。"},Source={["129a04fa5d457db1:19"]="掉落：白色鱼人卵"}}
D.ClientTexts.BattlePet[1117]={Description={["8f292cdcfcfd0d0f:71"]="一只淘气、喜欢喵喵叫的放火狂。千万别在不戴防火手套的情况下抚摸这些小猫！"},Source={["13ced4bd7d391b10:11"]=S[16053]}}
D.ClientTexts.BattlePet[1124]={Description={["bda386e7a117beca:98"]="虽然它看似和燃烬猫仔是远亲，但这两种生物其实并不是来自同一个祖先。"},Source={["1716bc7ebda339a7:51"]=S[1295]}}
D.ClientTexts.BattlePet[1125]={Description={["ca1ef18d3157c12a:57"]="这些古灵代表了潘达利亚元素力量的核心。"},Source={["1716bc7ebda339a7:51"]=S[1295]}}
D.ClientTexts.BattlePet[1126]={Description={["ef00dd5c52d9f7c9:72"]="只要家园不受到威胁，潘达利亚的元素都是既可爱又淘气的。"},Source={["1716bc7ebda339a7:51"]=S[1295]}}
D.ClientTexts.BattlePet[1127]={Description={["810020945121a8fd:66"]="它可以躲进最小的盒子里，这多亏了那灵体的本质。"},Source={["19f7b44a413ead23:49"]="特殊：2012上海战网世界锦标赛"}}
D.ClientTexts.BattlePet[1128]={Description={["37a2e19af27a20e7:19"]="一只体型异常的土拨鼠。"},Source={["8857f3217ec2b69c:24"]=S[8941]}}
D.ClientTexts.BattlePet[1142]={Description={["44fe4da4a201de89:83"]="制造它的目的有且仅有一个：尽可能地暴打小动物。"}}
D.ClientTexts.BattlePet[1143]={Description={["20909b987adbe4b7:91"]="这些生物是在迈克斯纳巢穴后的一堆尘封的蛋中找到的，孵出来时就是亡灵了。"},Source={["d696cf0ffee2b4c8:26"]="掉落：迈克斯纳\n地区：纳克萨玛斯"}}
D.ClientTexts.BattlePet[1144]={Description={["53f836a362b6bb84:110"]="洛欧塞布的身体上布满了小坑，在风力配合的情况下，可以将凋零真菌的孢子散播到1000码以外的地方。"},Source={["3bb7351cfd2f17f3:26"]="掉落：洛欧塞布\n地区：纳克萨玛斯"}}
D.ClientTexts.BattlePet[1145]={Description={["1d2632b69707ccfb:106"]="在纳克萨玛斯现存的严寒墓地中，比格沃斯先生迅速找到了一个能晒到太阳的温暖角落并美美地打了个盹。"},Source={["0f344de5e473fbe6:46"]="成就：缰绳来袭\n分类：收集"}}
D.ClientTexts.BattlePet[1146]={Description={["a7271b3314e0048e:100"]="当一队勇敢的冒险者杀死格拉斯后，在他的尸体上发现了这些啃咬巨大的亡灵骨架的小家伙。"},Source={["58c4aee10b04f188:24"]="掉落：格拉斯\n地区：纳克萨玛斯"}}
D.ClientTexts.BattlePet[1147]={Description={["ad3a39f1c2e277dc:70"]="随着拉格纳罗斯在火焰之地的惨败，这些熊熊燃烧的先驱已经很少见了。"},Source={["e8d0653237e02f7d:37"]="掉落：萨弗隆先驱者\n地区：熔火之心"}}
D.ClientTexts.BattlePet[1149]={Description={["b55869d1c57ba954:83"]="这些烈焰小鬼总是成群结队地在熔火之心中游荡，而且繁衍极其迅速。"},Source={["f5e65b5c283c6427:28"]="掉落：玛格曼达\n地区：熔火之心"}}
D.ClientTexts.BattlePet[1150]={Description={["e556f58c64e22881:69"]="冷却的古雷曼格核心，似乎具有某种半智慧特征。"},Source={["46100084517c8f2b:42"]="掉落：焚化者古雷曼格\n地区：熔火之心"}}
D.ClientTexts.BattlePet[1151]={Description={["bee81848702a8655:60"]="一枚拉佐格尔的卵，奇迹般地在黑翼之巢中幸存了下来。"},Source={["2082ea4e2ec216ed:42"]="掉落：狂野的拉佐格尔\n地区：黑翼之巢"}}
D.ClientTexts.BattlePet[1152]={Description={["a492c8831a2df8b2:77"]="面对这个凶猛的多彩怪物时，它的敌人都祈祷它不要使用时间停止！"},Source={["604adab467572859:33"]="掉落：克洛玛古斯\n地区：黑翼之巢"}}
D.ClientTexts.BattlePet[1153]={Description={["b046c80fa6edcf48:42"]="娇小的黑爪龙人，用来守卫幼龙。"},Source={["95d4cf3085b73303:41"]="掉落：勒什雷尔\n地区：黑翼之巢"}}
D.ClientTexts.BattlePet[1154]={Description={["403cf3229a4c629d:58"]="这个小水滴没能及时回到维希度斯体内重新聚合。"},Source={["63eb37290912f07c:27"]="掉落：维希度斯\n地区：安其拉"}}
D.ClientTexts.BattlePet[1156]={Description={["e76103b0699ef341:64"]="许多冒险者的克星，只要看看它的眼睛，你就会明白什么是真正的疯狂。"},Source={["50e639857e6950b4:35"]="掉落：预言者斯克拉姆\n地区：安其拉"}}
D.ClientTexts.BattlePet[1157]={Description={["c6fe407e1feaae23:34"]="它们会越长越漂亮的。"},Source={["bb6387015b48b1ac:25"]="宠物对战：北贫瘠之地"}}
D.ClientTexts.BattlePet[1158]={Description={["6c8fa14baf2ddd6e:53"]="经过当地人多年的捕杀，这种小家伙已经非常稀有了。"},Source={["b1d041821d46cacd:17"]="宠物对战：菲拉斯"}}
D.ClientTexts.BattlePet[1159]={Description={["bb6f4c1e3307213f:32"]="大部分人从没读过这本书。"},Source={["a2bcc12d004d40e2:28"]="宠物对战：希尔斯布莱德丘陵\n"}}
D.ClientTexts.BattlePet[1160]={Description={["097583177f47b1e8:24"]="永远不要将你的眼睛移开。"},Source={["6387611b70966160:22"]="宠物对战： 逆风小径\n"}}
D.ClientTexts.BattlePet[1161]={Description={["b60b4eed39376542:36"]="你最好相信它对时间的把握。"},Source={["a6a8a23a2bb4f16b:23"]="宠物对战：时光之穴\n"}}
D.ClientTexts.BattlePet[1162]={Description={["9e2ef3cb086f08be:101"]="焊接小猫最初是在诺莫瑞根深处由工程师制造出来的，是现代工程学的奇迹。"},Source={["27f568c72727f924:20"]="宠物对战：诺莫瑞根\n"}}
D.ClientTexts.BattlePet[1163]={Description={["9e3e293e50d1cf11:112"]="永望镇的工程巫师制造了这种特殊的测试型号熊仔。不幸的是其中有一部分走失了而且再也没有被找回来。"},Source={["bc09e95046389275:22"]="宠物对战：冬泉谷\n"}}
D.ClientTexts.BattlePet[1164]={Description={["be8bcd694e1afb20:105"]="这种型号的迅猛龙产于刀锋山。托什雷的基地附近经常能听到它们的机械怒吼。"},Source={["b4cbd7c9ac864da8:30"]="宠物对战：刀锋山\n"}}
D.ClientTexts.BattlePet[1165]={Description={["01fc4d6f80fe2fec:77"]="玛里苟斯的幼嗣，这些小龙因其无穷无尽的魔力而格外珍贵。"},Source={["1b0ae8ccc2ff0947:18"]="宠物对战：考达拉\n"}}
D.ClientTexts.BattlePet[1166]={Description={["4b8ffc02f84204b3:79"]="这种稀有的雪人原产于昆莱山，它们比看上去要危险得多。"},Source={["35c647940dfe38b5:23"]=S[8951]}}
D.ClientTexts.BattlePet[1167]={Description={["533a4405dc79e9cc:57"]="诺森德的海岸上到处都是这种漂亮的幼龙。"},Source={["5de8d5b5affe2b5a:23"]="宠物对战：索拉查盆地\n"}}
D.ClientTexts.BattlePet[1168]={Description={["d7029ab555b22fe0:44"]="霸波尔奔是全世界最稀有的鱼人品种之一。"},Source={["024bdd3c352bfa47:32"]="特殊：韩国促销活动"}}
D.ClientTexts.BattlePet[1174]={Description={["2571d085bb9b550c:129"]="一本邪恶侵蚀的书卷，里面蕴藏着无比恐怖和诡异的秘密，书页散发着一种可怕的生命气息。是许多术士家中床头柜上的必备品。"},Source={["d87f10f1dda51010:37"]="集换式卡牌：守护者的背叛"}}
D.ClientTexts.BattlePet[1175]={Description={["fa01847441fda5e3:68"]="这些啮齿类生物带有闪电之力，应该与它们保持安全距离。"},Source={["3c8e8ce06b29c4c7:23"]=S[8966]}}
D.ClientTexts.BattlePet[1176]={Description={["9f2eb054ac01912b:34"]="你能相信我有多可爱吗？连我自己都不相信。"},Source={["33edebe24f044dfd:19"]=S[1293]}}
D.ClientTexts.BattlePet[1177]={Description={["f110b26179461a9a:70"]="本是沙粒，这些危险的生物能在转瞬间成形并消散。"},Source={["6c5078d365ee107a:20"]="掉落：雷电王座\n\n"}}
D.ClientTexts.BattlePet[1178]={Description={["9ad09a6becfd2178:77"]="这些小型构造体自诞生以来就忠于夺日者，威力不容小觑。"},Source={["45b46ebf0b012aac:48"]="掉落：错乱的夺日者构造体\n地区：雷神岛"}}
D.ClientTexts.BattlePet[1179]={Description={["22aa7f4d4e1e2dcc:51"]="在它周身上下，从头至尾都有闪电在涌动。"},Source={["3c8e8ce06b29c4c7:23"]=S[8966]}}
D.ClientTexts.BattlePet[1180]={Description={["dee9b38f9b239bce:97"]="这只独特的迅猛龙出生在赞达拉岛屿上，随赞达拉大军一同来到了这里。"},Source={["ea68a688732efd55:41"]=S[12326]}}
D.ClientTexts.BattlePet[1181]={Description={["1e4fbcc22013937f:49"]="这些蛇因能一口吞下侏儒而闻名。"},Source={["3c8e8ce06b29c4c7:23"]=S[8966]}}
D.ClientTexts.BattlePet[1182]={Description={["c3dad3102224a80b:25"]="最好别去碰它。"},Source={["3c8e8ce06b29c4c7:23"]=S[8966]}}
D.ClientTexts.BattlePet[1183]={Description={["4c40cd98212686e7:77"]="在雷电王座锻铸而成，这些小家伙效命于伟大的黑暗意志。"},Source={["46d6e63632bf3291:31"]="掉落：意志\n地区：雷电王座"}}
D.ClientTexts.BattlePet[1184]={Description={["9098099eddccaf05:70"]="即便体型如此娇小，恐角龙也能给疏于防范的目标造成毁灭。"},Source={["f226f89e3fede79b:43"]="成就：野蛮宠物格斗家\n分类：战斗"}}
D.ClientTexts.BattlePet[1185]={Description={["9f878dd8e5ce96e5:42"]="这玩意儿让你觉得有些眼熟……"},Source={["46c735a98c03bea2:53"]="任务：一大堆巨型恐龙骨骼\n地区：巨兽岛"}}
D.ClientTexts.BattlePet[1196]={Description={["7b1275b77392fafa:75"]="这些可爱的淘气鬼喜欢晒太阳，在太阳底下睡大觉，或是在阳光下打盹。"},Source={["33edebe24f044dfd:19"]=S[1293]}}
D.ClientTexts.BattlePet[1197]={Description={["b7f87ffbb671e39a:70"]="雪色小熊猫的雪白皮毛，让它能和昆莱山的皑皑白雪融为一体。"},Source={["33edebe24f044dfd:19"]=S[1293]}}
D.ClientTexts.BattlePet[1198]={Description={["91fec83380a63cc6:75"]="作为雪色小熊猫的表亲，高山小熊猫住在昆莱山的较低区域。"},Source={["33edebe24f044dfd:19"]=S[1293]}}
D.ClientTexts.BattlePet[1200]={Description={["2f89452561682f4c:48"]="不要抚摸尖的那一头。注意：全身上下都是尖的。"},Source={["2d4b67ee0ff8d6c3:33"]="掉落：赫利东\n地区：雷电王座"}}
D.ClientTexts.BattlePet[1201]={Description={["3af66d175a9fe8fc:108"]="有些熊猫人认为，格纳瑟斯是一名留下来守护雷神岛以南水域的古老赞达拉神灵。"},Source={["aea442672562b086:33"]="掉落：格纳瑟斯\n地区：螳螂高原"}}
D.ClientTexts.BattlePet[1202]={Description={["00801045b2fed676:93"]="作为古老凤凰的致命子嗣，季鹍雏凤在许多种族的文化中都是无比神圣的。"},Source={["ee3194972510d3f8:31"]="掉落：季鹍\n地区：雷电王座"}}
D.ClientTexts.BattlePet[1204]={Description={["f5d56ebff128929e:186"]="这些金属和螺栓下包裹着每个厨师的梦想。可惜他烹制的东西并不合人形生物的胃口。从贾德的日记来看，他打算为他的朋友——艾米丽·科尔制作这个小家伙。"},Source={["f18900d2ac976b15:22"]="专业技能：工程学\n"}}
D.ClientTexts.BattlePet[1205]={Description={["db182b1e96681767:72"]="赞达拉巨魔培育出了一种特殊的恐角龙，体型小巧，便于骑乘。"},Source={["c45291c091f0f749:31"]="掉落：恐角龙\n地区：巨兽岛\n"}}
D.ClientTexts.BattlePet[1206]={Description={["87140848331e0287:158"]="这些鱼身上的红色鳞片会让螳螂高原和恐惧废土的掠食者望而生畏，害怕肉里有毒。专注的渔人有时能和某一只建立好感。"},Source={["fd34c68f272323ec:18"]="专业技能： 钓鱼"}}
D.ClientTexts.BattlePet[1207]={Description={["2702294bb74f2d4c:144"]="这些小家伙生活在永恒岛的水域中，或是在珍宝斑马鱼和红腹鳜鱼附近游动。专注的渔人有时能和某一只建立好感。"},Source={["fd34c68f272323ec:18"]="专业技能： 钓鱼"}}
D.ClientTexts.BattlePet[1208]={Description={["aae9c4e7a54279d2:189"]="人们相信，这种绿色小金鱼的绿皮肤和条纹，让他们在翡翠林、四风谷和卡桑琅丛林的水域中穿梭时好似身穿天然迷彩装。专注的渔人有时能和某一只建立好感。"},Source={["fd34c68f272323ec:18"]="专业技能： 钓鱼"}}
D.ClientTexts.BattlePet[1209]={Description={["01a22ea217148c4b:182"]="这些适应性极强的鱼类能在各种气候环境下存活下来，从冰雪覆盖的昆莱山到潘达利亚各地温暖的咸水水域。专注的渔人有时能和某一只建立好感。"},Source={["fd34c68f272323ec:18"]="专业技能： 钓鱼\n"}}
D.ClientTexts.BattlePet[1211]={Description={["ed0ef07659985b6f:97"]="这些赞达拉巨魔的小兵们擅长躲在赞达拉巨型战船的货箱里完成偷渡。"},Source={["ea68a688732efd55:41"]=S[12326]}}
D.ClientTexts.BattlePet[1212]={Description={["4074847e50b8fe27:71"]="即便只有这么大，这些迅猛龙也能在十秒之内把一整只奶牛开膛破肚。"},Source={["ea68a688732efd55:41"]=S[12326]}}
D.ClientTexts.BattlePet[1213]={Description={["ed8fb800bff32a29:77"]="这些可爱的野兽既惹人喜爱又让人不禁想去拥抱它们，前提是你不在乎面子问题。"},Source={["ea68a688732efd55:41"]=S[12326]}}
D.ClientTexts.BattlePet[1226]={Description={["e18962466246a7df:79"]="大灰狼经常被人忘记的后代，躲在一篮子甜食里狼吞虎咽，呼呼大睡。"},Source={["422cc6cc0d96a3b1:31"]="掉落：大灰狼\n地区：卡拉赞"}}
D.ClientTexts.BattlePet[1227]={Description={["b0a2645bdaeabd70:162"]="主要职责包括打扫麦迪文的众多魔法神器，在莫罗斯之前，不少看管者都为此献出了生命、心智或身体。"},Source={["8824067b668b0bfe:28"]="掉落：馆长\n地区：卡拉赞"}}
D.ClientTexts.BattlePet[1228]={Description={["03b269bf56c827ea:162"]="在离开虚空异界时，玛克扎尔的深渊魔被卡拉赞的魔法结界诡异地扭曲了，体型变得微小，不易自动爆发烈焰。"},Source={["e42b55d3fe153d9a:34"]="掉落：玛克扎尔王子\n地区：卡拉赞"}}
D.ClientTexts.BattlePet[1229]={Description={["4e9941352c71ace2:103"]="这只狡猾的小鬼是特雷斯坦·邪蹄的仆从，当通往扭曲虚空的传送门在它身后关闭时，它被留在了卡拉赞。"},Source={["919a4bb69c28962d:34"]="掉落：特雷斯坦·邪蹄\n地区：卡拉赞"}}
D.ClientTexts.BattlePet[1230]={Description={["1ff5ec5e931b5a6b:117"]="艾泽拉斯科研团体的惊人发现，这些科研人员长久以来总是习惯在酒馆里陷入沉思，思考年幼的海巨人会是什么样子。"},Source={["b6ac64ab54fd0c9e:47"]="掉落：莫洛格里·踏潮者\n地区：毒蛇神殿"}}
D.ClientTexts.BattlePet[1231]={Description={["4d6fea1bacb092c6:74"]="海度斯的后代，被元素界视作“泥浆伯爵”。"},Source={["b76514becf57d2b9:47"]="掉落：不稳定的海度斯\n地区：毒蛇神殿"}}
D.ClientTexts.BattlePet[1232]={Description={["f46590b63b760a3d:134"]="没人知道瓦丝琪究竟是怎么给这些沼泽阔步者灌注了扭曲心智的力量，尽管这只生物年纪还小，却已经显露出了强大的灵魂能力。"},Source={["40ebfad94f9d630e:38"]="掉落：瓦丝琪\n地区：毒蛇神殿"}}
D.ClientTexts.BattlePet[1233]={Description={["64566acf0d6cbb0a:122"]="由强大的污染者阿克蒙德经由扭曲虚空派遣而来，用其中等强度的跺地声来惊吓弱小的种族。"},Source={["1b7a4f88b7243a1d:31"]="掉落：空灵机甲\n地区：风暴要塞\n\n"}}
D.ClientTexts.BattlePet[1234]={Description={["176852e14853b3c0:107"]="虚空召唤者携带的灯笼架起了连接人间与鬼域的桥梁，而且总能吸引到任性的鬼灵与幽魂。"},Source={["2d060b89b16d4806:44"]="掉落：大星术师索兰莉安\n地区：风暴要塞\n"}}
D.ClientTexts.BattlePet[1235]={Description={["bc0409929702660f:112"]="这些色彩明艳的龙鹰能在魔眼四周的虚空风暴间，迅速准确地运送凯尔萨斯的军队。"},Source={["f36bf098eed4ee2b:26"]="掉落：奥\n地区：风暴要塞\n"}}
D.ClientTexts.BattlePet[1236]={Description={["fefae700d80b6557:171"]="虽然擅长舞台指导，但每当托托与胆小的狮子四目相接继而在卡拉赞歌剧院里大肆追逐时，演出还是会不止一次地中断。"},Source={["245d2ec26074e641:66"]="成就：缰绳来袭II：钥匙的远征\n分类：收集"}}
D.ClientTexts.BattlePet[1237]={Description={["2fb795a7b4bd47da:152"]="巨魔在召唤多头蛇方面有着悠久显赫的历史。尽管加兹洛奇并不是体型最大或最强壮的多头蛇，但要是你靠得太近，它还是会相当大力地咬断你的手指头。"}}
D.ClientTexts.BattlePet[1238]={Description={["4f5b4fd380c6d3bc:69"]="只有在征服了高贵的生物后，瓦格里才算是完成了“成人礼”。"},Source={["716f4a385509f08b:19"]="宠物对战：诺森德"}}
D.ClientTexts.BattlePet[1243]={Description={["d676e3672255bf50:98"]="普利莫修斯房间内的黑水池在魔古覆亡后变得污浊不堪，阴暗的思想开始升腾。"},Source={["6d02669e7b52af21:60"]="掉落：普利莫修斯\n地区：雷电王座\n难度：随机团队\n"}}
D.ClientTexts.BattlePet[1244]={Description={["d3efa4d0bdb9ff41:69"]="这些邪恶的软泥怪对普利莫修斯的信息素信号极为敏感。"},Source={["645352283f2bd42f:60"]="掉落：普利莫修斯\n地区：雷电王座\n难度：普通或英雄\n"}}
D.ClientTexts.BattlePet[1245]={Description={["8917c578cf6f098d:102"]="强烈建议战斗宠物训练师在与这种肮脏的小泥团戏耍过后，至少洗三十分钟手。"},Source={["b4cb9ac548db7c44:19"]="掉落：颤栗污泥怪"}}
D.ClientTexts.BattlePet[1248]={Description={["5af1be28f0662501:115"]="这棵萌生新芽的古树是艾泽拉斯的独特树种，由符印巨树的长青枝桠嫁接而成，一年四季都花开满枝。"},Source={["13ced4bd7d391b10:11"]="游戏商城\n"}}
D.ClientTexts.BattlePet[1255]={Description={["1ef62890ee1cdcf9:111"]="作为臭名昭著的星灵厉害角色，泽拉达尔也是唯一能够使用灵能风暴的执政官，拥有着压倒性的力量！"},Source={["db322146c0e39307:55"]="特殊：星际争霸2：虚空之遗典藏版\n"}}
D.ClientTexts.BattlePet[1256]={Description={["427efc40fc26c737:212"]="这个小家伙似乎喜欢在大灾变事件的边缘游走。但并没有任何证据表明，他跟这些事件的起因有什么关联——他也许只是个旁观者，又或许只是在去往其它地方的艰苦旅途中迷了路。"},Source={["f18900d2ac976b15:22"]="专业技能：工程学\n"}}
D.ClientTexts.BattlePet[1257]={Description={["916400f80e8e602f:30"]="可能会失控，然后杀死某个倒霉鬼。"},Source={["a1a50ecdc8460e94:15"]="掉落：开发人员\n"}}
D.ClientTexts.BattlePet[1266]={Description={["188d36928568a2cb:122"]="凶猛而又忠诚的雪福喜欢在月光下狩猎。它有一次在满月的夜晚杀死并吃下了一整只铁鬃公牛，然后睡了两天两夜。"},Source={["da65eb1807eedeed:29"]="商人出售：天神比武大会"}}
D.ClientTexts.BattlePet[1276]={Description={["88e47593f23d099a:88"]="月牙的幼崽都会成长为体型硕大、口水横流的黑毛杀戮机器……然而月月是个例外。"},Source={["ead542f5924506da:32"]="掉落：月牙\n地区：暗月岛"}}
D.ClientTexts.BattlePet[1303]={Description={["10888603cc153c02:87"]="赤芝试图通过大声尖叫和追赶吞食蝴蝶来激起别人心中的希望。"}}
D.ClientTexts.BattlePet[1304]={Description={["bafaf489665b2846:209"]="一位雕刻大师出于对玉珑的喜爱和崇敬，耗尽毕生精力制作出了这个美丽绝伦的雕像。当雕刻家辞世后，玉珑将自己的一小部分精华吹进了雕像里，为玉兰赋予了生命。"}}
D.ClientTexts.BattlePet[1305]={Description={["8f31102d78bc8372:78"]="皂皂总是俯身低头，目光炯炯地望向前方，密切留意着可能发生的战斗或鲜美的青草。"},Source={["da65eb1807eedeed:29"]="商人出售：天神比武大会"}}
D.ClientTexts.BattlePet[1320]={Description={["71f42b1c83539f05:195"]="这个帅气的小机器人与他的“爸爸”布林顿4000几乎是一个模子里刻出来的。鉴于只有在最大规格的布林顿机器人体内才具有决定其慷慨品格的电路，这个小家伙可不会给你什么免费赠品。"},Source={["17656a99fdb652ac:25"]="掉落：布林顿礼盒\n"}}
D.ClientTexts.BattlePet[1321]={Description={["cfc4c2b46dfebcdb:89"]="永恒岛上的雏鹤有时候会吟唱一支奇怪的曲子，能够舒缓神经，安抚灵魂。"},Source={["3d8f7dc0c66c6961:31"]="掉落：鹤巢\n地区：永恒岛"}}
D.ClientTexts.BattlePet[1322]={Description={["e462caa6f9bf872d:125"]="它是诞生于地下堡垒的第一个小炸弹人，攻城匠师黑索不忍心将它摧毁，把它当成了一个友好而具有爆炸性的宠物。"},Source={["79e18104dd973023:47"]="掉落：攻城匠师黑索\n团队副本：决战奥格瑞玛"}}
D.ClientTexts.BattlePet[1323]={Description={["22ce93f46013bfbf:114"]="永恒岛上的灰叶林精不知疲倦地保护着岛上的植物，使其免于被斡耳朵斯及其爪牙熊熊燃烧的怒火吞噬。"},Source={["5a0f8c50e6f9ef93:32"]="掉落：剪叶者\n地区：永恒岛\n"}}
D.ClientTexts.BattlePet[1324]={Description={["4c9c7efb67ca04a0:100"]="锦鱼人刺客将这只飞蛾带在身边，既能充当随身诱饵，又能作为光源，在敌人的护甲上找出薄弱点。"},Source={["df23e1b7d24d166c:22"]="宠物对战：永恒岛\n"}}
D.ClientTexts.BattlePet[1325]={Description={["e93ab791466a24b6:104"]="小猫和其它好奇的小动物常常会和这只飞蛾玩上一小会儿，结果给自己留下满脸焦毛。"},Source={["df23e1b7d24d166c:22"]="宠物对战：永恒岛\n"}}
D.ClientTexts.BattlePet[1326]={Description={["18bde9fd9c4aafc2:78"]="人们有时候会发现这只古怪的飞蛾正在打断某位云游法师或术士的法术。"},Source={["df23e1b7d24d166c:22"]="宠物对战：永恒岛\n"}}
D.ClientTexts.BattlePet[1328]={Description={["109ce8471d6ea732:121"]="红玉湖的湖水呈现出一种怪异的微红色彩，可能和在永恒岛深山中发现的红宝石晶体有关。"},Source={["d031816ffcb6141e:28"]="掉落：加尼亚\n地区：永恒岛"}}
D.ClientTexts.BattlePet[1329]={Description={["b1d0d2aa8062d557:98"]="除了对鲜花着迷外，嬉闹者还会随着摇曳的草叶和偶生的杂草翩翩起舞。"},Source={["64f900d647735f05:33"]="掉落：惊悚之灵\n地区：永恒岛\n"}}
D.ClientTexts.BattlePet[1330]={Description={["235a9a1211e5b3c1:121"]="在生命后期，如果环境条件适合的话，致死蝰蛇会蜕去表皮，变成一条帝王巨蟒。"},Source={["8edc5a7242018b15:36"]="掉落：帝王巨蟒\n掉落：永恒岛"}}
D.ClientTexts.BattlePet[1331]={Description={["fc775f41270fbe10:159"]="亚煞极的少许残余力量催生出了煞魔，亚煞极的一滴脓水就能将数千码内的情绪状态放大，使整座城镇因恐惧或怀疑而离群隐世。"},Source={["1b32ad2d5f3a7d08:70"]="掉落：傲之煞\n团队副本：决战奥格瑞玛\n难度：弹性、普通或英雄"}}
D.ClientTexts.BattlePet[1332]={Description={["24ffa4d75a326934:145"]="小煞魔能够反映出主人的情绪状态，会根据周边负面思绪的强弱程度而变得焦躁、沮丧、恐惧或多疑。"},Source={["c93c98d4b94a99c1:61"]="掉落：傲之煞\n团队副本：决战奥格瑞玛\n难度：随机和弹性"}}
D.ClientTexts.BattlePet[1333]={Description={["5209dbaecca5d9cb:95"]="永恒岛上的翠雾舞者对西北海岸的汽孔颇感兴趣。"},Source={["18da405b869b5b58:36"]="掉落：翠雾舞者\n地区：永恒岛"}}
D.ClientTexts.BattlePet[1334]={Description={["282671da2f4265ef:182"]="科沃克是恐惧废土的微小恐惧体，饮食习惯一成不变，酷爱食“脑”——穆山兽脑、人脑……对任何脑都来者不拒。这种诡异的营养需求也许和他巨大的脑袋稍有联系。"},Source={["50320f22b2cef1ed:45"]="掉落：卡拉克西英杰\n团队副本：决战奥格瑞玛\n"}}
D.ClientTexts.BattlePet[1335]={Description={["7b9909f483120cad:89"]="孤魂岩洞中的诡异蓝焰已经引得众多疏于防范的冒险者送了命。"},Source={["0db055e1cc9a4f56:37"]="掉落：恶兆之火\n地区：永恒岛\n\n"}}
D.ClientTexts.BattlePet[1336]={Description={["6edef4c39c2bbe26:222"]="当老酒湾在数个世代以前遭到斡耳朵野牛人的入侵时，村民们勇敢地在村子中央竖起了一个酒桶。第二天一早，庆典的热度消退后，宿醉未醒的野牛人稀里糊涂地签下了和平条约。"},Source={["27d8a70f7056a6e2:36"]="掉落：泛酸的筑汞\n地区：永恒岛\n\n"}}
D.ClientTexts.BattlePet[1337]={Description={["5bfcfe98d639232f:98"]="潘达利亚的钳爪蟹已经存活了数千年之久，是这片大陆上最为古老的物种之一。"},Source={["e5b1065db5c1a732:40"]="掉落：凶暴钳爪蟹\n地区：永恒岛\n"}}
D.ClientTexts.BattlePet[1338]={Description={["9c07b40eda79044b:126"]="永恒岛上的巨口蛙能吃掉大于自身体型数倍的猎物，它们可以通过一滩剧毒黏液，将受害者在体外缓慢地消化掉。"},Source={["27530d69583511f0:26"]="掉落：布佛\n地区：永恒岛"}}
D.ClientTexts.BattlePet[1343]={Description={["152c5de12c67fc5e:166"]="有些年幼且野性难驯的猢狲从小就被训练使用拳击手套，这样他们便不会误杀自己的族人，更为重要的是，还可以防止他们挖鼻孔。"},Source={["86dceafbe4724c58:33"]="掉落：库库鲁的宝箱\n地区：永恒岛"}}
D.ClientTexts.BattlePet[1344]={Description={["97ad2ffe6809524b:111"]="这家伙是永恒岛在时空转移时被留在岛上的野兽之一，很有可能是斡耳朵野牛人献给自己的半神斡耳朵斯的。"},Source={["644ddcf8d7d10b39:36"]="商人出售：发言人古兰\n地区：永恒岛"}}
D.ClientTexts.BattlePet[1345]={Description={["e884208344104698:93"]="古赤的蚕宝宝能吐出一种古老且异常强大的丝线，这种丝线在潘达利亚已经消失多年了。"},Source={["86652608a2e62d75:43"]="掉落：虫群先锋古赤\n地区：永恒岛"}}
D.ClientTexts.BattlePet[1346]={Description={["d05e88668ea3d75d:108"]="这些灵魂因长时间接触少昊的宁静之雾而变得平心静气，已经成为织雾者身边平静的伙伴。"},Source={["6a84b19edf22cd41:62"]="商人出售：织雾者顾严\n地区：永恒岛\n声望：少昊 - 践行者"}}
D.ClientTexts.BattlePet[1348]={Description={["6a82488b22b057f8:71"]="玉火之灵被认为是玉珑自身玉火吐息的活体化身。"},Source={["366aa427c2380296:38"]="掉落：玉火之灵\n地区：永恒岛\n\n"}}
D.ClientTexts.BattlePet[1349]={Description={["d7e99eb4da94a619:171"]="厌倦了长时低薪的工作，并且不愿再忍受冒险者对劣质冬幕节礼物无休止的抱怨，这些淘气的小家伙逃出了它们的魔法工作间，和讨厌的格林奇走到了一起。"},Source={["d00fbada955d933f:28"]="世界事件：冬幕节\n"}}
D.ClientTexts.BattlePet[1350]={Description={["59c3c87687334ddb:81"]="风筝里的一支蜡烛燃热了空气，使其可以在无风的情况下升上高空。"},Source={["910b1fbf7c33c024:29"]="商人出售：莫苦\n地区：永恒岛"}}
D.ClientTexts.BattlePet[1351]={Description={["9e94ad708b3073e3:77"]="异想天开的亡者鬼魂为这些被附身的小傀儡赋予了有如生者的外表。"},Source={["c5bcd66ba3de5c94:23"]="世界事件：悼念日"}}
D.ClientTexts.BattlePet[1363]={Description={["f5110d39df9f7944:163"]="身为营救类獒犬，奥特兰克负酒犬的血统以搜救被大雪掩埋的登山客而著称……当然它们那流不完的哈喇子也颇有名声。"},Source={["13ced4bd7d391b10:11"]=S[16053]}}
D.ClientTexts.BattlePet[1364]={Description={["991554a9ef39f55e:101"]="圣教威名传万古，\r\n亦善征战亦善舞。\r\n朝夕演兵军歌扬，\r\n此阵世间何人睹。"},Source={["fc4bf3d7c0953a5a:22"]="特殊：2013年暴雪嘉年华"}}
D.ClientTexts.BattlePet[1365]={Description={["8032b631b12dad22:19"]="看好你的钱包。"},Source={["6e0901357f4c6bb8:49"]="特殊：暗黑破坏神3：夺魂之镰典藏版"}}
D.ClientTexts.BattlePet[1384]={Description={["ceb8c1adafdcc462:75"]="强大的霍格斯既顽强又可怕，会毫不犹豫地消灭弱小的敌人。"},Source={["1c2dbb9c833a4055:46"]="成就：我打！\n分类：暗月马戏团"}}
D.ClientTexts.BattlePet[1385]={Description={["3852bcca7c25289f:89"]="这头可怕的奇美拉的两个脑袋都一样可怕，每个脑袋都能单独发起特殊的吐息攻击。"},Source={["b6bd5649814b521c:27"]="任务：德拉诺宠物博览\n"}}
D.ClientTexts.BattlePet[1386]={Description={["64277c9f70dfbca2:78"]="黑暗之翼会湮没并吞噬弱者的心智，因为它们实在是太可爱了！"},Source={["d536be81106c0cc0:45"]="特殊：德拉诺之王典藏版"}}
D.ClientTexts.BattlePet[1387]={Description={["205e3515fdee7c38:79"]="这把巨大的毁灭性武器被缩小了，供人们在花园里使用。鼹鼠们要小心了！"},Source={["4190463fb7087c50:79"]="任务：向国王报告（联盟），警告酋长（部落）\n地区：诅咒之地（90+）\n"}}
D.ClientTexts.BattlePet[1394]={Description={["c067ac53dda8329a:74"]="凭借黑暗魔法和一腔热爱之情，用落败战斗宠物的零碎残骸制成。"},Source={["b6bd5649814b521c:27"]="任务：德拉诺宠物博览\n"}}
D.ClientTexts.BattlePet[1395]={Description={["08bbabf2d6ea8567:34"]="可爱到令人食欲大开，但不推荐这么做。"},Source={["23fe4731a58f961c:18"]="专业技能：烹饪"}}
D.ClientTexts.BattlePet[1396]={Description={["ff98231e21b4c227:54"]="如果放任不管，胡萝卜绝对会失去理智。"}}
D.ClientTexts.BattlePet[1403]={Description={["c4eaf6a5acb2db7a:14"]="吱吱！"},Source={["f18900d2ac976b15:22"]=S[678]}}
D.ClientTexts.BattlePet[1411]={Description={["10cfc9ffe0d8685a:63"]="在坟墓上通常会放置一根孔雀羽毛，来避免邪灵的侵入。"},Source={["f46354896e899ed4:25"]="成就：德拉诺猎人\n"}}
D.ClientTexts.BattlePet[1412]={Description={["90a8642534c0b37c:115"]="在频频有人抱怨说驯服年幼的野猪是件苦差事后，工程师们设计出了这个栩栩如生到吓人的模型，解决了这个难题。"},Source={["f18900d2ac976b15:22"]=S[678]}}
D.ClientTexts.BattlePet[1416]={Description={["05989bfce713853f:45"]="别看恐爪鸟是毛茸茸的小家伙，却是强大的猎手。"},Source={["d67f978c75ce3367:29"]="掉落：恐爪鸟巢穴\n地区：塔拉多"}}
D.ClientTexts.BattlePet[1426]={Description={["653a600dc4fd9df2:46"]="这只可爱的小象随时随地都在等着你。"},Source={["223d4bf036e6af71:20"]="专业技能：裁缝\n"}}
D.ClientTexts.BattlePet[1427]={Description={["5c84eb0a6dbcaf6b:82"]="尽管恼人而又破坏力十足，但在足够多奶酪的引诱下，却能变成听话的小伙伴。"},Source={["754c14432b54be94:24"]=S[8967]}}
D.ClientTexts.BattlePet[1428]={Description={["65fee5cc65c82957:99"]="僵尸龙虾人是邪恶的化身，是某个因隔绝而发狂的人犯下的大错，是不可消除的创造物。"},Source={["787c34239dbd1f30:66"]="掉落：复生的黑潮骨壳者，黑潮硬壳者\n地区：影月谷\n"}}
