D.ClientTexts.BattlePet[1430]={Description={["2be8b712c2ea3457:36"]=S[1127]}}
D.ClientTexts.BattlePet[1431]={Description={["2be8b712c2ea3457:36"]=S[1127]}}
D.ClientTexts.BattlePet[1432]={Description={["2be8b712c2ea3457:36"]=S[1127]},Source={["f9e73f3eb9ae0f2d:20"]="专业技能：草药学"}}
D.ClientTexts.BattlePet[1433]={Description={["2be8b712c2ea3457:36"]=S[1127]}}
D.ClientTexts.BattlePet[1434]={Description={["2be8b712c2ea3457:36"]=S[1127]},Source={["b6bd5649814b521c:27"]=S[1294]}}
D.ClientTexts.BattlePet[1435]={Description={["545b7dbadf2645c9:93"]="许多年前，一名食人魔试图把一只厚皮小牛的牛皮加工成用脚踢的皮球。在那之后，他就只能顶着“一只脚”的绰号过活了。"},Source={["0f8f9cbf9c5ada16:17"]="宠物对战：纳格兰"}}
D.ClientTexts.BattlePet[1441]={Description={["3200eabd169c4cd2:138"]="兽人的孩子们有个传统，他们会溜到泥浆跳跃者背上，小声说出一个希望能够成真的秘密心愿。如果泥浆跳跃者没跳起来的话，心愿就会实现。"},Source={["e9d5ff5f88e3740c:51"]="宠物对战：至高岭，纳格兰，阿兰卡峰林，塔拉多\n"}}
D.ClientTexts.BattlePet[1442]={Description={["c84b8aff5f30c8b4:80"]="作为顽固派的终极代表，这只曾经活过的母山羊坚决不肯死去。"},Source={["b6bd5649814b521c:27"]=S[1294]}}
D.ClientTexts.BattlePet[1446]={Description={["383bd48fd90c70c8:78"]="小雷象聪明而富有爱心的性情，使其成为可靠的终身伙伴。"},Source={["69a8e7ce7c0b7f6b:36"]="任务：新的幼崽\n地区：纳格兰（德拉诺）"}}
D.ClientTexts.BattlePet[1447]={Description={["13eb9d9b874c0a94:106"]="月壳蟹的壳有着极强的反光特性，可以捡起来当作镜子使用。别被它们的蟹钳抓破脸就好！"},Source={["105b541085ec72c3:26"]=S[8947]}}
D.ClientTexts.BattlePet[1448]={Description={["dd20e2c49132a0a5:48"]="这只海牛对平衡的东西有着与生俱来的青睐。"}}
D.ClientTexts.BattlePet[1449]={Description={["341eeb5c2fbb33c7:83"]="这个刚出生的小家伙有着不同寻常的感知力，可以发现并跟随领头的捕食者。"}}
D.ClientTexts.BattlePet[1450]={Description={["8262d5cc74725881:133"]="尽管这些微型机械守卫的制造初衷是为了保护家养雷象免受害虫的侵扰，但事实证明，它们还是按摩的高手。"},Source={["89803231364c0732:50"]="商人出售：守备官努瑞姆\n声望：主教议会\n"}}
D.ClientTexts.BattlePet[1451]={Description={["da3890afe4dd9a92:62"]="喜欢跟小鬼混在一起，在岩浆里打滚，依偎在元素领主身边。"},Source={["2df8a03dbd4241da:56"]="成就：魔兽世界十周年\n分类：光辉事迹"}}
D.ClientTexts.BattlePet[1453]={Description={["406e78fb93d667a6:74"]=S[19033]}}
D.ClientTexts.BattlePet[1454]={Description={["5543af69c6cf70fe:100"]="在啃过古尔丹的胫骨后，这个好动的恶魔猎手就被他的哥哥鱼鹿囚禁了10000年。"},Source={["fc4bf3d9c0953a5c:22"]="特殊：2015年暴雪嘉年华\n\n"}}
D.ClientTexts.BattlePet[1455]={Description={["22ad939607cd3def:78"]="伪装成苔藓的样子，这个小飞掠者会躲在树丛里，从天而降般地跳到目标身上。"},Source={["105b541085ec72c3:26"]=S[8947]}}
D.ClientTexts.BattlePet[1456]={Description={["e782cfa82106ff41:107"]="这小家伙凭借着颇具欺骗性的可爱外表吸引猎物，然后疾风骤雨般地将它们席卷。拥抱要小心。"},Source={["e37f284e86bdfde9:22"]=S[8947]}}
D.ClientTexts.BattlePet[1457]={Description={["73f31e008f135dc5:97"]="这些冰寒的小家伙身上长着无比尖利的爪子，在厚厚的冰层和岩石下方打洞栖身。"},Source={["754c14432b54be94:24"]=S[8967]}}
D.ClientTexts.BattlePet[1458]={Description={["c04079fd75c8444a:118"]="在某种食人魔的仪式上，他们会让白骨蜂叮在自己手上。白骨蜂的毒液让他们增强力量的同时，也产生了强烈幻觉。"},Source={["76d8233e7915e52d:44"]="商人出售：阵营商人\n声望：嘲颅氏族"}}
D.ClientTexts.BattlePet[1462]={Description={["63430ed38e83a842:64"]="与主流观点相反，血刺蜂并不是靠吸血过活，而是渴望爱。"},Source={["e37f284e86bdfde9:22"]=S[8965]}}
D.ClientTexts.BattlePet[1463]={Description={["84b11039519ccd86:93"]="林地蜂在枯死或中空的树上筑巢，并会迅速攻击任何威胁其家园的敌人。"},Source={["da50bec6b58ae1f3:18"]=S[8949]}}
D.ClientTexts.BattlePet[1464]={Description={["88b8a455b8470e52:84"]="在月光下，它们的翅膀会生出闪耀的光环，犹如闪烁的星光一般熠熠生辉。"},Source={["92bb57912024f548:33"]="宠物对战：霜火岭，戈尔隆德"}}
D.ClientTexts.BattlePet[1465]={Description={["ad6c07629162ca3f:115"]="珀钩黄蜂总是喜欢激怒体形更大的生物来攻击它。等到目标上钩后，它们便会倾巢出动，还击敌人。"},Source={["da50bec6b58ae1f3:18"]=S[8949]}}
D.ClientTexts.BattlePet[1466]={Description={["cf697d7226e38b8f:82"]="一只精力充沛的魔法小猫，有时她会毫无由来地四处乱窜。"},Source={["13ced4bd7d391b10:11"]="游戏商城\n"}}
D.ClientTexts.BattlePet[1467]={Description={["d87af84fa24ce0cc:101"]="飞天切割者原本是臭名昭著的米莉·沃特为她猫咪设计的玩具。她的猫就睡在旁边的盒子里。"},Source={["8784b59e41cc0331:29"]="掉落：布林顿5000礼包"}}
D.ClientTexts.BattlePet[1468]={Description={["76a4a5faefad325f:82"]="古老的德拉诺部族向来喜欢用它们锐利的鸟喙来制作原始的工具和武器。"},Source={["5f77501c2b38e06d:22"]="宠物对战：塔纳安丛林"}}
D.ClientTexts.BattlePet[1469]={Description={["f1809db119c00a64:121"]="这些鸟身上美丽多彩的鸟羽倍受藏家的追捧。据说把这些羽毛戴在身上，能给你带来好运气。"},Source={["da50bec6b58ae1f3:18"]=S[8949]}}
D.ClientTexts.BattlePet[1470]={Description={["fb56f385ac20a71a:72"]="它鸟喙的边缘锋利得出奇。在喂它进食时小心你的手指头！"},Source={["da50bec6b58ae1f3:18"]=S[8949]}}
D.ClientTexts.BattlePet[1471]={Description={["df8c5bc683fa5e11:46"]="这只焦躁不安的小鸟酷爱吃水果。"},Source={["c383ca14bb89fecd:35"]="掉落：震动的蛋\n地区：霜火岭\n\n"}}
D.ClientTexts.BattlePet[1478]={Description={["7cff4201958caa00:80"]="这只小乌贼似乎很喜欢穿裤子，可在这世上你去哪找适合它穿的裤子呢？"},Source={["0482cd57a5f99a46:31"]="掉落：高级暗月宠物补给\n"}}
D.ClientTexts.BattlePet[1495]={Description={["aa38bc75ce0307a4:59"]="它们吃啊，吃啊，吃啊，直到长得很大。然后就能吃得更多。"},Source={["e972048967da50ee:17"]="专业技能：采矿"}}
D.ClientTexts.BattlePet[1511]={Description={["ee19294db45df24a:60"]="当然有雏鸟了，它们的名字可是爱情鸟啊，对吧？"}}
D.ClientTexts.BattlePet[1514]={Description={["98ae4b429367988d:38"]="在魔法手段和叶绿素的作用下，它变得生气勃勃。"}}
D.ClientTexts.BattlePet[1515]={Description={["3052277d9510395e:81"]="这个机器人身上出自大师之手的齿轮传动装置和精密焊接处显然都是用满满的爱制作出来的。"},Source={["e46db9dbed73b75a:12"]="掉落：塔拉多"}}
D.ClientTexts.BattlePet[1516]={Description={["fc5aff067ee880d7:152"]="在被地精引入大陆之后，灌木小鸡就以美味的口感和低智商一举成为了感恩节餐桌上的特色菜。"},Source={["c2cfd978ad541187:26"]="世界事件：感恩节"}}
D.ClientTexts.BattlePet[1517]={Description={["a3b36da712be4236:51"]="在它的笼子旁边排满了各种昆虫烧成灰烬的微小尸体。"}}
D.ClientTexts.BattlePet[1518]={Description={["a1f0b0dea13ea9af:102"]="熊猫人酒仙偶然将一桶高老伯新酿的美酒带到了美酒节上来。"}}
D.ClientTexts.BattlePet[1521]={Description={["8dd73176cf8d6bbf:89"]="这只猫有九条命，其中一条会在你刚想进入梦乡时大声叫唤来骚扰生者。"}}
D.ClientTexts.BattlePet[1523]={Description={["464d5471a6605430:53"]="就连死亡也抑制不了这只小猫难以满足的好奇心。"}}
D.ClientTexts.BattlePet[1524]={Description={["6d6f860659916099:37"]="这只软泥怪有着漫长而混乱不清的血统。"},Source={["b0131f34685b36c3:28"]="掉落：灵魔\n地区：纳格兰\n"}}
D.ClientTexts.BattlePet[1530]={Description={["d1da85fa3e90b5c7:118"]="小狼领命原地留，\r\n静待猎物来上钩。\r\n傲气不离终夭折，\r\n拘束散去自在游。\r\n"},Source={["460985159ae8a4ac:22"]=S[679]}}
D.ClientTexts.BattlePet[1531]={Description={["41e7fd44508110e7:69"]="这个上古巢穴守卫在设计时被灌注了不可思议的构想：恨猫。"},Source={["460985159ae8a4ac:22"]=S[679]}}
D.ClientTexts.BattlePet[1532]={Description={["f807ed78a854a199:98"]="卡利鸟的雏鸟在刚出生时以蛆虫为食，翅膀硬了之后却能吃掉任何比自己小的东西。"},Source={["db910b163d58da83:32"]="任务：伊奇的蛋\n地区：阿兰卡峰林"}}
D.ClientTexts.BattlePet[1533]={Description={["999b76ae4fd0c741:94"]="没人知道兰提克究竟是生活在黑翼血环深处的哪个区域，但那里肯定臭烘烘的。"},Source={["273d124732b194d6:41"]="掉落：兰提克\n地区：黑石塔上层"}}
D.ClientTexts.BattlePet[1536]={Description={["9877305045b4406b:108"]="在德拉诺，赞加海会把成千上万个这种孢子释放到海岸上，从而渐渐蚕食陆地。"},Source={["5dbcc6303dd173bf:44"]=S[12329]}}
D.ClientTexts.BattlePet[1537]={Description={["fdddcd3fca6dcb34:101"]="一种采摘自赤红沼泽的孢子，那是戈尔隆德的一个地区，在德拉诺被虚空魔法撕裂时被吞灭了。"},Source={["26ff2c49f8f7976a:30"]="掉落：奇异孢子\n地区：戈尔隆德\n"}}
D.ClientTexts.BattlePet[1538]={Description={["3bf7de11fbca9e70:56"]="深蓝色的暗泽后来成了破碎者部族的家园。"},Source={["c2d4949345a67a3a:38"]="掉落：奇异孢子\n地区：影月谷\n"}}
D.ClientTexts.BattlePet[1539]={Description={["c549966ce822b9b1:92"]="一种来自赞加拉的孢子，那是赞加海侵蚀的中心地区，后来发展成了赞加沼泽。"},Source={["5dbcc6303dd173bf:44"]=S[12329]}}
D.ClientTexts.BattlePet[1540]={Description={["3af227fe4bf3ad7f:117"]="一种极为罕见的明亮孢子，可以在深受赞加真菌侵蚀的最黑暗的角落里找到，藏在德拉诺的波涛深处。"},Source={["fd2a73dd0f0d8e0e:28"]="掉落：烂菌\n地区：阿兰卡峰林"}}
D.ClientTexts.BattlePet[1541]={Description={["62acb532ac30e123:85"]="养这只小多头蛇的成本十分高昂，因为它一次能吃掉三碗饲料。"},Source={["7c0f96b4542b9d71:32"]="掉落：瓦拉沙的卵\n地区：阿兰卡峰林"}}
D.ClientTexts.BattlePet[1542]={Description={["6b35b9abe6030396:83"]=S[20078]},Source={["fa61cfb914e199e2:36"]="商人出售：贝斯卡·赤牙\n阵营：霜狼\n\n"}}
D.ClientTexts.BattlePet[1543]={Description={["69377ec1173eaf34:47"]="饲养这种母牛的初衷只是为了给侏儒提供更加美味的牛奶。"},Source={["a66bf752004697f9:26"]="掉落：要塞，畜棚，3级"}}
D.ClientTexts.BattlePet[1544]={Description={["7d06451ab46ac539:29"]="小身材并不会使他的仇恨减少半分。"},Source={["87e64ae62ebca14d:59"]="掉落：炎魔拉格纳罗斯\n地区：熔火之心（周年庆版本）"}}
D.ClientTexts.BattlePet[1545]={Description={["d57a5ff2ebcb5d3b:44"]="别把纸放到她笼子边上，除非你想来场大火。"},Source={["b6bd5649814b521c:27"]=S[1294]}}
D.ClientTexts.BattlePet[1546]={Description={["a1b64a0619beb499:72"]="美丽的风暴之翼是一只半鸟半元素生物，能产生绝对的震骇效应。"},Source={["3b568fe5b8fa9992:25"]="成就：兼收并蓄"}}
D.ClientTexts.BattlePet[1563]={Description={["d6fa3326e81e6145:69"]="青铜龙宝宝在时间中迷失了，直到发生了一次不同寻常的事件，她才得以逃脱。"},Source={["ebf278a5deafb886:31"]="掉落：钢铁部落\n地区：诅咒之地"}}
D.ClientTexts.BattlePet[1564]={Description={["92856f6371752f7a:58"]="清楚地表明了为什么应该谨慎地使用地精肥料。"},Source={["1235e148ff84754b:31"]="掉落：曼达科尔\n地区：戈尔隆德\n"}}
D.ClientTexts.BattlePet[1565]={Description={["dc212300c12006e9:52"]="钢铁铸就，烈火烧成。弹簧、齿轮、铁板还有线材。"},Source={["f18900d2ac976b15:22"]=S[678]}}
D.ClientTexts.BattlePet[1566]={Description={["f5d3e39d7193b342:80"]="这些小家伙似乎钟爱又大又蓬松的鸟巢，最好筑在喜欢动物的树妖头上。"},Source={["fe1ca3cd62276bda:17"]="任务：为了小孔雀"}}
D.ClientTexts.BattlePet[1567]={Description={["79aeb04c39b68a21:54"]="某位暗夜精灵哨兵的小伙伴，很少有人会把它当作礼物送人。"},Source={["b881b566ba24bead:19"]="任务：女猎手"}}
D.ClientTexts.BattlePet[1568]={Description={["0f6cf14ce250ba9d:95"]="生活在距离水面很近的地方，泥水恐魔不仅是所有水生生物的朋友，还是它们当中的一员。"},Source={["b6bd5649814b521c:27"]=S[1294]}}
D.ClientTexts.BattlePet[1569]={Description={["4edc356ba3552c16:163"]="在锻铸注魔钢铁时，少许魔法力量渗透到了煤炭中。经过若干年，甚至是数十年，不受束缚的能量慢慢具备了形体，成为无比刚毅的微小元素生物。"},Source={["d118a3c7ad5847e0:24"]="专业技能：锻造"}}
D.ClientTexts.BattlePet[1570]={Description={["db072f9b635a2e0a:66"]="相传，阳炎卡利鸟在一心赴死时，会径直朝烈日飞去。"},Source={["b6bd5649814b521c:27"]=S[1294]}}
D.ClientTexts.BattlePet[1571]={Description={["692ba57ff13fea44:77"]="这种幼崽身上的白色兽皮像板甲一样厚，若非如此，它们很容易被烈日灼伤。"}}
D.ClientTexts.BattlePet[1572]={Description={["5bbe717fc2fcd698:78"]="血羽完全无所畏惧，散开自己的羽毛，冲向任何威胁它的敌人。"},Source={["ddbe3e4bdf819e42:17"]=S[8945]}}
D.ClientTexts.BattlePet[1573]={Description={["3fd897537aa7257a:65"]="据说当旭日的光芒照在它们身上时，这种鸟身上的羽毛会像黄金般闪耀。"},Source={["e37f284e86bdfde9:22"]=S[8965]}}
D.ClientTexts.BattlePet[1574]={Description={["97b5706b65437584:28"]="神一般所在的旅行形态。"}}
D.ClientTexts.BattlePet[1575]={Description={["3043a163ee6663fa:54"]="跟鳐玩传接游戏总是很有趣。你甚至都不用瞄准。"},Source={["7a58edf8ff5530f3:49"]="商人出售：声望商人\n声望：沙塔尔防御者"}}
D.ClientTexts.BattlePet[1576]={Description={["233306677674c02c:46"]="你总是觉得……有东西在盯着你看。"},Source={["21dd79a6da27cd1b:33"]="掉落：观察者奥鲁莫\n地区：塔拉多"}}
D.ClientTexts.BattlePet[1577]={Description={["49bce6576e7ada14:58"]="年幼且不具杀伤力的血棘幼崽，是深受食人魔喜爱的餐点。"},Source={["a1a329699b9068d0:50"]=S[6140]}}
D.ClientTexts.BattlePet[1578]={Description={["2882f9ee70b44345:87"]="霜壳钳爪蟹会筑起厚厚的冰层，以保护自己免受更大捕食者的攻击。"},Source={["754c14432b54be94:24"]=S[8967]}}
D.ClientTexts.BattlePet[1579]={Description={["4a76260616e351f3:65"]="尖利的蟹爪足以粉碎板甲护手，最好小心应对。"},Source={["754c14432b54be94:24"]=S[8967]}}
D.ClientTexts.BattlePet[1581]={Description={["c1794430294b297b:78"]="这种狡猾的甲壳类动物会在泥里打洞，避免遭受到更大捕食者的攻击。"},Source={["5f77501c2b38e06d:22"]="宠物对战：塔纳安丛林\n"}}
D.ClientTexts.BattlePet[1582]={Description={["56d9898c367ef66f:94"]="这种螃蟹以富含营养物的真菌孢子为食，因此蟹壳带有独特的色彩。"},Source={["105b541085ec72c3:26"]=S[8947]}}
D.ClientTexts.BattlePet[1583]={Description={["ad04b35ba09da440:81"]="他们将自己隐藏在海藻和其它海洋植物当中，出其不意地袭击猎物。"},Source={["ddbe3e4bdf819e42:17"]=S[8945]}}
D.ClientTexts.BattlePet[1586]={Description={["e9e990598502594c:63"]="既美丽又危险，既闪耀又放肆，是比黄金还要珍贵的美丽飞蛾。"},Source={["5f77501c2b38e06d:22"]="宠物对战：塔纳安丛林\n\n"}}
D.ClientTexts.BattlePet[1587]={Description={["af9c05fd86bbded0:107"]="深紫色的翅膀深受食人魔法师的追捧，他们相信用来做药引可以延年益寿。"},Source={["bf082683e4edfbdc:34"]="宠物对战：影月谷，塔拉多"}}
D.ClientTexts.BattlePet[1588]={Description={["265d85905a6f0b35:63"]="在遇到危险时，它们的翅膀会释放发出一种超细的粉末，作为防御手段。"},Source={["a1a329699b9068d0:50"]=S[6140]}}
D.ClientTexts.BattlePet[1589]={Description={["8334d23b185687a4:95"]="既美丽又危险，既闪耀又放肆，是比同等重量的黄金还要珍贵的美丽飞蛾。只可惜它们都太轻了。"},Source={["ddbe3e4bdf819e42:17"]=S[8945]}}
D.ClientTexts.BattlePet[1590]={Description={["4a39d0ee1d16be95:82"]="学者们始终对萤火虫的发光原理争论不休，但最被认可的假设是“魔法论”。"},Source={["7ecc31a527d34fa0:35"]="宠物对战：至高岭、阿兰卡峰林"}}
D.ClientTexts.BattlePet[1591]={Description={["f300d0547ab79707:70"]="这些萤火虫通过采食紫色的花朵和花蜜来保持自己身上发出的紫色光芒。"},Source={["5f77501c2b38e06d:22"]="宠物对战：塔纳安丛林\n"}}
D.ClientTexts.BattlePet[1592]={Description={["fc7d6fc56d3380a6:79"]="由于这种萤火虫身上的光泽与上等蓝玉十分接近，故又被称作‘会飞的宝石’。"},Source={["e37f284e86bdfde9:22"]=S[8965]}}
D.ClientTexts.BattlePet[1593]={Description={["512a2cca8bedb351:82"]="这种水荧利用水面来反射肚子上发出的光芒，从而吸引伴侣。"},Source={["991f10a728726b7a:47"]="宠物对战： 影月谷、塔拉多、塔纳安丛林"}}
D.ClientTexts.BattlePet[1594]={Description={["406e78fb93d667a6:74"]=S[19033]},Source={["da50bec6b58ae1f3:18"]=S[8949]}}
D.ClientTexts.BattlePet[1595]={Description={["406e78fb93d667a6:74"]=S[19033]},Source={["ddbe3e4bdf819e42:17"]=S[8945]}}
D.ClientTexts.BattlePet[1596]={Description={["8bfe4e2c36622933:70"]=S[16935]}}
D.ClientTexts.BattlePet[1597]={Description={["847252838c5a6ca0:69"]=S[16935]}}
D.ClientTexts.BattlePet[1598]={Description={["49c5423b10310848:80"]=S[20869]},Source={["a1a329699b9068d0:50"]=S[6140]}}
D.ClientTexts.BattlePet[1599]={Description={["49c5423b10310848:80"]=S[20869]},Source={["ddbe3e4bdf819e42:17"]=S[8945]}}
D.ClientTexts.BattlePet[1600]={Description={["a4d18e3b254188d6:106"]="幼年骨蛇会钻进活物的脑袋里吃他们的脑子。所以你最好戴一顶睡帽。"},Source={["9f326b162b0d9605:43"]="宠物对战：收藏家爱瑞斯，库拉·雷蹄"}}
D.ClientTexts.BattlePet[1601]={Description={["b34e22ccd53b5b9d:73"]="当戴米多斯为其它虚空领主举办派对时，制造出了不少仆从。"},Source={["9989733b4cb2c00e:33"]="掉落：戴米多斯\n地区：影月谷"}}
D.ClientTexts.BattlePet[1602]={Description={["7742ce0be7076df0:48"]="如论他如何尖叫，千万不要给他恶魔之血。"},Source={["fc4bf3d8c0953a5b:22"]="特殊：2014年暴雪嘉年华"}}
D.ClientTexts.BattlePet[1603]={Description={["aa5dc156e2da8a97:89"]="总被人发现正在咀嚼不该吃的东西，山羊最初被认作是埃索达覆灭的罪魁祸首。"},Source={["13ced4bd7d391b10:11"]=S[16053]}}
D.ClientTexts.BattlePet[1604]={Description={["ca793dcb1fe37b16:82"]="是哪位达拉然法师遗失的魔法灯笼，还是一支性格热情的活化蜡烛？你说了算。"},Source={["b43aa1eebabdec7f:12"]="地区：达拉然\n"}}
D.ClientTexts.BattlePet[1605]={Description={["f9c0212c19e03531:54"]="一种魔法小伙伴，由等量的冒险精神和勇气凝聚而成。"},Source={["6d35e0db5c3e1bac:33"]="成就：超级大冒险"}}
D.ClientTexts.BattlePet[1615]={Description={["03afa37822d24389:29"]="它不仅迅如闪电，而且声如洪钟！"},Source={["da50bec6b58ae1f3:18"]=S[8949]}}
D.ClientTexts.BattlePet[1622]={Description={["31ba00cfbd95dcc4:97"]="一幢阴郁建筑上的小型石像鬼，将雨水引向别处，防止陵墓被水淹没。"},Source={["5b8c9411d3134b54:28"]="掉落：阿兹加洛\n地区：海加尔峰"}}
D.ClientTexts.BattlePet[1623]={Description={["384462ee95d11b79:84"]="黑暗神殿的下水道系统中深绿色的腐水赋予了这些多头蛇鲜亮的色彩。"},Source={["6591637845a4e9e7:41"]="掉落：高阶督军纳因图斯\n地区：黑暗神殿"}}
D.ClientTexts.BattlePet[1624]={Description={["64cde1640cd941ad:103"]="作为巨大的深渊魔苏普雷姆斯的碎片，深渊小魔怪所蕴含的火焰精华足以将你的口袋烧穿一个洞。"},Source={["c5b54ff2b20166f3:29"]="掉落：苏普雷姆斯\n地区：黑暗神殿"}}
D.ClientTexts.BattlePet[1625]={Description={["f64a905171e9ce72:19"]="它只是有一点疯。"},Source={["8fe02104b5ab7333:39"]=S[12327]}}
D.ClientTexts.BattlePet[1626]={Description={["6f9a655f9439194c:24"]="它只是有点生气。"},Source={["8fe02104b5ab7333:39"]=S[12327]}}
D.ClientTexts.BattlePet[1627]={Description={["899bc6ab092e956a:27"]="它只是有点兴趣。"},Source={["8fe02104b5ab7333:39"]=S[12327]}}
D.ClientTexts.BattlePet[1628]={Description={["487a0f1e6a6040c7:48"]="她是你肩头的恶魔，在你耳边窃窃私语。"},Source={["c1433d8e9bca381f:34"]="掉落：莎赫拉丝主母\n地区：黑暗神殿"}}
D.ClientTexts.BattlePet[1629]={Description={["297f42a033eed1ab:16"]="那是什么味儿？"},Source={["d1a83de5d984f0d0:30"]="掉落：安纳塞隆\n地区：海加尔峰"}}
D.ClientTexts.BattlePet[1631]={Description={["a516a76695d6ff43:75"]="数百只这样的小精灵聚集在一起，保护海加尔免受阿克蒙德的侵袭。它们拯救了世界。"},Source={["3fe1407b42f2b528:31"]="掉落：阿克蒙德\n地区：海加尔峰"}}
D.ClientTexts.BattlePet[1632]={Description={["53e4801634825b3d:66"]="你不会想知道当一只老鼠溜进太阳之井时会发生什么。"},Source={["0b75b2de5eee1239:33"]="掉落：布鲁塔卢斯\n地区：太阳之井高地"}}
D.ClientTexts.BattlePet[1633]={Description={["3771766cc5a90f8d:78"]="扭曲虚空是一个无尽的恐怖深渊，也是可爱到极点的一个小小角落。"},Source={["4771c5b011c4414b:29"]="掉落：穆鲁\n地区：太阳之井高地"}}
D.ClientTexts.BattlePet[1634]={Description={["69c245f15d8868f2:112"]="嗜魔成瘾的精灵太过渺小和脆弱，无法成为基尔加丹的大军主力，最终沦为高级恶魔的仆役。"},Source={["c248ad68a3ff7d3b:35"]="掉落：艾瑞达双子\n地区：太阳之井高地"}}
D.ClientTexts.BattlePet[1635]={Description={["419aef8a42d81c7d:73"]="当这只宠物走近时，祥和的钟声充斥着你的脑海，让你想起悠远的往昔。"},Source={["97779e2f918e6174:72"]="成就：缰绳来袭III：畅饮太阳之井\n分类：收集"}}
D.ClientTexts.BattlePet[1636]={Description={["3c00ce787c6ff77b:68"]="暗月竞速赛最讨厌的障碍物之一，现在它落在你的手上了！"},Source={["4424ccb8233c9eff:51"]="成就：火箭神兵：黄金\n分类：暗月马戏团"}}
D.ClientTexts.BattlePet[1639]={Description={["001ad1b2a959f227:194"]="在一次对鬼灵矿的突袭中，一队英雄只收到了一个精华。结果召唤出的魔像体型太小，没法对敌人的塔造成多少伤害。这头魔像最后游荡进了时空枢纽，最终来到了艾泽拉斯。"},Source={["d072bbf73cfe684e:26"]="特殊：风暴英雄\n"}}
D.ClientTexts.BattlePet[1655]={Description={["d86a767bff5e17b4:97"]="德拉诺的河流中生活着许多鳗鱼。它们是邪恶的掠食者，会攻击一切进入水域的生物。"},Source={["9f326b162b0d9605:43"]=S[8950]}}
D.ClientTexts.BattlePet[1656]={Description={["c4c76b9adcf871e5:43"]="塔布羊的犄角在幼年时就已经完全长成了。"},Source={["9f326b162b0d9605:43"]=S[8950]}}
D.ClientTexts.BattlePet[1660]={Description={["6b35b9abe6030396:83"]=S[20078]},Source={["00614204b7213425:39"]="任务：我的邪能小幼崽\n地区：塔纳安丛林\n\n"}}
D.ClientTexts.BattlePet[1661]={Description={["587e15f48fa90a93:88"]="传说，有一些被虚空感染的野兽就生活在两个相邻世界之间的空间中。"},Source={["a1a329699b9068d0:50"]=S[6140]}}
D.ClientTexts.BattlePet[1662]={Description={["bb53d8f349129abe:102"]="这只狼崽被发现时，正在黑石铸造厂的黑色熔炉里啃着一块焦黑的骨头。它可以迅速让你暖和起来。"},Source={["15dc7d5002bf571d:28"]="要塞任务：烈焰之友\n"}}
D.ClientTexts.BattlePet[1663]={Description={["02b9961e2f7b3f55:95"]="这些顽皮的小淡水兽喜欢含一大口水，然后互相喷着玩。"},Source={["5dbcc6303dd173bf:44"]=S[12329]}}
D.ClientTexts.BattlePet[1664]={Description={["63f1a03c52278f65:126"]="曾是德莱尼祭司用来安抚灵魂的圣器，被愤怒的灵魂赋予生命后，就常被充斥着死亡和腐蚀的地方吸引。"},Source={["5dbcc6303dd173bf:44"]=S[12329]}}
D.ClientTexts.BattlePet[1665]={Description={["32bac66a7f42e3c9:88"]="这些螃蟹进化出了更高级的伪装形态，使它们的皮肤看起来像是透明的。"},Source={["57e356938206f758:39"]=S[6139]}}
D.ClientTexts.BattlePet[1666]={Description={["86b4a4eb3f543976:79"]="这种鱼似乎对你的命令毫无反应，也根本意识不到你的存在，真的。"},Source={["57e356938206f758:39"]=S[6139]}}
D.ClientTexts.BattlePet[1672]={Description={["82189365216ea5e4:74"]="腐化的巢穴守卫和煎蛋卷的大厨没什么两样。"},Source={["b6a8fd89c60fae72:41"]="掉落：暗影领主艾斯卡\n地区：地狱火堡垒\n"}}
D.ClientTexts.BattlePet[1687]={Description={["dbc82b67f37fd834:61"]="谁会丢下这么可爱的小鲨鱼？钢铁部落真是没人性。"},Source={["360879988c1b4a49:43"]="要塞任务：营救失怙水生动物\n"}}
D.ClientTexts.BattlePet[1688]={Description={["46d0303eb9a7d91f:93"]="这只迷路的鬣蜥人被发现时正在一场小型暴风雪中游荡。随身携带的矿锄说明他还是个多面手。"}}
D.ClientTexts.BattlePet[1690]={Description={["2d2b27959814cd5c:86"]="森卢肯的一小部分精魂正在这块秘文中熊熊燃烧。你最好将其贴身收藏。"},Source={["3dc89ab360204762:51"]="宝藏：被遗忘的秘文碎片\n地区：塔纳安丛林"}}
D.ClientTexts.BattlePet[1691]={Description={["019d77708ae4b073:80"]="一把魔法小点就轻而易举地让这只小魔犬离开了萨格拉斯。"},Source={["279dab918efd2a36:34"]="特殊：军团再临典藏版"}}
D.ClientTexts.BattlePet[1692]={Description={["2bfce526e0d89cd1:76"]="宠物总是像它们的主人，当它们的主人是刃牙虎人时就更是如此。"}}
D.ClientTexts.BattlePet[1693]={Description={["a2dba6a7041d3492:74"]="鸦人对太阳的崇拜令他们制造出了一些古怪又畸形的爪牙。"},Source={["6c944f7e40f5222f:75"]="商人出售：觅晨者科塞克\n地区：塔纳安丛林\n阵营：觉醒教派 - 崇拜"}}
D.ClientTexts.BattlePet[1699]={Description={["96d8e41725cd6df4:135"]="女巫斯塔佳为她的大锅进行过附魔，防止它被打翻而溢出热汤来。她从没想过大锅会产生知觉，并且试图谋杀她。"},Source={["b8be1b98d4d0823f:46"]="专业技能：附魔\n公式：魔化大锅"}}
D.ClientTexts.BattlePet[1700]={Description={["81dcdd435c4690b0:111"]="女巫斯塔佳不喜欢自己举火把。经过简单地附魔后，这玩意儿就会自己跟着她在黑夜中穿行了。"},Source={["80094880be717f3f:43"]="专业技能：附魔\n公式：魔化火把"}}
D.ClientTexts.BattlePet[1701]={Description={["994a909a0cf4dd35:154"]="女巫斯塔佳受够了写感谢纸条这个麻烦活，于是就用她的魔法来自动完成这个任务。不幸的是，这支笔内心阴暗，所有收信人都收到了一封措辞强硬的信……"},Source={["c4684fc3440a42fc:41"]="专业技能：附魔\n公式：魔化羽毛笔"}}
D.ClientTexts.BattlePet[1705]={Description={["55d5b283254f194a:31"]="你救了他，但也或许是他救了你。"},Source={["61f1f52c55f549dd:27"]="任务：不高兴\n地区：瓦尔莎拉"}}
D.ClientTexts.BattlePet[1706]={Description={["90e97ad192dbf6bc:63"]="这个小家伙从小过得十分艰苦，你一定要好好照顾他。"},Source={["dce5267942262f1a:40"]="任务：收养小可爱\n地区：瓦尔莎拉"}}
D.ClientTexts.BattlePet[1708]={Description={["93fe338dbb70ecdc:77"]="许多水手认为，伤害信天翁会给他们的航程带来霉运。"},Source={["2595a43a65f1e9cf:26"]="宠物对战：阿苏纳，风暴峡湾"}}
D.ClientTexts.BattlePet[1709]={Description={["5aea0c664db0c891:190"]="其他鸟类在成群迁徙的时候会轮流领航，但皇羽鹰却会一直保持领头的位置。这到底是为了帮助其他的鸟儿保存体力，还是出于支配欲就不得而知了。"},Source={["4107f456a586eb51:16"]="宠物对战：阿苏纳\n"}}
D.ClientTexts.BattlePet[1710]={Description={["477f8741e6f4c8b6:27"]="总是活在它兄弟的阴影里。"},Source={["4107f456a586eb51:16"]="宠物对战：阿苏纳\n"}}
D.ClientTexts.BattlePet[1711]={Description={["776bce63487c60d4:42"]="非常稀有的鸟类，不过这一只已经被托付给你了。"},Source={["07d5b27b980f44f0:32"]="任务：空荡荡的鹰巢\n地区：至高岭"}}
D.ClientTexts.BattlePet[1712]={Description={["f9d0c139e155f81a:80"]="这种鸟通常以乌龟为食，它们会从非常高的地方扔下乌龟，以摔碎其坚硬的外壳。"},Source={["69e29e3c775e43a7:19"]=S[8968]}}
D.ClientTexts.BattlePet[1713]={Description={["4beb8320a91f9013:34"]="它的视力好过听力。"},Source={["4e094ef38fea08b0:32"]=S[8961]}}
D.ClientTexts.BattlePet[1714]={Description={["9730c6ae5020ff29:47"]="锐利的眼神可以在暴雪之中认出一只雪兔。"},Source={["cb4f33cf56abacb2:22"]=S[8960]}}
D.ClientTexts.BattlePet[1715]={Description={["97f35e49ab2110c4:42"]="这种生物可以在近乎完全黑暗的环境中捕食。"}}
D.ClientTexts.BattlePet[1716]={Description={["14bbc02e71183d0d:32"]="一个年轻的伙伴，急需训练。"}}
D.ClientTexts.BattlePet[1717]={Description={["dc6619cde235f900:44"]="曾经是你的大敌，现在变成了可爱的朋友。"}}
D.ClientTexts.BattlePet[1718]={Description={["0b4dc1166f878429:21"]="你到底在看什么？！"},Source={["bb1452d814e62661:36"]="职业大厅：恐痕裂隙，邪能之槌号"}}
D.ClientTexts.BattlePet[1719]={Description={["7d8141c6e1704dd5:29"]="你好。你在找我吗？"},Source={["355b2cb62fbf5715:34"]="掉落：\n邪魂审判官\n地区：苏拉玛"}}
D.ClientTexts.BattlePet[1720]={Description={["a3ca98d05da2287b:55"]="塞纳苟斯的重重重重重孙女。"},Source={["df95da8d631771a0:27"]="任务：灭族危机\n地区：阿苏纳"}}
D.ClientTexts.BattlePet[1721]={Description={["74a9d8f145c99d64:58"]="它的鳞片带电，想抱抱它的话很不容易。"},Source={["31f4146722443d40:37"]="掉落：风暴之翼主母\n地区：风暴峡湾"}}
D.ClientTexts.BattlePet[1722]={Description={["ef2e6591fd211dda:66"]="沉睡的小宝贝啊，醒来吧，星光与露珠在等待着你。"},Source={["1801e1fe8f4febc9:29"]="宠物对战：\n翡翠梦魇"}}
D.ClientTexts.BattlePet[1723]={Description={["2fede90b28bcaa70:38"]="在朋友之间，一点小小的腐化又算什么？"},Source={["db66a628eca04931:36"]="掉落：伊森德雷\n地区：翡翠梦魇"}}
D.ClientTexts.BattlePet[1725]={Description={["a935a35228a6fbaf:73"]="被诱拐的孩子流下的泪水落在一簇新落的雪花上，就变成了格噜噜。"},Source={["d00fbada955d933f:28"]=S[811]}}
D.ClientTexts.BattlePet[1726]={Description={["c3368e421e1ac559:87"]="这只蜘蛛的前腿几乎坚不可摧，让它可以钻入大部分地面。"},Source={["cb4f33cf56abacb2:22"]=S[8960]}}
D.ClientTexts.BattlePet[1727]={Description={["eac9546446108607:123"]="它为什么叫做育儿蛛？它喜欢潜伏在托儿所里吗？它为什么喜欢那么做？它在那里做什么？噢，天啊！快来人去看看孩子们怎么样了！"}}
D.ClientTexts.BattlePet[1728]={Description={["3f40bee9210bae82:53"]="幼年指的是这只煤壳蟹的年纪，而不是它的成熟程度。"},Source={["1c301f4484640515:29"]="宠物对战：阿苏纳，艾萨拉之眼"}}
D.ClientTexts.BattlePet[1729]={Description={["2bd1cc1ad688cac3:54"]="绿尾这个名字有点不恰当，因为它全身都是棕色的……"},Source={["1c301f4484640515:29"]="宠物对战：阿苏纳，艾萨拉之眼"}}
D.ClientTexts.BattlePet[1730]={Description={["df01eadb1e2f3062:49"]="难道一个充斥着活蜘蛛的矿井还不够吓人吗？"},Source={["c67d612179a0f5bc:22"]="世界事件：万圣节\n"}}
D.ClientTexts.BattlePet[1731]={Description={["8ae1e55d8459a970:34"]="它就和普通的蜘蛛一样，只是充满了邪能而已。"},Source={["d16b610d76c5248a:29"]="宠物对战：阿苏纳、至高岭"}}
D.ClientTexts.BattlePet[1734]={Description={["1a2c8088325ef265:126"]="萤火虫在极为罕见的情况下会同步它们闪光的频率，营造出一幅异常壮观的景象，只有最幸运的冒险者才有机会一饱眼福。"},Source={["c9015245347d6b36:20"]=S[8955]}}
D.ClientTexts.BattlePet[1735]={Description={["23db2c108795e89d:98"]="恐魔幼虫正在寻找宿主，以蚕食他们的梦境和恐惧。它很快就会成为宿主最可怕的梦魇。"},Source={["c9015245347d6b36:20"]=S[8955]}}
D.ClientTexts.BattlePet[1736]={Description={["04d75544aaaafd8b:175"]="这些棕鳞蛇是非常温顺的生物。但是，因为它们可以与周围的环境融为一体，所以冒险者们很容易过分靠近它们的巢穴。其实大部分的攻击都是可以避免的。"},Source={["c3169167633d0b10:37"]="宠物对战：苏拉玛，风暴峡湾，瓦尔莎拉"}}
D.ClientTexts.BattlePet[1737]={Description={["63f5b6096c1e7b56:93"]="谷地飞蛾的寿命一般都很长——直到人们发现可以用它们进行宠物对战为止。"},Source={["c9015245347d6b36:20"]=S[8955]}}
D.ClientTexts.BattlePet[1738]={Description={["1cbd163235644bf1:64"]="到底是棕色的尾巴上有三道白色条纹呢，还是白色的尾巴上有两道棕色条纹？"},Source={["c9015245347d6b36:20"]=S[8955]}}
D.ClientTexts.BattlePet[1739]={Description={["e4a0e8356be8284c:47"]="它在泉水里会发出最耀眼的光芒，因此得名泉眼水黾。"},Source={["c9015245347d6b36:20"]=S[8955]}}
D.ClientTexts.BattlePet[1740]={Description={["2772e0c3b3f14562:51"]="活的蛆虫会吃死尸，那亡灵蛆虫吃什么呢？"},Source={["c67d612179a0f5bc:22"]="世界事件：万圣节\n"}}
D.ClientTexts.BattlePet[1741]={Description={["d5962e669d7a4a45:42"]="迄今为止散播亡灵瘟疫的最佳方式。"},Source={["c67d612179a0f5bc:22"]="世界事件：万圣节\n"}}
D.ClientTexts.BattlePet[1743]={Description={["ae7907abb2bdfd96:41"]="它的脚抓住猎物后通常都会被染成红色。"},Source={["4e094ef38fea08b0:32"]=S[8961]}}
D.ClientTexts.BattlePet[1744]={Description={["be77da8b8a82b8a0:46"]="它会像雾气一般安静而神秘地消失。"},Source={["4e094ef38fea08b0:32"]=S[8961]}}
D.ClientTexts.BattlePet[1749]={Description={["f4cd1672750edbc5:36"]="你看到的最后一个画面将是一道红色的条纹。"},Source={["69e29e3c775e43a7:19"]=S[8968]}}
D.ClientTexts.BattlePet[1750]={Description={["ee1655de744edd13:23"]="它不但不可怕，反而很可爱。"},Source={["69e29e3c775e43a7:19"]=S[8968]}}
D.ClientTexts.BattlePet[1751]={Description={["b39d1cb3be7c35ac:19"]="有其父，必有其子。"},Source={["7b4f0d79df34e6d8:32"]="掉落：血角之子\n地区：风暴峡湾"}}
D.ClientTexts.BattlePet[1752]={Description={["3e75fae091f23c83:45"]="很奇怪，它在那件事发生之前就叫脆脆了。"},Source={["03b5d846c54b9aa7:38"]="掉落：坦帕克·烈焰图腾\n地区：至高岭"}}
D.ClientTexts.BattlePet[1753]={Description={["38cfd8d1ec548f58:89"]="如果冥界鱿鱼吃掉区域里的大部分食物，那么它就可以回归螅虫形态，然后重新开始它的一生。"},Source={["fbc1fc7e9516bf0b:29"]="掉落：吸魂者\n地区：冥狱深渊"}}
D.ClientTexts.BattlePet[1754]={Description={["554fa9148b1d9b51:39"]="达拉然的排水系统并没有你想象得那么好。"}}
D.ClientTexts.BattlePet[1755]={Description={["6ae702c10ae9c53e:62"]="只要被它的触手抓住了，那不管你怎么挣扎也逃不掉，就像被它的爱套牢了一样。"}}
D.ClientTexts.BattlePet[1756]={Description={["2b95f2d8646a49b9:47"]="他喜欢玩泥巴！他也喜欢拥抱你！"},Source={["822f778afa1270e3:18"]="专业技能：炼金术"}}
D.ClientTexts.BattlePet[1757]={Source={["5fbe9f043826e943:10"]="宠物对战："}}
D.ClientTexts.BattlePet[1758]={Source={["5fbe9f043826e943:10"]="宠物对战："}}
D.ClientTexts.BattlePet[1759]={Description={["95800b186d50ef03:34"]="这配方有点太……紫了。"},Source={["822f778afa1270e3:18"]="专业技能：炼金术"}}
D.ClientTexts.BattlePet[1760]={Description={["b3c115f5179e94d8:83"]="就连小猪也逃不过燃烧军团的腐蚀。不过，这一只看起来不像是有害的样子。"}}
D.ClientTexts.BattlePet[1761]={Description={["93f091ce06ba36f5:49"]="大多数蝙蝠都有视力，除了这一只。这一只是瞎的。"},Source={["cb4f33cf56abacb2:22"]=S[8960]}}
