D.ClientTexts.BattlePet[2004]={Description={["8dc27dd5a529e8a2:36"]="你是怎么干掉生活在垃圾堆里的家伙的？"}}
D.ClientTexts.BattlePet[2017]={Description={["df61917cbec66e63:69"]="永恒龙军团有丰富的多样性，远超大部分艾泽拉斯居民的想象。"}}
D.ClientTexts.BattlePet[2018]={Description={["0bf45505255b21be:43"]="它是包裹在神秘谜团中的谜团。"}}
D.ClientTexts.BattlePet[2022]={Description={["206de7d775aa4530:48"]="一个可怕的梦魇，你很惊讶它居然是真实存在的。"}}
