D.ClientTexts.BattlePet[2086]={Description={["80b7c2ee7791dd03:76"]="有人说它是裂肢和狂脸的后代，也有人说“我都不愿意去想那种可能性。”"},Source={["005c52c11fe8904e:26"]="掉落：沙恩诺克斯\n地区：火焰之地"}}
D.ClientTexts.BattlePet[2087]={Description={["d75179ea9c802529:118"]="一种非常少见的烬网蜘蛛，她会吃掉配偶的腿，把卵产在对方还在抽搐的身体里，而且是可爱的紫色。"},Source={["e4762a59bb9af638:29"]="掉落：贝丝缇拉克\n地区：火焰之地"}}
D.ClientTexts.BattlePet[2088]={Description={["dd915915f97d5f94:70"]="他永远都无法放弃的五件事：冲浪、冲浪、冲浪、冲浪、冲浪。"},Source={["2a94245a20ffd5c7:26"]="掉落：贝尔洛克\n地区：火焰之地"}}
D.ClientTexts.BattlePet[2089]={Description={["6e1a3f91ac3904b4:97"]="在火焰之地生活期间，范达尔常常觉得无聊，就对当地的动植物施展了塑形魔法。"},Source={["ad40a61f308e7364:36"]="掉落：管理者鹿盔\n地区：火焰之地"}}
D.ClientTexts.BattlePet[2090]={Description={["937df4d21f6a6893:67"]="并不能控制你的心智，但会让你患上严重的偏头痛。"},Source={["315f9baa928d6a45:41"]="掉落：不眠的约萨希\n地区：巨龙之魂"}}
D.ClientTexts.BattlePet[2091]={Description={["57dd5aab8e1283fe:109"]="死亡之翼残留的部分鲜血一直活到了今天，在早已被遗忘的世界深处不断寻找着它们早已逝去的宿主。"},Source={["b2cc2171a80ac994:33"]="宝藏：守护巨龙的大型宝箱"}}
D.ClientTexts.BattlePet[2092]={Description={["be04ab44499b3cd1:25"]="它的朋友们都叫它“拍拍”。"},Source={["ddb284f34db1a820:27"]="宝藏：源质碎片\n"}}
D.ClientTexts.BattlePet[2093]={Description={["08036ab878022879:123"]="灌注了用于武装巨龙死亡之翼的源质矿石，那场疯狂的最后一点余波差点吞噬了艾泽拉斯。"},Source={["eb13acef4e4e76f6:58"]="成就：缰绳来袭V：萌物的裂变\n分类：收集"}}
D.ClientTexts.BattlePet[2113]={Description={["f27f7564d77f1b63:94"]="阿古斯的多数魔鼠都是以水果为食，但这只魔鼠却喜欢嘎嘣脆的啮齿动物。"},Source={["5aaeec475034f2a6:40"]="成就：全谱系战神\n类型：对战"}}
D.ClientTexts.BattlePet[2114]={Description={["c8da7c2bc3d77650:71"]="是谁创造了它们？它们是怎么到这里来的？也许只有冬天爷爷才知道。"},Source={["d00fbada955d933f:28"]=S[811]}}
D.ClientTexts.BattlePet[2115]={Description={["d5152b91c7f2afac:36"]="我总感觉有人在看着我。"}}
D.ClientTexts.BattlePet[2116]={Description={["c221a00a0682590b:68"]="其实它的父母还在。取这个名字只是为了减轻你捕捉它时的负罪感。"}}
D.ClientTexts.BattlePet[2117]={Description={["7e48285ae744cfd7:19"]="美丽且致命。"},Source={["f9e73f3eb9ae0f2d:20"]="专业技能：草药学"}}
D.ClientTexts.BattlePet[2118]={Description={["0b85db10c251a255:120"]="经过观察发现，天鳍鳐有很多种颜色。生物学家相信这些丰富的色彩有助于吸引伴侣和警告掠食者。"},Source={["83c4834e4ec2399f:19"]="掉落：邪斑鱼卵"}}
D.ClientTexts.BattlePet[2119]={Description={["79427f64223428a7:20"]="当心它吐的口水。"},Source={["83c4834e4ec2399f:19"]="掉落：邪斑鱼卵"}}
D.ClientTexts.BattlePet[2120]={Description={["4dbafbadf269a078:62"]="从虚空的某个未知的广大角落伸出来……给你一个拥抱。"},Source={["4d33400a93e77803:24"]="掉落：阿塔克松\n地区：玛凯雷"}}
D.ClientTexts.BattlePet[2121]={Description={["2a62f55154ceb8ea:125"]="如果灾怨幼虫在地下待的时间过长，它们就会渐渐褪色。破土而出后，它们还会变得非常贪食。"},Source={["2635880859cef0af:19"]="专业技能：剥皮"}}
D.ClientTexts.BattlePet[2122]={Description={["82ce8f48760e6fbf:48"]="因为太靠近安托鲁斯，这些幼虫变得极其凶狠。"},Source={["3409faae1b217e2d:23"]="宠物对战：安托兰废土\n"}}
D.ClientTexts.BattlePet[2123]={Description={["f04e9f4d0ae075cc:38"]="灾怨蝇生命循环的早期阶段。"},Source={["50d5dc93765ffe68:17"]=S[8940]}}
D.ClientTexts.BattlePet[2124]={Description={["22a9f469cfe0317a:39"]="灾怨蝇生命循环的最终阶段。"},Source={["50d5dc93765ffe68:17"]=S[8940]}}
D.ClientTexts.BattlePet[2126]={Description={["83fbad14f2752d7d:121"]="灾怨蝇多数情况下是以燃烧军团的受害者的尸骸为食。但是，你们到来后，它也逐渐喜欢上了恶魔的尸骸。"},Source={["3409faae1b217e2d:23"]="宠物对战：安托兰废土\n"}}
D.ClientTexts.BattlePet[2127]={Description={["b93ddcfb450b0c80:40"]="从阿古斯泽尼达尔的坠毁点诞生。"},Source={["50d5dc93765ffe68:17"]=S[8940]}}
D.ClientTexts.BattlePet[2128]={Description={["04bf162baff806c4:135"]="虽然与艾泽拉斯的迁跃兽有很多相似之处，但有证据表明，二者其实拥有完全独立的进化过程。真是神奇！"},Source={["069fa0f97467de0c:18"]=S[8954]}}
D.ClientTexts.BattlePet[2129]={Description={["aceb7727b276036e:75"]="虚空能吞噬生命，或者与生命融为一体。后者经常会产生未预见的后果。"},Source={["069fa0f97467de0c:18"]=S[8954]}}
D.ClientTexts.BattlePet[2130]={Description={["d2231cadbc4a60e2:41"]="你有种奇怪的感觉：它想杀死你。"},Source={["069fa0f97467de0c:18"]=S[8954]}}
D.ClientTexts.BattlePet[2131]={Description={["7cac75bcdbc60d19:83"]="数千年前，法力浮龙的种群曾经非常繁盛，但和平的日子已经一去不复返。"},Source={["069fa0f97467de0c:18"]=S[8954]}}
D.ClientTexts.BattlePet[2132]={Description={["6838feeba36634fa:64"]="如果法力太过稀少，这些浮龙就会去寻找其他能量源。"},Source={["069fa0f97467de0c:18"]=S[8954]}}
D.ClientTexts.BattlePet[2133]={Description={["ef274853cfb74f92:31"]="它很喜欢背鳍后面被抚摸的感觉。"},Source={["069fa0f97467de0c:18"]=S[8954]}}
D.ClientTexts.BattlePet[2134]={Description={["04834350ffc5faa9:79"]="天鳍鳐一出生就会飞了，有人甚至看到过天鳍鳐妈妈一边飞一边生宝宝！"},Source={["069fa0f97467de0c:18"]=S[8954]}}
D.ClientTexts.BattlePet[2135]={Description={["771a293ee0de2911:76"]="他们背叛了什么？你该问的是他们没有背叛什么。"},Source={["59335159d2185c62:17"]="掉落：主母罗苏拉"}}
D.ClientTexts.BattlePet[2136]={Description={["acf33b8080bdc09b:96"]="尤娜被束缚到一只乌祖尔身上，后来被释放到了暗影界，在黑暗中徘徊。"},Source={["8bb903d60fbe02c3:26"]="掉落：千面吞噬者"}}
D.ClientTexts.BattlePet[2158]={Description={["0e2f60aa3538e037:213"]="邮政长在传说中通常是神奇、机密，甚至无法解释的存在。对于这位隐秘的邮件大师，我们的所知极少，如果没有蜡印，我们甚至都不知道还有喜欢邮件的邮件元素的存在。"},Source={["2e19ef4daa9f1fa6:24"]="成就：紧急邮件\n"}}
D.ClientTexts.BattlePet[2163]={Description={["bd17b750451258e3:107"]="这只异种蝎作战坦克过早进入了进化成熟期，它永远无法长到成虫大小，但它的凶残程度与其大型表亲相比不遑多让。"},Source={["7ad786117930e0ac:22"]="掉落：希利苏斯：创伤之痕"}}
